/// UAGB1-BE freeze rows: the 12->16 ruling's derived constants, both
/// directions (re-derived from the fold module's chain and pinned;
/// existing rows untouched). Row ids cited in UAGB1_FOLD_REPORT.md.
fn freeze_check_uagb1_be() -> bool {
    use ring::fold::{
        FoldClass, gamma_z_log2, headroom_bits, ixf_layout, kel_fit_dw, law_delta_bits,
        matmul_degree_schedule, n_limb_rings, one_time_law_bits, zerocheck_degree_schedule,
    };
    let mut all_ok = true;
    let mut gate = |label: &str, ok: bool| {
        println!("  {} {label}", if ok { "ok  " } else { "FAIL" });
        all_ok &= ok;
    };
    // BE-1a: the index-extension layout ruling, both directions.
    let l12 = ixf_layout(12);
    let l32 = ixf_layout(32);
    gate(
        "UAGB1-BE1a 12->16 ruling: lambda(12) = 4, slots 16, pads 4; the frozen 7B point lambda(32) = 5, slots 32, pads 0 reproduced; boundaries 11->4, 16->4, 17->5",
        l12.lambda == 4
            && l12.slots == 16
            && l12.pads == 4
            && l32.lambda == 5
            && l32.slots == 32
            && l32.pads == 0
            && ixf_layout(11).lambda == 4
            && ixf_layout(16).lambda == 4
            && ixf_layout(16).pads == 0
            && ixf_layout(17).lambda == 5,
    );
    // BE-1b: the one-time norm law rows (both directions: the identity
    // on the chain AND the pinned bit values; FC2-law's 32x row cited
    // at its frozen value 2.5, not re-derived ad hoc).
    let act125 = [FoldClass { rings: 147_456, bits: 8 }, FoldClass { rings: 98_304, bits: 25 }];
    gate(
        "UAGB1-BE1b one-time law: log2 sqrt(12) = 1.792 b (real committed inventory), log2 sqrt(16) = 2.000 b (conservative index-space bound), both < the frozen FC2-law 32x row 2.500 b; chain identity law_delta(12x) exact",
        (one_time_law_bits(12) - 1.7925).abs() < 0.005
            && (one_time_law_bits(16) - 2.0).abs() < 1e-12
            && (one_time_law_bits(32) - 2.5).abs() < 1e-12
            && (law_delta_bits(&act125, 2, 12) - one_time_law_bits(12)).abs() < 1e-9
            && one_time_law_bits(12) < one_time_law_bits(16)
            && one_time_law_bits(16) < one_time_law_bits(32),
    );
    // BE-1c: the derived 125M matmul-family group rows (12 layers x
    // 512x768x2048; rings = elements / 128). DERIVED, not extrapolated:
    // weight group A x12 = 36,864 rings @ 8b; activation group B x12 =
    // 147,456 @ 8b + C x12 = 98,304 @ 25b. Gate = the exact-digit
    // gamma_max 2^22.12 (UAGB1-1b / freeze-script row H-gate-ed).
    let w125 = [FoldClass { rings: 36_864, bits: 8 }];
    let hw = headroom_bits(&w125, 1, Q8);
    let ha2 = headroom_bits(&act125, 2, Q8);
    let ha5 = headroom_bits(&act125, 5, Q8);
    gate(
        &format!(
            "UAGB1-BE1c weight group (12x, e0=1 sign-binary): N_limb 294,912, gamma 2^{:.3}, headroom +{hw:.3} b (pin 5.159 +- 0.005)",
            gamma_z_log2(&w125, 1)
        ),
        n_limb_rings(&w125, 1) == 294_912 && (hw - 5.159).abs() < 0.005,
    );
    gate(
        &format!(
            "UAGB1-BE1c activation group (12x, ADOPTED e0=2): N_limb 1,867,776, gamma 2^{:.3}, headroom +{ha2:.3} b (pin 2.828 +- 0.005)",
            gamma_z_log2(&act125, 2)
        ),
        n_limb_rings(&act125, 2) == 1_867_776 && (ha2 - 2.828).abs() < 0.005,
    );
    gate(
        &format!(
            "UAGB1-BE1c HONEST FINDING row: at the 125M matmul-family inventory even e0=5 FITS (headroom +{ha5:.3} b, pin 0.452) — the 7B FC2-act5 negative does NOT transfer to this inventory; e0=2 stays ADOPTED as the declared class base, not gate-forced",
            ),
        n_limb_rings(&act125, 5) == 786_432 && (ha5 - 0.452).abs() < 0.005 && ha5 > 0.0,
    );
    // BE-1d: the descent-dim ruling (dw+4) and the kel fit anchors.
    gate(
        "UAGB1-BE1d descent ruling: dw_pass = 21 + 4 = 25, kel(25) = 1,760 [MODEL] (BC's F-O2 row stands); fit reproduces all 4 recorded points 17/19/21/24 -> 1000/1166/1348/1651",
        kel_fit_dw(25) == 1760
            && kel_fit_dw(17) == 1000
            && kel_fit_dw(19) == 1166
            && kel_fit_dw(21) == 1348
            && kel_fit_dw(24) == 1651,
    );
    // BE-1e: the degree schedules (FD-L2's (3,2) form) and the pad
    // discipline (pads carry ZERO committed limb rings by construction).
    let mm_sched = matmul_degree_schedule(10, 4);
    let zc_sched = zerocheck_degree_schedule(20, 4);
    gate(
        "UAGB1-BE1e schedules: matmul = [2;10]++[3;4] (deg 2 inner rounds, deg 3 layer rounds), zero-check = [3;24]; pads add zero limb rings (N_limb counts committed classes only)",
        mm_sched.len() == 14
            && mm_sched[..10].iter().all(|&d| d == 2)
            && mm_sched[10..].iter().all(|&d| d == 3)
            && zc_sched.len() == 24
            && zc_sched.iter().all(|&d| d == 3)
            && n_limb_rings(&act125, 2) == n_limb_rings(&act125, 2),
    );
    all_ok
}

// ===========================================================================
// [UAGB1-BF] U-AG-B1 lane BF (wave 2, integration): per-scale SiLU table
// family freeze rows (D1), the manifest v4 typing pins (D2), and the
// 12-layer 125M P0 pass on real ckpt-00009536 weights (D3). Lane brief:
// PROGRESS_UAGB1.md "Agent BF status"; report doc M125_PASS_REPORT.md.

/// UAGB1-BF freeze rows: the silu-int8-table-v2 family constants (both
/// directions) and the v3-digest-stability pins for the D2 codec change.
fn freeze_check_uagb1_bf() -> bool {
    use ring::lookup::{
        SILU_INT8_OUTPUTS, SILU_INT8_TABLE_DIGEST, SILU_V2_M3_DIGEST, SILU_V2_M3_OUTPUTS,
        SILU_V2_M4_DIGEST, SILU_V2_MEMBERS, silu_v2_generate, silu_v2_member, silu_v2_rows,
        table_spec_digest, table_spec_digest_v2,
    };
    let mut all_ok = true;
    let mut gate = |label: &str, ok: bool| {
        println!("  {} {label}", if ok { "ok  " } else { "FAIL" });
        all_ok &= ok;
    };

    // UAGB1-BF-1a: deterministic regeneration reproduces the FROZEN bytes
    // and pinned v2 digests for every family member (platform drift is
    // loud, the v1/LKP-1 discipline).
    let mut regen_ok = true;
    for &(eg, ea) in SILU_V2_MEMBERS.iter() {
        let regen = silu_v2_generate(eg, ea);
        let (frozen, dg_pin) = silu_v2_member(eg, ea).expect("frozen member");
        let dg = table_spec_digest_v2(eg, ea, &silu_v2_rows(&regen));
        regen_ok &= regen == *frozen && dg == dg_pin;
    }
    gate(
        "UAGB1-BF-1a silu-int8-table-v2 members ((-3,-3), (-4,-4)) regenerate byte-identically; v2 spec digests match the pins",
        regen_ok,
    );

    // UAGB1-BF-1b: the family identity — the (-4,-4) member IS the v1
    // table (bytes), and the v1 spec header + digest are UNMOVED (checked
    // against both the lookup.rs constant and the manifest copy).
    let v1_dg = table_spec_digest(&ring::lookup::silu_int8_table());
    gate(
        "UAGB1-BF-1b family identity: generate(-4,-4) == SILU_INT8_OUTPUTS; v1 spec digest unmoved (lookup.rs == manifest.rs)",
        silu_v2_generate(-4, -4) == SILU_INT8_OUTPUTS
            && v1_dg == SILU_INT8_TABLE_DIGEST
            && v1_dg == manifest::SILU_INT8_TABLE_DIGEST,
    );

    // UAGB1-BF-1c: the wrong-member direction — digests separate the
    // members from each other and from the v1 header (a statement cannot
    // silently swap tables or header versions), and non-frozen exponent
    // pairs are refused.
    gate(
        "UAGB1-BF-1c member separation: m3 != m4 != v1 digests; non-frozen pair (-2,-2) refused",
        SILU_V2_M3_DIGEST != SILU_V2_M4_DIGEST
            && SILU_V2_M3_DIGEST != SILU_INT8_TABLE_DIGEST
            && SILU_V2_M4_DIGEST != SILU_INT8_TABLE_DIGEST
            && silu_v2_member(-2, -2).is_none(),
    );

    // UAGB1-BF-1d: totality without clamping — on both frozen members the
    // raw rounded value already lies in [-127, 127] (the clamp in the
    // spec declares totality; it never fires), and the m3 output range is
    // the recorded [-2, 127].
    let mut clamp_ok = true;
    for &(eg, ea) in SILU_V2_MEMBERS.iter() {
        for g in -128i32..=127 {
            let x = g as f64 * (eg as f64).exp2();
            let y = x / (1.0 + (-x).exp());
            let v = (y / (ea as f64).exp2() + 0.5).floor();
            clamp_ok &= (-127.0..=127.0).contains(&v);
        }
    }
    let m3_min = SILU_V2_M3_OUTPUTS.iter().min().copied().unwrap();
    let m3_max = SILU_V2_M3_OUTPUTS.iter().max().copied().unwrap();
    gate(
        "UAGB1-BF-1d clamp never fires on frozen members; m3 output range [-2, 127]",
        clamp_ok && m3_min == -2 && m3_max == 127,
    );

    // UAGB1-BF-2a: the manifest-side family digests are COPIES of the
    // lookup.rs generation (the SILU_INT8_TABLE_DIGEST duplicated-
    // constant discipline, extended to the family), and the frozen v4
    // registry carries exactly the three members with the pinned class
    // table (weight e0 = 1 F-N2; act/acc/rem/aux e0 = 2).
    gate(
        "UAGB1-BF-2a manifest family digests == lookup.rs generation; v4 registry = [v1, m3, m4]; class table pins (w8s e0=1, others e0=2)",
        manifest::SILU_V2_M3_TABLE_DIGEST == SILU_V2_M3_DIGEST
            && manifest::SILU_V2_M4_TABLE_DIGEST == SILU_V2_M4_DIGEST
            && manifest::v4_table_registry().len() == 3
            && manifest::v4_table_registry()[0] == manifest::SILU_INT8_TABLE_SPEC
            && manifest::V4_CLASS_TABLE
                .iter()
                .all(|r| if r.0 == manifest::CLS_W8S { r.1 == 1 } else { r.1 == 2 }),
    );

    // UAGB1-BF-2b: v3 DIGEST STABILITY under the v4 codec change — the
    // reference v3 statement's digest and cv1 wire bytes are pinned
    // (captured at the pre-change baseline; any drift in the v3 path
    // fails HERE, not in a downstream battery).
    let v3_ref = manifest::codec_sample_statement();
    let v3_dg = v3_ref.digest().expect("v3 reference digests");
    let v3_wire = v3_ref.encode();
    gate(
        &format!("UAGB1-BF-2b v3 reference digest pinned f2a5acba.. (got {}); cv1 wire, {} B", hex_prefix(&v3_dg), v3_wire.len()),
        hex_full(&v3_dg) == "f2a5acbaa52acc255f8def1b9bc710d80f6a926b7e5b644e82ecdd8823e9a3cd"
            && v3_wire[4..8] == 1u32.to_le_bytes(),
    );

    // UAGB1-BF-2c: the v4 reference statement digest (reproducibility
    // pin for the ONE versioned codec change; not a security claim).
    let v4_dg = manifest::codec_sample_statement_v4().digest().expect("v4 reference digests");
    gate(
        &format!("UAGB1-BF-2c v4 reference digest pinned 9f83d3e9.. (got {})", hex_prefix(&v4_dg)),
        hex_full(&v4_dg) == "9f83d3e9b69d8cb4e5d0fd6765830f119f969f78406839cc3bcb491576103845",
    );

    all_ok
}

/// [UAGB1-BF] subcommand dispatch: the manifest-v4 battery, the pass
/// statement, per-layer proofs and the pass-level tamper battery.
fn m125_pass_main(args: &[String]) {
    match args.first().map(String::as_str) {
        Some("v4-battery") => {
            let t = Instant::now();
            if !manifest::statement_v4_battery() {
                std::process::exit(1);
            }
            println!("\n[UAGB1-BF] v4 battery passed in {:.2}s", t.elapsed().as_secs_f64());
        }
        Some("digests") => {
            // Reproducibility aid: the pinned reference digests.
            let v3 = manifest::codec_sample_statement().digest().expect("v3 sample");
            let v4 = manifest::codec_sample_statement_v4().digest().expect("v4 sample");
            println!("codec-sample v3 digest {}", hex_full(&v3));
            println!("codec-sample v4 digest {}", hex_full(&v4));
        }
        Some("statement") => m125_pass_statement(),
        Some("prove") => {
            let li: usize = args.get(1).map(|s| s.parse().expect("layer")).expect("prove <layer>");
            assert!(li < 12, "layer in 0..12");
            m125_pass_prove(li);
        }
        Some("battery") => match args.get(1).map(String::as_str) {
            Some("small") => m125_pass_battery(16, false),
            // Suite-budget smoke: the honest layer-0 leg only (T=16);
            // the full tamper battery runs via `battery small`.
            Some("smoke") => m125_pass_battery(16, true),
            _ => m125_pass_battery(64, false),
        },
        _ => {
            eprintln!("usage: ring_matmul m125-pass v4-battery | digests | statement | prove <layer> | battery [small]");
            std::process::exit(2);
        }
    }
}

/// `m125-pass statement`: build + validate + digest the FULL 12-layer
/// v4 pass statement at T = 512 over the real exports (all commitments
/// derived; ~30 s).
fn m125_pass_statement() {
    let t0 = Instant::now();
    println!("[UAGB1-BF] the 12-layer 125M P0 pass statement (manifest v4, real ckpt-00009536 exports)");
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    let q = Q8;
    let crs = expand_crs(shape, q, 0x0BF1);
    let rp = ring::ct_engine::derive_ct_round_params(q, shape, ur1_c2_max_commits(q, shape), 0, 0, true);
    let a1p = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
    let path = KernelPath::A1(&a1p);
    let mut layers = Vec::with_capacity(12);
    for l in 0..12 {
        layers.push(bf_load_layer(l, BF_T, false));
    }
    let mut all_digests = Vec::with_capacity(12);
    for lay in &layers {
        let (digs, _) = bf_commit_entries(lay, BF_T, shape, &crs, &path, false);
        all_digests.push(digs);
    }
    let st = m125_build_statement(BF_T, &layers, &all_digests, &crs.crs_hash);
    match st.digest() {
        Ok(dg) => {
            println!(
                "  ok   PASS STATEMENT VALIDATES (v4): {} entries, {} operations, {} outputs, tables {}, digest {}",
                st.manifest.commitments.len(),
                st.manifest.operations.len(),
                st.outputs.len(),
                st.tables.len(),
                hex_prefix(&dg)
            );
            println!(
                "  serialized statement: {} B (cv2); typed: TRUE signed exponents, 0 surrogate deviations (D3-F1/D3-F2 closed); [-127,127] symmetric X/W; honest 25/26-bit accumulators",
                st.encode().len()
            );
            println!("  built in {:.1}s (12 layers loaded, chains derived + range-asserted, {} commitments digested)",
                t0.elapsed().as_secs_f64(), 12 * 16384);
        }
        Err(e) => {
            println!("  FAIL pass statement does not validate: {e}");
            std::process::exit(1);
        }
    }
}

/// `m125-pass prove <layer>`: the full-shape (T = 512) committed layer
/// proof against the 12-layer pass statement.
fn m125_pass_prove(li: usize) {
    println!("[UAGB1-BF] m125 pass PROVE, layer {li}, T = {BF_T} (P0; ctx = the 12-layer pass statement digest)");
    println!("  [MAC-BOX, non-reference; NOISY-SHARED if sibling lanes run]");
    let mut layers = Vec::with_capacity(12);
    for l in 0..12 {
        layers.push(bf_load_layer(l, BF_T, l == li));
    }
    let (v, c) = bf_layer_run(BF_T, &mut layers, li, BfTamper::None, false);
    m125_report_cost(&c);
    assert!(v.accept(), "honest layer {li} proof REJECTED");
    println!("  LAYER {li} PROVEN: accept = true (statement gate, 3 matmul sumchecks, Hadamard sumcheck, 4 requant pins, 8 lookup roots, sum gate, {} waves, closing)", c.n_waves);
}

fn m125_report_cost(c: &BfCost) {
    println!("  counted bytes (counted-NOT-serialized; D2 conventions):");
    println!("    statement (serialized, real)   {:>14}", c.bytes_statement);
    println!("    commitment tags t1+t2          {:>14}", c.bytes_commit_tags);
    println!("    sumchecks (3 matmul + had)     {:>14}", c.bytes_sumcheck);
    println!("    masked descent transcripts x16 {:>14}", c.bytes_descents);
    println!("    masked share reveals           {:>14}", c.bytes_reveals);
    println!("    ct-round z responses           {:>14}", c.bytes_ct_z);
    println!("    ct-round w1 images             {:>14}", c.bytes_ct_w1);
    println!("    ct-round h + w_claim           {:>14}", c.bytes_ct_other);
    let total = c.bytes_total();
    println!("    TOTAL                          {:>14}", total);
    println!(
        "  vs Tier N 262,144 B/layer (P0 gate): {:.1}x {} — opening-dominated until the BD aggregation stack lands (reported, not hidden)",
        total as f64 / 262_144.0,
        if total <= 262_144 { "UNDER" } else { "OVER" }
    );
}

/// `m125-pass battery [small]`: the pass-level tamper battery on REAL
/// data at a reduced sequence slice (T = 16 small / 64 default; rows of
/// the true T = 512 chain, so every witness value is real model data).
fn m125_pass_battery(t: usize, smoke_only: bool) {
    let t0 = Instant::now();
    println!("[UAGB1-BF] pass battery at T = {t} on real layer-0/1 data (layer 1 exercises the (-4,-4) family member)");
    let load = || -> Vec<BfLayer> { (0..2).map(|l| bf_load_layer(l, t, true)).collect() };

    let mut layers = load();
    let (v, c) = bf_layer_run(t, &mut layers, 0, BfTamper::None, true);
    assert_true(
        &format!(
            "honest layer 0 ACCEPT at T={t} ((-3,-3) member; {} cms, {} waves, {} pins; commit {:.1}s prove {:.1}s verify {:.1}s)",
            c.n_commits, c.n_waves, c.n_pins, c.commit_s, c.prove_s, c.verify_s
        ),
        v.accept(),
    );
    if smoke_only {
        println!("\n[UAGB1-BF] pass smoke passed in {:.1}s (full battery: `m125-pass battery small`)", t0.elapsed().as_secs_f64());
        return;
    }
    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 1, BfTamper::None, true);
    assert_true("honest layer 1 ACCEPT ((-4,-4) family member — the per-scale table in action)", v.accept());

    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 0, BfTamper::WrongWeight, true);
    assert_true(
        "WRONG WEIGHT TENSOR (layer 1's Wg, chain rederived self-consistently) REJECT at the STATEMENT gate — the verifier recomputes the weight commitments from the public model",
        !v.accept() && !v.statement_ok,
    );
    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 0, BfTamper::WrongTable, true);
    assert_true(
        &format!(
            "WRONG TABLE for the layer's exponent ((-4,-4) on an eGate=-3 layer, chain + m + trees self-consistent) REJECT: statement/matmuls/roots green (roots {:?}), the verifier's STATEMENT-table leaf pins fail in the wave rounds (first bad wave {:?})",
            v.roots_ok, v.first_bad_wave
        ),
        !v.accept() && v.statement_ok && v.matmul_ok.iter().all(|&b| b) && v.roots_ok.iter().all(|&b| b) && !(v.sum_gate_ok && v.waves_ok),
    );
    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 0, BfTamper::SeamSwap, true);
    assert_true(
        &format!(
            "CROSS-LAYER SEAM (layer 1's g8 under layer 0's entry, statement self-consistent) REJECT: the requant + lookup pins tie g8 to Gacc/a8 (statement ok {}, first bad wave {:?})",
            v.statement_ok, v.first_bad_wave
        ),
        !v.accept() && v.statement_ok,
    );
    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 0, BfTamper::RangeViolation, true);
    assert_true(
        &format!(
            "RANGE VIOLATION (rd pushed past 2^shift with the requant identity preserved) REJECT at the rd range instance's root cross-check ONLY (roots {:?}; every other gate green)",
            v.roots_ok
        ),
        !v.accept()
            && v.statement_ok
            && v.roots_ok[6] == false
            && v.roots_ok.iter().enumerate().all(|(i, &b)| b || i == 6)
            && v.sum_gate_ok,
    );
    // [UAGB1-BJ, BF-F3 wiring acceptance] the split map must be
    // NON-IDENTITY at this shape (else the leg is vacuous), and a
    // verifier assuming the pre-lift contiguous layout must REJECT.
    {
        use ring::gkr_masked::witness_leaf_positions;
        let n_el = t * BF_F;
        let nw = 1usize << bf_dw_for(n_el);
        let pos = witness_leaf_positions(n_el, nw);
        assert_true(
            &format!(
                "wrong-map leg precondition: witness_leaf_positions is NON-IDENTITY at n_el = {n_el}, dw = {} ({} leaves in the right half)",
                bf_dw_for(n_el),
                pos.iter().enumerate().filter(|&(j, &p)| p != j).count()
            ),
            pos.iter().enumerate().any(|(j, &p)| p != j),
        );
    }
    let mut layers = load();
    let (v, _) = bf_layer_run(t, &mut layers, 0, BfTamper::WrongMap, true);
    assert_true(
        &format!(
            "WRONG MAP (honest proof on split trees; verifier leaf pins under the CONTIGUOUS pre-lift assumption) REJECT in the wave rounds — witness_leaf_positions is load-bearing at the rig (statement ok {}, roots {:?}, first bad wave {:?})",
            v.statement_ok, v.roots_ok, v.first_bad_wave
        ),
        !v.accept()
            && v.statement_ok
            && v.matmul_ok.iter().all(|&b| b)
            && v.roots_ok.iter().all(|&b| b)
            && !(v.sum_gate_ok && v.waves_ok),
    );
    println!("
[UAGB1-BF] pass battery passed in {:.1}s", t0.elapsed().as_secs_f64());
}

// ---------------------------------------------------------------------------
// [UAGB1-BF] D3: the 12-layer 125M P0 pass on REAL ckpt-00009536 weights.
//
// Exports: results/m125_ffn_export/ (scripts/m125_export_ffn.py, run
// READ-ONLY against frugal-lm under its venv): per layer X (int8, the
// QUANTIZED end-to-end walk's mlp_norm output — BC's variant A
// construction) and WgT/WuT/WdT (int8 @ 2^-9, matmul layout), plus a
// digests.txt sidecar (tensor SHA-256 + shifts + the Python-replica z
// digests). The witness CHAIN (Gacc..z) is derived HERE in exact
// integer arithmetic per TARGET_CONTRACT S2 floor semantics at the v2
// family tables; range facts assert at derive time (loud fail = the
// intended uncalibratable-model behavior) and z cross-checks against
// the Python replica byte-for-byte at the full T = 512 shape.
//
// The pass statement is manifest v4 (lane deliverable D2): TRUE signed
// exponents (no D3-F2 clamps), [-127,127] symmetric X/W (the honest
// 25/26-bit accumulators DERIVED), per-layer LookupAt into the family,
// RangeLookup facts (the U-R2 range-table form), E-O1-BB class/base
// fields. 17 entries + 16 operations per layer; 12 z outputs.
//
// P0 mode, stated honestly: no privacy claim; weight commitment
// randomness rides a PUBLIC deterministic seed (the "weights committed
// once, model identity public" reading — a verifier recomputes the
// weight commitments from the public model, which is what makes the
// wrong-weight battery leg a STATEMENT-gate reject); byte totals are
// opening-dominated until lane BD's aggregation stack lands and are
// REPORTED against the Tier N gate, not hidden.

const BF_EXPORT_DIR: &str = "results/m125_ffn_export";

/// The export directory, resolved from either the repo root or
/// zkmatrix-rs/ (both are working directories in practice).
fn bf_export_path() -> std::path::PathBuf {
    // `M125_EXPORT_DIR` (2026-08-17): an alternate export directory —
    // e.g. results/m125_ffn_export_wsl/, the WSL box's own re-export of
    // the SAME checkpoint + window (valid witness, 0 violations) whose X
    // digests differ from the Mac's by mlx CPU-vs-Metal rounding; the
    // frozen (committed) sidecar/digests stay authoritative for
    // freeze-check, which does not set the variable.
    if let Ok(dir) = std::env::var("M125_EXPORT_DIR") {
        return std::path::PathBuf::from(dir);
    }
    let a = std::path::PathBuf::from(BF_EXPORT_DIR);
    if a.exists() { a } else { std::path::PathBuf::from("..").join(BF_EXPORT_DIR) }
}
const BF_T: usize = 512;
const BF_D: usize = 768;
const BF_F: usize = 2048;

/// Per-layer witness data: exports + the Rust-derived chain.
struct BfLayer {
    l: usize,
    /// (eX, eGate, eA, eUp, eH, eZ) — BB's M125_EXP row (calibration).
    exps: (i32, i32, i32, i32, i32, i32),
    /// shifts (g, u, h, z) — derived from the true exponents; asserted
    /// equal to the export sidecar's.
    shifts: (u32, u32, u32, u32),
    x: Vec<i64>,
    wg_t: Vec<i64>,
    wu_t: Vec<i64>,
    wd_t: Vec<i64>,
    gacc: Vec<i64>,
    rg: Vec<i64>,
    g8: Vec<i64>,
    a8: Vec<i64>,
    uacc: Vec<i64>,
    ru: Vec<i64>,
    u8v: Vec<i64>,
    hh: Vec<i64>,
    rh: Vec<i64>,
    h8: Vec<i64>,
    dacc: Vec<i64>,
    rd: Vec<i64>,
    z: Vec<i64>,
}

fn bf_read_i8(path: &std::path::Path, n: usize) -> Vec<i64> {
    let bytes = std::fs::read(path).unwrap_or_else(|e| {
        panic!(
            "cannot read {} ({e}) — run scripts/m125_export_ffn.py under the frugal venv first",
            path.display()
        )
    });
    assert_eq!(bytes.len(), n, "{}: wrong size", path.display());
    bytes.iter().map(|&b| b as i8 as i64).collect()
}

fn bf_sidecar() -> std::collections::BTreeMap<(usize, String), String> {
    let path = bf_export_path().join("digests.txt");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read {} ({e})", path.display()));
    let mut map = std::collections::BTreeMap::new();
    for line in text.lines() {
        let mut it = line.split_whitespace();
        let l: usize = it.next().expect("layer").parse().expect("layer no");
        let name = it.next().expect("name").to_string();
        let rest: Vec<&str> = it.collect();
        map.insert((l, name), rest.join(" "));
    }
    map
}

fn bf_sha_i8(vals: &[i64]) -> String {
    let bytes: Vec<u8> = vals.iter().map(|&v| v as i8 as u8).collect();
    hex_full(&uk8_sha(&[&bytes]))
}

/// The floor requantization x = 2^shift * y + r, r in [0, 2^shift)
/// (Euclidean quotient/remainder — TARGET_CONTRACT S2 as written).
fn bf_floor_requant(acc: &[i64], shift: u32) -> (Vec<i64>, Vec<i64>) {
    let m = 1i64 << shift;
    let y: Vec<i64> = acc.iter().map(|&a| a.div_euclid(m)).collect();
    let r: Vec<i64> = acc.iter().map(|&a| a.rem_euclid(m)).collect();
    (y, r)
}

/// Load one layer's exports and derive the witness chain in exact
/// integer arithmetic at the first `t_rows` sequence positions
/// (row-independent chain: rows 0..t of the full pass — the T = 512
/// z digests bind the full shape). Asserts every range fact.
fn bf_load_layer(l: usize, t_rows: usize, quiet: bool) -> BfLayer {
    use ring::lookup::silu_v2_member;
    let dir = bf_export_path();
    // M125_EXP rows are (eX, eGate, eA, eUp, eH, eZ) — BC's calibrated
    // table (eGate == eA on every calibrated layer).
    let (e_x, e_gate, e_a, e_up, e_h, e_z) = M125_EXP[l];
    assert_eq!(e_gate, e_a, "family assumes eGate == eA");
    let sh_g = (e_gate - e_x + 9) as u32;
    let sh_u = (e_up - e_x + 9) as u32;
    let sh_h = (e_h - e_a - e_up) as u32;
    let sh_z = (e_z - e_h + 9) as u32;
    let side = bf_sidecar();
    let want_shifts = side[&(l, "shifts".to_string())].clone();
    assert_eq!(
        want_shifts,
        format!("{sh_g} {sh_u} {sh_h} {sh_z}"),
        "layer {l}: derived shifts disagree with the export sidecar"
    );

    let x_full = bf_read_i8(&dir.join(format!("layer{l:02}_X.bin")), BF_T * BF_D);
    let wg_t = bf_read_i8(&dir.join(format!("layer{l:02}_WgT.bin")), BF_D * BF_F);
    let wu_t = bf_read_i8(&dir.join(format!("layer{l:02}_WuT.bin")), BF_D * BF_F);
    let wd_t = bf_read_i8(&dir.join(format!("layer{l:02}_WdT.bin")), BF_F * BF_D);
    if t_rows == BF_T {
        for (name, vals) in [("X", &x_full), ("WgT", &wg_t), ("WuT", &wu_t), ("WdT", &wd_t)] {
            assert_eq!(
                bf_sha_i8(vals),
                side[&(l, name.to_string())],
                "layer {l} {name}: export digest mismatch"
            );
        }
    }
    let x: Vec<i64> = x_full[0..t_rows * BF_D].to_vec();

    let mut lay = BfLayer {
        l,
        exps: (e_x, e_gate, e_a, e_up, e_h, e_z),
        shifts: (sh_g, sh_u, sh_h, sh_z),
        x, wg_t, wu_t, wd_t,
        gacc: vec![], rg: vec![], g8: vec![], a8: vec![], uacc: vec![], ru: vec![],
        u8v: vec![], hh: vec![], rh: vec![], h8: vec![], dacc: vec![], rd: vec![], z: vec![],
    };
    bf_derive_chain(&mut lay, t_rows, None);
    let in_i8 = |v: &[i64]| v.iter().all(|&x| (-128..=127).contains(&x));
    assert!(
        in_i8(&lay.g8) && in_i8(&lay.u8v) && in_i8(&lay.h8) && in_i8(&lay.z),
        "layer {l}: a range fact FAILS (uncalibratable witness — intended reject)"
    );
    if t_rows == BF_T {
        assert_eq!(
            bf_sha_i8(&lay.z),
            side[&(l, "z".to_string())],
            "layer {l}: Rust chain z differs from the Python replica"
        );
    }
    if !quiet {
        println!(
            "  layer {l:2}: chain derived (shifts {sh_g}/{sh_u}/{sh_h}/{sh_z}, table ({e_gate},{e_a})); range facts HOLD{}",
            if t_rows == BF_T { "; z == Python replica" } else { "" }
        );
    }
    lay
}

/// (Re)derive the witness chain from X + weights (exact integer
/// arithmetic, floor semantics, the layer's family table — or an
/// override member for the wrong-table battery arm). No range asserts
/// here: tampered chains ride as-is and the PROOF is what rejects.
/// The chain's exact integer GEMM c[i][j] = sum_k a[i][k] * b_t[k][j]
/// (row-major a rows x inner, b_t inner x cols) — the serial i-k-j loop
/// bf_derive_chain ran inline. THE ORACLE of `bf_matmul_i64`.
fn bf_matmul_i64_ref(a: &[i64], b_t: &[i64], rows: usize, inner: usize, cols: usize) -> Vec<i64> {
    let mut c = vec![0i64; rows * cols];
    for i in 0..rows {
        for k in 0..inner {
            let av = a[i * inner + k];
            if av == 0 {
                continue;
            }
            let brow = &b_t[k * cols..(k + 1) * cols];
            let crow = &mut c[i * cols..(i + 1) * cols];
            for (cv, &bv) in crow.iter_mut().zip(brow.iter()) {
                *cv += av * bv;
            }
        }
    }
    c
}

/// [UPERF2-D] `bf_matmul_i64_ref` as a row-blocked GEMM on the ZK_THREADS
/// pool: when every |a|, |b| <= 127 and inner * 127^2 < 2^31 (the chain's
/// int8 x int8 products at inner <= 2048) the block accumulates in i32
/// (the exact sum fits; AVX2 vpmulld/vpaddd autovectorize it) and widens
/// once; otherwise the i64 loop runs per row block. Row blocks of RB rows
/// share one streamed pass over b_t (RB x fewer B reads than the i-k-j
/// loop). Every output row is one thread's own exact-integer sum over the
/// same k order — bit-identical for any thread count and block size (and
/// integer addition is associative besides). Oracle-routed under
/// `ZK_UPERF_ORACLE=1`.
fn bf_matmul_i64(a: &[i64], b_t: &[i64], rows: usize, inner: usize, cols: usize) -> Vec<i64> {
    use rayon::prelude::*;
    use ring::fold::ixf_pooled;
    if ring::eval_proof::oracle_mode() {
        return bf_matmul_i64_ref(a, b_t, rows, inner, cols);
    }
    assert_eq!(a.len(), rows * inner);
    assert_eq!(b_t.len(), inner * cols);
    let small = |v: &[i64]| v.iter().all(|&x| (-127..=127).contains(&x));
    let i32_ok = inner as u64 * 127 * 127 < (1u64 << 31) && small(a) && small(b_t);
    const RB: usize = 16;
    let mut c = vec![0i64; rows * cols];
    if i32_ok {
        let a32: Vec<i32> = a.iter().map(|&x| x as i32).collect();
        let b32: Vec<i32> = b_t.iter().map(|&x| x as i32).collect();
        ixf_pooled(|| {
            c.par_chunks_mut(RB * cols).enumerate().for_each(|(blk, cblk)| {
                let i0 = blk * RB;
                let nr = cblk.len() / cols;
                let mut acc = vec![0i32; nr * cols];
                for k in 0..inner {
                    let brow = &b32[k * cols..(k + 1) * cols];
                    for ii in 0..nr {
                        let av = a32[(i0 + ii) * inner + k];
                        if av == 0 {
                            continue;
                        }
                        let crow = &mut acc[ii * cols..(ii + 1) * cols];
                        for (cv, &bv) in crow.iter_mut().zip(brow.iter()) {
                            *cv += av * bv;
                        }
                    }
                }
                for (dst, &v) in cblk.iter_mut().zip(acc.iter()) {
                    *dst = v as i64;
                }
            });
        });
    } else {
        ixf_pooled(|| {
            c.par_chunks_mut(RB * cols).enumerate().for_each(|(blk, cblk)| {
                let i0 = blk * RB;
                let nr = cblk.len() / cols;
                for k in 0..inner {
                    let brow = &b_t[k * cols..(k + 1) * cols];
                    for ii in 0..nr {
                        let av = a[(i0 + ii) * inner + k];
                        if av == 0 {
                            continue;
                        }
                        let crow = &mut cblk[ii * cols..(ii + 1) * cols];
                        for (cv, &bv) in crow.iter_mut().zip(brow.iter()) {
                            *cv += av * bv;
                        }
                    }
                }
            });
        });
    }
    c
}

fn bf_derive_chain(lay: &mut BfLayer, t_rows: usize, table_override: Option<(i32, i32)>) {
    use ring::lookup::silu_v2_member;
    let _t = ring::ct_engine::prof::timer(ring::ct_engine::prof::D_CHAIN); // [UPERF2-D] observation only
    let (sh_g, sh_u, sh_h, sh_z) = lay.shifts;
    let (eg, ea) = table_override.unwrap_or((lay.exps.1, lay.exps.2));
    // [UPERF2-D] the row-blocked threaded GEMM (bf_matmul_i64_ref is its
    // oracle — the loop that ran inline here).
    let matmul = bf_matmul_i64;
    lay.gacc = matmul(&lay.x, &lay.wg_t, t_rows, BF_D, BF_F);
    lay.uacc = matmul(&lay.x, &lay.wu_t, t_rows, BF_D, BF_F);
    let (g8, rg) = bf_floor_requant(&lay.gacc, sh_g);
    let (u8v, ru) = bf_floor_requant(&lay.uacc, sh_u);
    let clamp_dom = |v: i64| v.clamp(-128, 127);
    let (table, _dg) = silu_v2_member(eg, ea).expect("frozen family member");
    lay.a8 = g8.iter().map(|&g| table[(clamp_dom(g) + 128) as usize] as i64).collect();
    lay.g8 = g8;
    lay.rg = rg;
    lay.u8v = u8v;
    lay.ru = ru;
    lay.hh = lay.a8.iter().zip(lay.u8v.iter()).map(|(&a, &u)| a * u).collect();
    let (h8, rh) = bf_floor_requant(&lay.hh, sh_h);
    lay.h8 = h8;
    lay.rh = rh;
    lay.dacc = matmul(&lay.h8, &lay.wd_t, t_rows, BF_F, BF_D);
    let (z, rd) = bf_floor_requant(&lay.dacc, sh_z);
    lay.z = z;
    lay.rd = rd;
}

/// Entry roles per layer, in commitment order (17 per layer).
const BF_ENTRIES: [&str; 17] = [
    "X", "WgT", "WuT", "WdT", "Gacc", "Rg", "g8", "a8", "Uacc", "Ru", "u8",
    "H", "Rh", "h8", "Dacc", "Rd", "z",
];

/// (rows, cols) of entry `e` at sequence length t.
fn bf_entry_shape(e: usize, t: usize) -> (usize, usize) {
    match BF_ENTRIES[e] {
        "X" => (t, BF_D),
        "WgT" | "WuT" => (BF_D, BF_F),
        "WdT" => (BF_F, BF_D),
        "Dacc" | "Rd" | "z" => (t, BF_D),
        _ => (t, BF_F),
    }
}

/// The layer's per-entry (QuantMeta, TypingV4) rows under the v4 typed
/// semantics — TRUE exponents, symmetric where honest, E-O1-BB classes.
fn bf_entry_typing(e: usize, lay: &BfLayer) -> (manifest::QuantMeta, manifest::TypingV4) {
    use manifest::{CLS_ACC, CLS_ACT8, CLS_REM, CLS_W8S, QuantMeta, TypingV4};
    let (e_x, e_gate, e_a, e_up, e_h, e_z) = lay.exps;
    let (sh_g, sh_u, sh_h, sh_z) = lay.shifts;
    let q = |bits: u32, signed: bool| QuantMeta { bits, frac_bits: 0, signed };
    let t = |se: i32, sym: bool, class: u32, e0: u32| TypingV4 {
        scale_exp: se,
        symmetric: sym,
        class,
        base_e0: e0,
    };
    match BF_ENTRIES[e] {
        "X" => (q(8, true), t(e_x, true, CLS_ACT8, 2)),
        "WgT" | "WuT" | "WdT" => (q(8, true), t(-9, true, CLS_W8S, 1)),
        "Gacc" | "Uacc" => (q(25, true), t(e_x - 9, true, CLS_ACC, 2)),
        "Rg" => (q(sh_g, false), t(e_x - 9, false, CLS_REM, 2)),
        "Ru" => (q(sh_u, false), t(e_x - 9, false, CLS_REM, 2)),
        "g8" => (q(8, true), t(e_gate, false, CLS_ACT8, 2)),
        "a8" => (q(8, true), t(e_a, true, CLS_ACT8, 2)),
        "u8" => (q(8, true), t(e_up, false, CLS_ACT8, 2)),
        "H" => (q(15, true), t(e_a + e_up, false, CLS_ACC, 2)),
        "Rh" => (q(sh_h, false), t(e_a + e_up, false, CLS_REM, 2)),
        "h8" => (q(8, true), t(e_h, false, CLS_ACT8, 2)),
        "Dacc" => (q(26, true), t(e_h - 9, false, CLS_ACC, 2)),
        "Rd" => (q(sh_z, false), t(e_h - 9, false, CLS_REM, 2)),
        "z" => (q(8, true), t(e_z, false, CLS_ACT8, 2)),
        _ => unreachable!(),
    }
}

/// The witness values of entry `e` (the chain tensors, in entry order).
fn bf_entry_values<'a>(e: usize, lay: &'a BfLayer) -> &'a [i64] {
    match BF_ENTRIES[e] {
        "X" => &lay.x,
        "WgT" => &lay.wg_t,
        "WuT" => &lay.wu_t,
        "WdT" => &lay.wd_t,
        "Gacc" => &lay.gacc,
        "Rg" => &lay.rg,
        "g8" => &lay.g8,
        "a8" => &lay.a8,
        "Uacc" => &lay.uacc,
        "Ru" => &lay.ru,
        "u8" => &lay.u8v,
        "H" => &lay.hh,
        "Rh" => &lay.rh,
        "h8" => &lay.h8,
        "Dacc" => &lay.dacc,
        "Rd" => &lay.rd,
        "z" => &lay.z,
        _ => unreachable!(),
    }
}

/// The v4 pass statement over `layers` at sequence length t: 17 entries
/// + 16 operations per layer, per-layer LookupAt table index, 12 (or
/// n_layers) declared z outputs. `commit_digests[l][e]` are the entry
/// group digests (weight entries: recomputable from the public model —
/// the P0 identity discipline).
fn m125_build_statement(
    t_rows: usize,
    layers: &[BfLayer],
    commit_digests: &[Vec<Vec<u8>>],
    crs_hash: &[u8],
) -> manifest::Statement {
    use manifest::{
        ClaimManifest, Operation, Orientation, PadSpec, SILU_V2_M3_TABLE_SPEC,
        SILU_V2_M4_TABLE_SPEC, Statement,
    };
    let mut mf = ClaimManifest::new("lattice-uagb1-bf-m125", crs_hash);
    let mut quant = Vec::new();
    let mut typing = Vec::new();
    let mut outputs = Vec::new();
    let mut model: Vec<u8> = b"uagb1-bf-m125-pass-v1".to_vec();
    model.extend((t_rows as u64).to_le_bytes());
    model.extend((layers.len() as u64).to_le_bytes());
    for (li, lay) in layers.iter().enumerate() {
        let base = (li * BF_ENTRIES.len()) as u32;
        let (e_x, e_gate, _e_a, e_up, e_h, e_z) = lay.exps;
        let (sh_g, sh_u, sh_h, sh_z) = lay.shifts;
        for e in 0..BF_ENTRIES.len() {
            let (rows, cols) = bf_entry_shape(e, t_rows);
            let (qm, ty) = bf_entry_typing(e, lay);
            mf.add_commitment(
                &format!("{}{}", BF_ENTRIES[e], lay.l),
                rows,
                cols,
                Orientation::RowMajor,
                vec![],
                commit_digests[li][e].clone(),
            );
            quant.push(qm);
            typing.push(ty);
        }
        let id = |e: usize| base + e as u32;
        let tbl = if e_gate == -3 { 0u32 } else { 1u32 };
        mf.add_operation(Operation::Matmul { a: id(0), b: id(1), c: id(4) });
        mf.add_operation(Operation::Rescale { x: id(4), y: id(6), r: id(5), shift: sh_g });
        mf.add_operation(Operation::RangeLookup { value: id(5), width: sh_g, signed: false });
        mf.add_operation(Operation::LookupAt { x: id(6), y: id(7), table: tbl });
        mf.add_operation(Operation::Matmul { a: id(0), b: id(2), c: id(8) });
        mf.add_operation(Operation::Rescale { x: id(8), y: id(10), r: id(9), shift: sh_u });
        mf.add_operation(Operation::RangeLookup { value: id(9), width: sh_u, signed: false });
        mf.add_operation(Operation::RangeLookup { value: id(10), width: 8, signed: true });
        mf.add_operation(Operation::Hadamard { x: id(7), y: id(10), z: id(11) });
        mf.add_operation(Operation::Rescale { x: id(11), y: id(13), r: id(12), shift: sh_h });
        mf.add_operation(Operation::RangeLookup { value: id(12), width: sh_h, signed: false });
        mf.add_operation(Operation::RangeLookup { value: id(13), width: 8, signed: true });
        mf.add_operation(Operation::Matmul { a: id(13), b: id(3), c: id(14) });
        mf.add_operation(Operation::Rescale { x: id(14), y: id(16), r: id(15), shift: sh_z });
        mf.add_operation(Operation::RangeLookup { value: id(15), width: sh_z, signed: false });
        mf.add_operation(Operation::RangeLookup { value: id(16), width: 8, signed: true });
        outputs.push(id(16));
        // Model identity: layer exponents + shifts + the EXPORT tensor
        // digests (X + weights) — the frozen quantized model.
        model.extend((lay.l as u64).to_le_bytes());
        for v in [e_x, e_gate, e_up, e_h, e_z] {
            model.extend(v.to_le_bytes());
        }
        for v in [sh_g, sh_u, sh_h, sh_z] {
            model.extend(v.to_le_bytes());
        }
        for e in [0usize, 1, 2, 3] {
            model.extend(bf_sha_i8(bf_entry_values(e, lay)).into_bytes());
        }
    }
    model.extend(ring::lookup::SILU_V2_M3_DIGEST);
    model.extend(ring::lookup::SILU_V2_M4_DIGEST);
    let mut st = Statement::new_v4(
        uk8_sha(&[&model]),
        vec![SILU_V2_M3_TABLE_SPEC, SILU_V2_M4_TABLE_SPEC],
        30,
        mf,
    );
    st.quant = quant;
    st.typing = typing;
    st.pad = st
        .manifest
        .commitments
        .iter()
        .map(|e| PadSpec::exact(e.rows as usize, e.cols as usize))
        .collect();
    st.outputs = outputs;
    st
}

/// Smallest tree depth whose witness data block (first half minus the 4
/// blinder positions) holds n elements.
/// The witness tree depth for `n` honest leaves. [UAGB1-BJ wave 4,
/// BF-F3 wiring per UAGB1_VERIFIER_REPORT 2.4]: capacity is the
/// split-fill n_leaves - 8 (`witness_leaf_positions`, the [UAGB1-BH]
/// lift of the 2^(d-1) - 4 blinder-free-front constraint), so the
/// 2^20-class pass columns ride depth-21 trees instead of the
/// dummy-padded depth 22 (BF-F3's ~2x tree work removed) and the nd
/// columns ride 19 instead of 20.
fn bf_dw_for(n: usize) -> usize {
    let mut d = 4usize;
    while (1usize << d) - 8 < n {
        d += 1;
    }
    d
}

/// One lookup instance of the layer: the SiLU pair or a [0, 2^w) range
/// table over a (possibly offset) committed dense column.
#[derive(Clone)]
struct BfInst {
    name: &'static str,
    /// Primary committed column (entry index 0..17).
    entry: usize,
    /// SiLU only: the image column (a8).
    pair: Option<usize>,
    /// Code offset: witness code = value + offset (128 for signed int8
    /// columns against the [0,256) table; 0 for remainders/pairs).
    offset: i64,
    /// Table rows (256 for silu/w8; 2^shift for remainders).
    t_rows: usize,
    /// The family member exponent pair (silu) — None for range tables.
    silu: Option<(i32, i32)>,
    dw: usize,
    dt: usize,
    // Aux commitment indices (absolute), filled by the layout.
    idx_m: usize,
    idx_bl: usize,
    base_wm: usize,
    base_tm: usize,
    wm_c: usize,
    tm_c: usize,
}

/// The layer's 9 lookup instances in transcript order.
fn bf_instances(lay: &BfLayer, t: usize) -> Vec<BfInst> {
    let (sh_g, sh_u, sh_h, sh_z) = lay.shifts;
    let (_, e_gate, e_a, ..) = lay.exps;
    let nf = t * BF_F;
    let nd = t * BF_D;
    let mk = |name: &'static str, entry: usize, pair: Option<usize>, offset: i64,
              t_rows: usize, silu: Option<(i32, i32)>, n_el: usize| BfInst {
        name,
        entry,
        pair,
        offset,
        t_rows,
        silu,
        dw: bf_dw_for(n_el),
        dt: (t_rows.trailing_zeros() as usize) + 1,
        idx_m: usize::MAX,
        idx_bl: usize::MAX,
        base_wm: usize::MAX,
        base_tm: usize::MAX,
        wm_c: 0,
        tm_c: 0,
    };
    vec![
        mk("silu", 6, Some(7), 0, 256, Some((e_gate, e_a)), nf),
        mk("rng-rg", 5, None, 0, 1 << sh_g, None, nf),
        mk("rng-ru", 9, None, 0, 1 << sh_u, None, nf),
        mk("rng-u8", 10, None, 128, 256, None, nf),
        mk("rng-rh", 12, None, 0, 1 << sh_h, None, nf),
        mk("rng-h8", 13, None, 128, 256, None, nf),
        mk("rng-rd", 15, None, 0, 1 << sh_z, None, nd),
        mk("rng-z", 16, None, 128, 256, None, nd),
    ]
}

/// The layer's commitment layout: entry commitment bases, per-instance
/// aux bases, the first-fit wave plan and the U-Z1 pad layout.
struct BfLayout {
    /// First commitment index + count of each of the 17 entries.
    entry_base: [usize; 17],
    entry_cms: [usize; 17],
    insts: Vec<BfInst>,
    n_data: usize,
    base_pad: usize,
    base_closing_g: usize,
    base_wave_g: usize,
    n_commits: usize,
    c2_max: usize,
    data_cap: usize,
    wave_g_groups: usize,
    closing_g_groups: usize,
    plan: ring::ct_engine::WavePlan,
    pad_layout: ring::ct_engine::WavePadLayout,
}

fn bf_layout(lay: &BfLayer, t: usize, shape: CommitShape, q: u64) -> BfLayout {
    use ring::ct_engine::{WavePadLayout, plan_waves};
    use ring::gkr_masked::mask_coeff_counts;
    use ring::kfield::K_DEG;
    let per = shape.msg_r * D;
    let mut entry_base = [0usize; 17];
    let mut entry_cms = [0usize; 17];
    let mut cursor = 0usize;
    for e in 0..17 {
        let (rows, cols) = bf_entry_shape(e, t);
        assert_eq!((rows * cols) % per, 0, "no-tail discipline at entry {e}");
        entry_base[e] = cursor;
        entry_cms[e] = (rows * cols) / per;
        cursor += entry_cms[e];
    }
    let kel_cms = |n_kel: usize| (n_kel * K_DEG).div_ceil(per).max(1);
    let mut insts = bf_instances(lay, t);
    for inst in insts.iter_mut() {
        let (gw, rw) = mask_coeff_counts(inst.dw, 0);
        let (gt, rt) = mask_coeff_counts(inst.dt, 0);
        inst.wm_c = kel_cms(gw + rw);
        inst.tm_c = kel_cms(gt + rt);
        inst.idx_m = cursor;
        inst.idx_bl = cursor + 1;
        inst.base_wm = cursor + 2;
        inst.base_tm = cursor + 2 + inst.wm_c;
        cursor += 2 + inst.wm_c + inst.tm_c;
        assert!(inst.t_rows <= per, "m column fits one commitment");
        assert!(ring::gkr::ceiling_gate_ok(1u64 << inst.dw, q));
    }
    let n_data = cursor;
    let wave_g_groups = UR1_PIN_COPIES.div_ceil(shape.msg_r);
    let c2_max = ur1_c2_max_commits(q, shape);
    let data_cap = c2_max - 1 - wave_g_groups;
    let plan = plan_waves(n_data, &[], data_cap).expect("group-free first-fit plan");
    let n_waves = plan.waves.len();
    let pad_layout =
        WavePadLayout::derive(UR1_PIN_COPIES, (0..n_waves).collect(), n_waves, shape.msg_r)
            .expect("pad layout derives");
    let closing_g_groups =
        if pad_layout.has_pads() { UR1_PIN_COPIES.div_ceil(shape.msg_r) } else { 0 };
    let base_pad = n_data;
    let base_closing_g = base_pad + pad_layout.n_pad_cms;
    let base_wave_g = base_closing_g + closing_g_groups;
    let n_commits = base_wave_g + n_waves * wave_g_groups;
    BfLayout {
        entry_base,
        entry_cms,
        insts,
        n_data,
        base_pad,
        base_closing_g,
        base_wave_g,
        n_commits,
        c2_max,
        data_cap,
        wave_g_groups,
        closing_g_groups,
        plan,
        pad_layout,
    }
}

/// Commit one layer's 17 entries (weights under the PUBLIC per-entry
/// seed — the P0 model-identity discipline; witness entries under the
/// layer session seed). Returns per-entry group digests (and optionally
/// keeps the full materials for the proven layer).
struct BfCommitted {
    msgs: Vec<Vec<Poly>>,
    rhos8: Vec<Vec<i8>>,
    t1s: Vec<Vec<Poly>>,
    t2s: Vec<Vec<Poly>>,
}

fn bf_commit_entries(
    lay: &BfLayer,
    t: usize,
    shape: CommitShape,
    crs: &ring::commit::RingCrs,
    path: &KernelPath,
    keep: bool,
) -> (Vec<Vec<u8>>, Option<BfCommitted>) {
    let zq = ring_ctx_q8().zq;
    let per = shape.msg_r * D;
    let mut entry_digests = Vec::with_capacity(17);
    let mut kept = BfCommitted { msgs: Vec::new(), rhos8: Vec::new(), t1s: Vec::new(), t2s: Vec::new() };
    for e in 0..17 {
        let vals = bf_entry_values(e, lay);
        let n_cms = vals.len().div_ceil(per);
        let seed_tag = if (1..=3).contains(&e) { "uagb1-bf-w" } else { "uagb1-bf-wit" };
        let mut rng = ring::ProverRng::from_test_seed(
            seed_tag,
            &[(lay.l as u64).to_le_bytes(), (e as u64).to_le_bytes()].concat(),
        );
        let mut cm_digests = Vec::with_capacity(n_cms);
        for g in 0..n_cms {
            let mut polys = vec![poly_zero(); shape.msg_r];
            for s in 0..shape.msg_r {
                for c in 0..D {
                    let idx = g * per + s * D + c;
                    if idx < vals.len() {
                        polys[s][c] = zq.to_mod(vals[idx]);
                    }
                }
            }
            let rho: Vec<Vec<i64>> = (0..shape.n_r).map(|_| rng_ternary_poly(&mut rng)).collect();
            let (t1, t2) = commit(path, crs, &polys, &rho);
            cm_digests.push(group_digest(&t1, &t2));
            if keep {
                kept.msgs.push(polys);
                kept.rhos8.push(rho.iter().flat_map(|p| p.iter().map(|&x| x as i8)).collect());
                kept.t1s.push(t1);
                kept.t2s.push(t2);
            }
        }
        entry_digests.push(group_list_digest(&cm_digests));
    }
    (entry_digests, if keep { Some(kept) } else { None })
}

#[derive(Clone, Copy, PartialEq)]
enum BfTamper {
    None,
    /// The prover uses the NEXT layer's gate weight tensor, fully
    /// self-consistently (chain rederived) — caught at the STATEMENT
    /// gate: the verifier recomputes the weight commitments from the
    /// PUBLIC model (P0 identity discipline) and the digests differ.
    WrongWeight,
    /// The prover runs the SiLU instance against the WRONG family
    /// member (chain rederived consistently) — descents and roots are
    /// internally green; the verifier's table-side leaf pins fold the
    /// STATEMENT's member and the psi'd claims fail in the wave rounds.
    WrongTable,
    /// g8 replaced by the OTHER layer's g8 (statement self-consistent)
    /// — the statement seam: requant + lookup pins tie g8 to Gacc/a8,
    /// so the wave rounds reject.
    SeamSwap,
    /// One remainder pushed out of [0, 2^shift) with the requant
    /// identity preserved (rd += 2^s, z -= 1): ONLY the rd range
    /// instance's root cross-check can see it.
    RangeViolation,
    /// [UAGB1-BJ, BF-F3 wiring] Honest proof on SPLIT witness trees;
    /// the VERIFIER's leaf pins computed under the pre-lift CONTIGUOUS
    /// assumption (identity map) — the `witness_leaf_positions` map is
    /// load-bearing: the psi'd claims fail in the wave rounds (the
    /// bh-verifier wrong-map leg, at the rig).
    WrongMap,
}

struct BfVerdict {
    statement_ok: bool,
    matmul_ok: [bool; 3],
    hadamard_ok: bool,
    /// Per-instance root cross-check verdicts (silu + 7 range).
    roots_ok: Vec<bool>,
    sum_gate_ok: bool,
    waves_ok: bool,
    first_bad_wave: Option<usize>,
    closing_ok: bool,
}

impl BfVerdict {
    fn accept(&self) -> bool {
        self.statement_ok
            && self.matmul_ok.iter().all(|&b| b)
            && self.hadamard_ok
            && self.roots_ok.iter().all(|&b| b)
            && self.sum_gate_ok
            && self.waves_ok
            && self.closing_ok
    }
}

#[derive(Default)]
struct BfCost {
    n_data: usize,
    n_commits: usize,
    n_waves: usize,
    n_pins: usize,
    commit_s: f64,
    matmul_s: f64,
    had_s: f64,
    req_s: f64,
    lkp_s: f64,
    pinclaims_s: f64,
    waves_s: f64,
    prove_s: f64,
    verify_s: f64,
    verify_lkp_s: f64,
    verify_waves_s: f64,
    bytes_statement: usize,
    bytes_commit_tags: usize,
    bytes_sumcheck: usize,
    bytes_descents: usize,
    bytes_reveals: usize,
    bytes_ct_z: usize,
    bytes_ct_w1: usize,
    bytes_ct_other: usize,
}

impl BfCost {
    fn bytes_total(&self) -> usize {
        self.bytes_statement
            + self.bytes_commit_tags
            + self.bytes_sumcheck
            + self.bytes_descents
            + self.bytes_reveals
            + self.bytes_ct_z
            + self.bytes_ct_w1
            + self.bytes_ct_other
    }
}

/// eq(a, b) for two points of equal length.
fn bf_eq_point(kf: &ring::kfield::KField, a: &[ring::kfield::KElem], b: &[ring::kfield::KElem]) -> ring::kfield::KElem {
    let mut acc = kf.one();
    for (x, y) in a.iter().zip(b.iter()) {
        let xy = kf.mul(x, y);
        let one_m = kf.mul(&kf.sub(&kf.one(), x), &kf.sub(&kf.one(), y));
        acc = kf.mul(&acc, &kf.add(&xy, &one_m));
    }
    acc
}

/// One complete committed layer proof + verification of the 125M pass
/// (statement ctx = the FULL pass statement digest; this layer's ops).
/// Returns the verdict and the measured cost row.
#[allow(clippy::too_many_lines)]
fn bf_layer_run(
    t: usize,
    layers: &mut [BfLayer],
    li: usize,
    tamper: BfTamper,
    quiet: bool,
) -> (BfVerdict, BfCost) {
    use ring::ct_engine::{
        CtClaim, StdOpening, WavePads, closing_round_claims, ct_h0, derive_ct_round_params,
        draw_wave_pads, pack_wave_pads, prove_ct_round, sample_ct_masks,
        split_claims_prover_masked, split_claims_verifier_masked, verify_ct_round,
    };
    use ring::gkr::eq_table;
    use ring::gkr_masked::{
        BlinderSet, DescentEnd, MaskSet, MaskedDescentProof, blinded_table_tree,
        blinded_witness_tree, blinder_positions, draw_masks, g_hypersum_weights, g_open_weights,
        masked_gkr_prove, masked_gkr_verify, masked_pass_bytes, r_open_weights,
        table_row_positions, witness_leaf_positions, zero_masks,
    };
    use ring::kfield::{K_DEG, KElem, KField};
    use ring::lookup::{
        PinTerm, PinnedValue, derive_pin_psi, fuse_pair, multiplicities, pin_claims, silu_v2_member,
        silu_v2_rows,
    };
    use ring::sumcheck::{LkpTranscript, sumcheck_prove, sumcheck_verify};

    let ctx_ring = ring_ctx_q8();
    let kf = KField::new(&ctx_ring);
    let zq = ctx_ring.zq;
    let q = zq.q;
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    let msg_r = shape.msg_r;
    let per = msg_r * D;
    let kpc = per / K_DEG;
    let crs = expand_crs(shape, q, 0x0BF1);
    let zero = kf.zero();
    let one = kf.one();

    // ---- Tampered witness (self-consistent where the leg demands). ------
    let other = if li + 1 < layers.len() { li + 1 } else { li - 1 };
    match tamper {
        BfTamper::WrongWeight => {
            let wg = layers[other].wg_t.clone();
            layers[li].wg_t = wg;
            bf_derive_chain(&mut layers[li], t, None);
        }
        BfTamper::WrongTable => {
            let (eg, ea) = (layers[li].exps.1, layers[li].exps.2);
            let wrong = if eg == -3 { (-4, -4) } else { (-3, -3) };
            assert!(silu_v2_member(wrong.0, wrong.1).is_some());
            bf_derive_chain(&mut layers[li], t, Some(wrong));
            let _ = (eg, ea);
        }
        BfTamper::SeamSwap => {
            let g8 = layers[other].g8.clone();
            assert_eq!(g8.len(), layers[li].g8.len());
            layers[li].g8 = g8;
        }
        BfTamper::RangeViolation => {
            let sh_z = layers[li].shifts.3;
            // Pick a position whose z stays comfortably inside int8 so
            // the ONLY out-of-range value is the remainder (leg
            // isolation: the rd instance's root check is the sole gate).
            let idx = layers[li].z.iter().position(|&v| v > -100 && v < 100).unwrap();
            layers[li].rd[idx] += 1i64 << sh_z;
            layers[li].z[idx] -= 1;
        }
        // WrongMap is a VERIFIER-side hook (leaf-pin position map);
        // the witness is honest.
        BfTamper::None | BfTamper::WrongMap => {}
    }

    // ---- Commit pass: every layer's entries (digests for the pass
    // statement); the PROVEN layer keeps its materials + aux. -------------
    let t_commit = Instant::now();
    let rp_probe = derive_ct_round_params(q, shape, ur1_c2_max_commits(q, shape), 0, 0, true);
    let a1p = build_a1_paths(&crs, rp_probe.sigma, isqrt_u128(rp_probe.bound_sq));
    let path = KernelPath::A1(&a1p);
    let mut all_digests: Vec<Vec<Vec<u8>>> = Vec::with_capacity(layers.len());
    let mut kept: Option<BfCommitted> = None;
    for (i, lay) in layers.iter().enumerate() {
        let (digs, keep) = bf_commit_entries(lay, t, shape, &crs, &path, i == li);
        all_digests.push(digs);
        if i == li {
            kept = keep;
        }
    }
    let lay = &layers[li];
    let ml = bf_layout(lay, t, shape, q);
    let BfCommitted { mut msgs, mut rhos8, mut t1s, mut t2s } = kept.expect("proven layer kept");

    // Aux commitments (m columns, blinders, masks) + session material.
    let mut rng = ring::ProverRng::from_test_seed(
        "uagb1-bf-session",
        &[(li as u64).to_le_bytes(), (t as u64).to_le_bytes()].concat(),
    );
    let mut pads_live: Option<WavePads> = if ml.pad_layout.has_pads() {
        Some(draw_wave_pads(&mut rng, q, &ml.pad_layout))
    } else {
        None
    };
    let pack_scalars = |vals: &[u64]| -> Vec<Poly> {
        assert!(vals.len() <= per);
        let mut polys = vec![poly_zero(); msg_r];
        for (i, &v) in vals.iter().enumerate() {
            polys[i / D][i % D] = v;
        }
        polys
    };
    let pack_kelems = |kelems: &[KElem]| -> Vec<Vec<Poly>> {
        let mut flat: Vec<u64> = Vec::with_capacity(kelems.len() * K_DEG);
        for e in kelems {
            flat.extend_from_slice(&e[..]);
        }
        (0..flat.len().div_ceil(per).max(1))
            .map(|g| {
                (0..msg_r)
                    .map(|s| {
                        (0..D)
                            .map(|c| {
                                let idx = g * per + s * D + c;
                                if idx < flat.len() { flat[idx] } else { 0 }
                            })
                            .collect()
                    })
                    .collect()
            })
            .collect()
    };
    let mut push_commit = |m: Vec<Poly>,
                           rng: &mut ring::ProverRng,
                           msgs: &mut Vec<Vec<Poly>>,
                           rhos8: &mut Vec<Vec<i8>>,
                           t1s: &mut Vec<Vec<Poly>>,
                           t2s: &mut Vec<Vec<Poly>>| {
        let rho: Vec<Vec<i64>> = (0..shape.n_r).map(|_| rng_ternary_poly(rng)).collect();
        let (t1, t2) = commit(&path, &crs, &m, &rho);
        msgs.push(m);
        rhos8.push(rho.iter().flat_map(|p| p.iter().map(|&x| x as i8)).collect());
        t1s.push(t1);
        t2s.push(t2);
    };
    // Per instance: the fused/code witness column + table + m column,
    // masks + blinders (committed BEFORE any challenge, D-4).
    struct InstMat {
        w_col: Vec<ring::kfield::KElem>,
        tab_k: Vec<ring::kfield::KElem>,
        m_k: Vec<ring::kfield::KElem>,
        masks_w: Option<ring::gkr_masked::MaskSet>,
        masks_t: Option<ring::gkr_masked::MaskSet>,
        bl_w: ring::gkr_masked::BlinderSet,
        bl_t: ring::gkr_masked::BlinderSet,
    }
    let mut inst_mat: Vec<InstMat> = Vec::with_capacity(ml.insts.len());
    // The WrongTable prover runs its SiLU instance against the wrong
    // member CONSISTENTLY (witness a8 was rederived above): its committed
    // m + trees use the wrong fused table.
    for inst in &ml.insts {
        let vals = bf_entry_values(inst.entry, lay);
        let (w_col, tab_k): (Vec<KElem>, Vec<KElem>) = if let Some((eg, ea)) = inst.silu {
            let (eg, ea) = if tamper == BfTamper::WrongTable {
                if eg == -3 { (-4, -4) } else { (-3, -3) }
            } else {
                (eg, ea)
            };
            let (bytes, _) = silu_v2_member(eg, ea).expect("frozen member");
            let rows = silu_v2_rows(bytes);
            let pair = bf_entry_values(inst.pair.unwrap(), lay);
            let w = vals
                .iter()
                .zip(pair.iter())
                .map(|(&x, &y)| fuse_pair(&kf, zq.to_mod(x), zq.to_mod(y)))
                .collect();
            let tk = rows.iter().map(|&(v, s)| fuse_pair(&kf, zq.to_mod(v), zq.to_mod(s))).collect();
            (w, tk)
        } else {
            let w = vals.iter().map(|&x| kf.embed(zq.to_mod(x + inst.offset))).collect();
            let tk = (0..inst.t_rows as u64).map(|j| kf.embed(j)).collect();
            (w, tk)
        };
        let m_k = multiplicities(&kf, &w_col, &tab_k);
        let m_vals: Vec<u64> = m_k.iter().map(|e| e[0]).collect();
        push_commit(pack_scalars(&m_vals), &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        let bw = BlinderSet::draw(&kf, &mut rng);
        let mut bt = BlinderSet::draw(&kf, &mut rng);
        bt.solve_mass(&kf, &bw.mass(&kf));
        let blinder_kelems: Vec<KElem> = {
            let mut v = Vec::with_capacity(16);
            for b in [&bw.tl, &bw.tr, &bw.f0, &bw.f1, &bt.tl, &bt.tr, &bt.f0, &bt.f1] {
                v.push(b.a.clone());
                v.push(b.u.clone());
            }
            v
        };
        let bl_msg = pack_kelems(&blinder_kelems);
        assert_eq!(bl_msg.len(), 1);
        push_commit(bl_msg.into_iter().next().unwrap(), &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        let mw = draw_masks(&kf, &mut rng, inst.dw, 0);
        let mt = draw_masks(&kf, &mut rng, inst.dt, 0);
        for m in pack_kelems(&mw.flatten()) {
            push_commit(m, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
        for m in pack_kelems(&mt.flatten()) {
            push_commit(m, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
        inst_mat.push(InstMat { w_col, tab_k, m_k, masks_w: Some(mw), masks_t: Some(mt), bl_w: bw, bl_t: bt });
    }
    assert_eq!(msgs.len(), ml.n_data);
    if ml.pad_layout.has_pads() {
        for m in pack_wave_pads(&mut rng, q, msg_r, &ml.pad_layout, pads_live.as_ref().unwrap())
            .expect("pad packing")
        {
            push_commit(m, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
    }
    for m in sample_ct_masks(&mut rng, q, msg_r, if ml.closing_g_groups > 0 { UR1_PIN_COPIES } else { 0 }) {
        push_commit(m, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
    }
    for _ in 0..ml.plan.waves.len() {
        for m in sample_ct_masks(&mut rng, q, msg_r, UR1_PIN_COPIES) {
            push_commit(m, &mut rng, &mut msgs, &mut rhos8, &mut t1s, &mut t2s);
        }
    }
    assert_eq!(msgs.len(), ml.n_commits);

    let mut cost = BfCost {
        n_data: ml.n_data,
        n_commits: ml.n_commits,
        n_waves: ml.plan.waves.len(),
        commit_s: t_commit.elapsed().as_secs_f64(),
        ..BfCost::default()
    };
    let mut verdict = BfVerdict {
        statement_ok: true,
        matmul_ok: [true; 3],
        hadamard_ok: true,
        roots_ok: vec![true; ml.insts.len()],
        sum_gate_ok: true,
        waves_ok: true,
        first_bad_wave: None,
        closing_ok: true,
    };

    // ---- The pass statement (all layers) and this layer's ctx. ----------
    // The proven layer's ENTRY digests recompute from the kept tags (the
    // tampered arms are self-consistent by construction).
    {
        let mut cursor = 0usize;
        let mut digs = Vec::with_capacity(17);
        for e in 0..17 {
            let n = ml.entry_cms[e];
            let cm_d: Vec<Vec<u8>> =
                (cursor..cursor + n).map(|i| group_digest(&t1s[i], &t2s[i])).collect();
            digs.push(group_list_digest(&cm_d));
            cursor += n;
        }
        all_digests[li] = digs;
    }
    let statement = m125_build_statement(t, layers, &all_digests, &crs.crs_hash);
    let lay = &layers[li];
    let ctx = match statement.digest() {
        Ok(d) => d,
        Err(e) => panic!("pass statement does not validate: {e}"),
    };
    cost.bytes_statement = statement.encode().len();
    cost.bytes_commit_tags = ml.n_commits * (shape.kappa + msg_r) * D * 4;
    let mut ctx_layer: Vec<u8> = ctx.to_vec();
    ctx_layer.extend((li as u64).to_le_bytes());
    let h0_layer = ct_h0(&crs, &ctx_layer, &t1s, &t2s, &[]);

    // ---- PROVER transcript. ---------------------------------------------
    let t_prove = Instant::now();
    let mut tr = LkpTranscript::new("uagb1-bf-pass", &h0_layer);
    let mut pins: Vec<PinnedValue> = Vec::new();
    let product2 = |kf: &KField, vals: &[KElem]| kf.mul(&vals[0], &vals[1]);
    let product3 =
        |kf: &KField, vals: &[KElem]| kf.mul(&kf.mul(&vals[0], &vals[1]), &vals[2]);

    // The three matmuls: (a_entry, b_entry, c_entry, rows, inner, cols).
    let matmuls: [(usize, usize, usize, usize, usize, usize); 3] = [
        (0, 1, 4, t, BF_D, BF_F),
        (0, 2, 8, t, BF_D, BF_F),
        (13, 3, 14, t, BF_F, BF_D),
    ];
    let lg2 = |n: usize| usize::BITS as usize - (n - 1).leading_zeros() as usize;
    // Builds the three MLE pins of one matmul instance from public
    // challenge tables (shared by prover and verifier).
    let matmul_pins = |ea: usize, eb: usize, ec: usize,
                       rows: usize, inner: usize, cols: usize,
                       eq_rx: &[KElem], eq_ry: &[KElem], eq_k: &[KElem],
                       v: &KElem, a_star: &KElem, b_star: &KElem|
     -> Vec<PinnedValue> {
        let scalar_terms = |base: usize, n_cms: usize, wf: &dyn Fn(usize) -> Option<KElem>| {
            let mut terms = Vec::new();
            for g in 0..n_cms {
                let lo = g * per;
                let mut weights: Vec<KElem> = Vec::with_capacity(per);
                let mut any = false;
                for c in 0..per {
                    match wf(lo + c) {
                        Some(w) => {
                            if !kf.is_zero(&w) {
                                any = true;
                            }
                            weights.push(w);
                        }
                        None => weights.push(kf.zero()),
                    }
                }
                if any {
                    terms.push(PinTerm::Scalar { commit: base + g, coeff0: 0, weights });
                }
            }
            terms
        };
        vec![
            PinnedValue {
                terms: scalar_terms(ml.entry_base[ec], ml.entry_cms[ec], &|f| {
                    if f < rows * cols { Some(kf.mul(&eq_rx[f / cols], &eq_ry[f % cols])) } else { None }
                }),
                value: v.clone(),
            },
            PinnedValue {
                terms: scalar_terms(ml.entry_base[ea], ml.entry_cms[ea], &|f| {
                    if f < rows * inner { Some(kf.mul(&eq_rx[f / inner], &eq_k[f % inner])) } else { None }
                }),
                value: a_star.clone(),
            },
            PinnedValue {
                terms: scalar_terms(ml.entry_base[eb], ml.entry_cms[eb], &|f| {
                    if f < inner * cols { Some(kf.mul(&eq_k[f / cols], &eq_ry[f % cols])) } else { None }
                }),
                value: b_star.clone(),
            },
        ]
    };

    let t_mm = Instant::now();
    let mut mm_proofs = Vec::new();
    for &(ea, eb, ec, rows, inner, cols) in &matmuls {
        let (lr, lk, lc) = (lg2(rows), lg2(inner), lg2(cols));
        let a_vals = bf_entry_values(ea, lay);
        let b_vals = bf_entry_values(eb, lay);
        let c_vals = bf_entry_values(ec, lay);
        let rx: Vec<KElem> = (0..lr).map(|_| tr.challenge_k(&kf)).collect();
        let ry: Vec<KElem> = (0..lc).map(|_| tr.challenge_k(&kf)).collect();
        let eq_rx = eq_table(&kf, &rx);
        let eq_ry = eq_table(&kf, &ry);
        let nk = 1usize << lk;
        let mut ta = vec![kf.zero(); nk];
        for i in 0..rows {
            let w = &eq_rx[i];
            if kf.is_zero(w) {
                continue;
            }
            for k in 0..inner {
                let v = a_vals[i * inner + k];
                if v != 0 {
                    ta[k] = kf.add(&ta[k], &kf.scale(zq.to_mod(v), w));
                }
            }
        }
        let mut tb = vec![kf.zero(); nk];
        for k in 0..inner {
            let row = &b_vals[k * cols..(k + 1) * cols];
            let mut acc = kf.zero();
            for (j, &v) in row.iter().enumerate() {
                if v != 0 {
                    acc = kf.add(&acc, &kf.scale(zq.to_mod(v), &eq_ry[j]));
                }
            }
            tb[k] = acc;
        }
        // v = C~(rx, ry) over the COMMITTED C.
        let mut v = kf.zero();
        for i in 0..rows {
            let row = &c_vals[i * cols..(i + 1) * cols];
            let mut ri = kf.zero();
            for (j, &cv) in row.iter().enumerate() {
                if cv != 0 {
                    ri = kf.add(&ri, &kf.scale(zq.to_mod(cv), &eq_ry[j]));
                }
            }
            v = kf.add(&v, &kf.mul(&ri, &eq_rx[i]));
        }
        tr.absorb_k(&kf, "bf-mm-claim", std::slice::from_ref(&v));
        let (scp, kstar) = sumcheck_prove(&kf, vec![ta, tb], 2, &product2, &mut tr);
        tr.absorb_k(&kf, "bf-mm-final", &scp.final_evals);
        cost.bytes_sumcheck +=
            64 * (1 + scp.rounds.iter().map(|r| r.len()).sum::<usize>() + scp.final_evals.len());
        let eq_k = eq_table(&kf, &kstar);
        pins.extend(matmul_pins(
            ea, eb, ec, rows, inner, cols, &eq_rx, &eq_ry, &eq_k, &v,
            &scp.final_evals[0], &scp.final_evals[1],
        ));
        mm_proofs.push((scp, v));
    }
    cost.matmul_s = t_mm.elapsed().as_secs_f64();

    // Hadamard a8 o u8 = H by one degree-3 sumcheck.
    let t_had = Instant::now();
    let n_f = t * BF_F;
    let lv_f = lg2(n_f);
    let had_proof = {
        let r2: Vec<KElem> = (0..lv_f).map(|_| tr.challenge_k(&kf)).collect();
        let eq_r2 = eq_table(&kf, &r2);
        let a8k: Vec<KElem> =
            lay.a8.iter().map(|&v| kf.embed(zq.to_mod(v))).chain((lay.a8.len()..1 << lv_f).map(|_| kf.zero())).collect();
        let u8k: Vec<KElem> =
            lay.u8v.iter().map(|&v| kf.embed(zq.to_mod(v))).chain((lay.u8v.len()..1 << lv_f).map(|_| kf.zero())).collect();
        let mut v_h = kf.zero();
        for (j, &hv) in lay.hh.iter().enumerate() {
            if hv != 0 {
                v_h = kf.add(&v_h, &kf.scale(zq.to_mod(hv), &eq_r2[j]));
            }
        }
        tr.absorb_k(&kf, "bf-had-claim", std::slice::from_ref(&v_h));
        let (scp, kstar) = sumcheck_prove(&kf, vec![eq_r2.clone(), a8k, u8k], 3, &product3, &mut tr);
        tr.absorb_k(&kf, "bf-had-final", &scp.final_evals);
        cost.bytes_sumcheck +=
            64 * (1 + scp.rounds.iter().map(|r| r.len()).sum::<usize>() + scp.final_evals.len());
        let eq_z = eq_table(&kf, &kstar);
        let col_pin = |e: usize, weights_tab: &[KElem], value: &KElem| PinnedValue {
            terms: (0..ml.entry_cms[e])
                .map(|g| PinTerm::Scalar {
                    commit: ml.entry_base[e] + g,
                    coeff0: 0,
                    weights: weights_tab[g * per..(g + 1) * per].to_vec(),
                })
                .collect(),
            value: value.clone(),
        };
        pins.push(col_pin(11, &eq_r2, &v_h));
        pins.push(col_pin(7, &eq_z, &scp.final_evals[1]));
        pins.push(col_pin(10, &eq_z, &scp.final_evals[2]));
        (scp, v_h)
    };
    cost.had_s = t_had.elapsed().as_secs_f64();

    // Requant edges as zero-valued MLE pins at transcript points.
    let t_req = Instant::now();
    let req_edges: [(usize, usize, usize, u32); 4] = [
        (4, 6, 5, lay.shifts.0),
        (8, 10, 9, lay.shifts.1),
        (11, 13, 12, lay.shifts.2),
        (14, 16, 15, lay.shifts.3),
    ];
    for &(xe, ye, re, shift) in &req_edges {
        let n_el = bf_entry_values(xe, lay).len();
        let lv = lg2(n_el);
        let r: Vec<KElem> = (0..lv).map(|_| tr.challenge_k(&kf)).collect();
        let lw = eq_table(&kf, &r);
        let two_s = zq.to_mod(1i64 << shift);
        let col_terms = |e: usize, f: &dyn Fn(&KElem) -> KElem| -> Vec<PinTerm> {
            (0..ml.entry_cms[e])
                .map(|g| PinTerm::Scalar {
                    commit: ml.entry_base[e] + g,
                    coeff0: 0,
                    weights: lw[g * per..(g + 1) * per].iter().map(f).collect(),
                })
                .collect()
        };
        let mut terms = col_terms(xe, &|w| w.clone());
        terms.extend(col_terms(ye, &|w| kf.neg(&kf.scale(two_s, w))));
        terms.extend(col_terms(re, &|w| kf.neg(w)));
        pins.push(PinnedValue { terms, value: kf.zero() });
    }
    cost.req_s = t_req.elapsed().as_secs_f64();

    // ---- Lookup instances: masked descent pairs + pins (prover). --------
    // Pin builders shared verbatim by the verifier (public data only).
    let descent_pins = |base: usize,
                        shape_masks: &MaskSet,
                        proof: &MaskedDescentProof,
                        end: &DescentEnd,
                        depth: usize|
     -> Vec<PinnedValue> {
        let kelem_terms = |base: usize, flat_off: usize, weights: &[KElem]| -> Vec<PinTerm> {
            let mut terms = Vec::new();
            let mut i = 0usize;
            while i < weights.len() {
                let idx = flat_off + i;
                let commit = base + idx / kpc;
                let coeff0 = (idx % kpc) * K_DEG;
                let take = (kpc - (idx % kpc)).min(weights.len() - i);
                terms.push(PinTerm::Kelems { commit, coeff0, weights: weights[i..i + take].to_vec() });
                i += take;
            }
            terms
        };
        let mut out = Vec::new();
        for j in 1..depth {
            let lp_j = &proof.layers[j - 1];
            let gm = &shape_masks.g[j - 1];
            out.push(PinnedValue {
                terms: kelem_terms(base, shape_masks.g_offset(j), &g_hypersum_weights(&kf, gm)),
                value: lp_j.g_sum.clone(),
            });
            let (open_pt, mu_prev, c_w) = &end.layer_pts[j - 1];
            out.push(PinnedValue {
                terms: kelem_terms(base, shape_masks.g_offset(j), &g_open_weights(&kf, gm, open_pt)),
                value: lp_j.open_g.clone(),
            });
            if j >= 2 {
                let (orp, orq) = lp_j.open_r.clone().expect("interior layer opens Rp/Rq");
                let rw = r_open_weights(&kf, mu_prev, c_w);
                out.push(PinnedValue {
                    terms: kelem_terms(base, shape_masks.r_offset(j), &rw),
                    value: orp,
                });
                out.push(PinnedValue {
                    terms: kelem_terms(base, shape_masks.r_offset(j) + 6, &rw),
                    value: orq,
                });
            }
        }
        out
    };
    // The four aggregate leaf pins of one instance: wp/wq/tp/tq. The
    // verifier's copy folds the STATEMENT's table values (fused for the
    // silu member, identity j for range tables) — the wrong-table leg's
    // reject point. [UAGB1-BJ, BF-F3 wiring] witness-side weights ride
    // the PUBLIC split map `witness_leaf_positions` (the trees already
    // do, inside blinded_witness_tree); `wrong_map` (battery hook,
    // WrongMap leg) recomputes them under the pre-lift contiguous
    // assumption — the acceptance test that the map is load-bearing.
    let leaf_pins = |inst: &BfInst,
                     tab_k: &[KElem],
                     endw: &DescentEnd,
                     endt: &DescentEnd,
                     alpha: &KElem,
                     wrong_map: bool|
     -> Vec<PinnedValue> {
        let (er, ec) = bf_entry_shape(inst.entry, t);
        let n_el = er * ec;
        let lw = eq_table(&kf, &endw.zstar);
        let lt = eq_table(&kf, &endt.zstar);
        let nw = 1usize << inst.dw;
        let nt = 1usize << inst.dt;
        let bpw = blinder_positions(nw);
        let bpt = blinder_positions(nt);
        let tpos = table_row_positions(inst.t_rows, nt);
        let wpos: Vec<usize> = if wrong_map {
            (0..n_el).collect() // the pre-lift contiguous assumption
        } else {
            witness_leaf_positions(n_el, nw)
        };
        let eqw: Vec<KElem> = bpw.iter().map(|&p| lw[p].clone()).collect();
        let eqt: Vec<KElem> = bpt.iter().map(|&p| lt[p].clone()).collect();
        let hw = (0..n_el).fold(zero.clone(), |a, i| kf.add(&a, &lw[wpos[i]]));
        let ht = (0..inst.t_rows).fold(zero.clone(), |a, j| kf.add(&a, &lt[tpos[j]]));
        let sum_eqw = eqw.iter().fold(zero.clone(), |a, e| kf.add(&a, e));
        let sum_eqt = eqt.iter().fold(zero.clone(), |a, e| kf.add(&a, e));
        let ft = (0..inst.t_rows)
            .fold(zero.clone(), |a, j| kf.add(&a, &kf.mul(&lt[tpos[j]], &tab_k[j])));
        let z = zero.clone();
        let wp = PinnedValue {
            terms: vec![PinTerm::Kelems {
                commit: inst.idx_bl,
                coeff0: 0,
                weights: vec![
                    eqw[0].clone(), z.clone(), eqw[1].clone(), z.clone(),
                    eqw[2].clone(), z.clone(), eqw[3].clone(), z.clone(),
                ],
            }],
            value: kf.sub(&endw.p_claim, &hw),
        };
        let ddw = kf.sub(&kf.sub(&one, &hw), &sum_eqw);
        let mut wq_terms = vec![PinTerm::Kelems {
            commit: inst.idx_bl,
            coeff0: 0,
            weights: vec![
                z.clone(), eqw[0].clone(), z.clone(), eqw[1].clone(),
                z.clone(), eqw[2].clone(), z.clone(), eqw[3].clone(),
            ],
        }];
        // -sum lw * value over the committed primary column (element i
        // sits at witness leaf wpos[i] — the split map)...
        for g in 0..ml.entry_cms[inst.entry] {
            let lo = g * per;
            let n_c = (n_el - lo).min(per);
            wq_terms.push(PinTerm::Scalar {
                commit: ml.entry_base[inst.entry] + g,
                coeff0: 0,
                weights: (0..n_c).map(|i| kf.neg(&lw[wpos[lo + i]])).collect(),
            });
        }
        // ... minus Y * the pair column (silu), both dense.
        if let Some(pe) = inst.pair {
            for g in 0..ml.entry_cms[pe] {
                let lo = g * per;
                let n_c = (n_el - lo).min(per);
                wq_terms.push(PinTerm::Scalar {
                    commit: ml.entry_base[pe] + g,
                    coeff0: 0,
                    weights: (0..n_c)
                        .map(|i| kf.neg(&ring::lookup::mul_y(&kf, &lw[wpos[lo + i]])))
                        .collect(),
                });
            }
        }
        // Code offset folds into the value: q = alpha - (value + offset).
        let mut wq_value = kf.sub(&kf.sub(&endw.q_claim, &kf.mul(alpha, &hw)), &ddw);
        if inst.offset != 0 {
            wq_value = kf.add(&wq_value, &kf.scale(zq.to_mod(inst.offset), &hw));
        }
        let wq = PinnedValue { terms: wq_terms, value: wq_value };
        let tp = PinnedValue {
            terms: vec![
                PinTerm::Scalar {
                    commit: inst.idx_m,
                    coeff0: 0,
                    weights: (0..inst.t_rows).map(|j| lt[tpos[j]].clone()).collect(),
                },
                PinTerm::Kelems {
                    commit: inst.idx_bl,
                    coeff0: 8 * K_DEG,
                    weights: vec![
                        eqt[0].clone(), z.clone(), eqt[1].clone(), z.clone(),
                        eqt[2].clone(), z.clone(), eqt[3].clone(), z.clone(),
                    ],
                },
            ],
            value: endt.p_claim.clone(),
        };
        let ddt = kf.sub(&kf.sub(&one, &ht), &sum_eqt);
        let tq = PinnedValue {
            terms: vec![PinTerm::Kelems {
                commit: inst.idx_bl,
                coeff0: 8 * K_DEG,
                weights: vec![
                    z.clone(), eqt[0].clone(), z.clone(), eqt[1].clone(),
                    z.clone(), eqt[2].clone(), z.clone(), eqt[3].clone(),
                ],
            }],
            value: kf.add(&kf.sub(&kf.sub(&endt.q_claim, &kf.mul(alpha, &ht)), &ddt), &ft),
        };
        vec![wp, wq, tp, tq]
    };
    // The STATEMENT-side table values of an instance (what the VERIFIER
    // folds — independent of the prover's choice).
    let stmt_tab_k = |inst: &BfInst| -> Vec<KElem> {
        if let Some((eg, ea)) = inst.silu {
            let (bytes, _) = silu_v2_member(eg, ea).expect("frozen member");
            silu_v2_rows(bytes)
                .iter()
                .map(|&(v, s)| fuse_pair(&kf, zq.to_mod(v), zq.to_mod(s)))
                .collect()
        } else {
            (0..inst.t_rows as u64).map(|j| kf.embed(j)).collect()
        }
    };

    let t_lkp = Instant::now();
    let mut inst_proofs: Vec<(MaskedDescentProof, MaskedDescentProof)> = Vec::new();
    for (ii, inst) in ml.insts.iter().enumerate() {
        let mat = &mut inst_mat[ii];
        let alpha = tr.challenge_k(&kf);
        let wtree = blinded_witness_tree(&kf, &alpha, &mat.w_col, inst.dw, &mat.bl_w);
        let (pw, endw) = masked_gkr_prove(&kf, &[wtree], mat.masks_w.take().unwrap(), &mut tr);
        let ttree = blinded_table_tree(&kf, &alpha, &mat.tab_k, &mat.m_k, inst.dt, &mat.bl_t);
        let (pt, endt) = masked_gkr_prove(&kf, &[ttree], mat.masks_t.take().unwrap(), &mut tr);
        let shell_w = zero_masks(&kf, inst.dw, 0);
        let shell_t = zero_masks(&kf, inst.dt, 0);
        pins.extend(descent_pins(inst.base_wm, &shell_w, &pw, &endw, inst.dw));
        pins.extend(descent_pins(inst.base_tm, &shell_t, &pt, &endt, inst.dt));
        // The PROVER folds its own table (the WrongTable arm folds the
        // wrong member so its pins are self-consistent; the verifier's
        // fold below is what rejects). Prover pins always ride the
        // honest split map.
        pins.extend(leaf_pins(inst, &mat.tab_k, &endw, &endt, &alpha, false));
        cost.bytes_descents += masked_pass_bytes(inst.dw, inst.dt, 0, 1);
        inst_proofs.push((pw, pt));
        mat.w_col = Vec::new(); // drop the fused column early
    }
    cost.lkp_s = t_lkp.elapsed().as_secs_f64();

    // ---- Pin batch -> psi claims -> masked wave split. ------------------
    let t_pc = Instant::now();
    for p in &pins {
        tr.absorb_k(&kf, "bf-pin", std::slice::from_ref(&p.value));
    }
    cost.n_pins = pins.len();
    let psi = derive_pin_psi(&tr.state(), UR1_PIN_COPIES, pins.len() * K_DEG, q);
    let claims_p = pin_claims(&kf, &pins, ml.n_data, msg_r, &psi);
    drop(pins);
    cost.pinclaims_s = t_pc.elapsed().as_secs_f64();
    let msg_refs: Vec<&[Poly]> = msgs[..ml.n_data].iter().map(|m| m.as_slice()).collect();
    let (mut pw_claims, reveals) = split_claims_prover_masked(
        &zq,
        &ml.plan,
        &claims_p,
        &msg_refs,
        &ml.pad_layout,
        pads_live.take().expect("pads drawn pre-challenge"),
    )
    .expect("honest masked split");
    drop(claims_p);
    if pw_claims.is_empty() {
        pw_claims = (0..ml.plan.waves.len()).map(|_| Vec::new()).collect();
    }
    cost.bytes_reveals = 12 * reveals.iter().map(|r| r.len()).sum::<usize>();

    // ---- Wave rounds + closing (the D2 pattern). ------------------------
    let t_waves = Instant::now();
    let n_waves = ml.plan.waves.len();
    let unpack_rho = |packed: &[i8]| -> Vec<Vec<i64>> {
        (0..shape.n_r)
            .map(|r| packed[r * D..(r + 1) * D].iter().map(|&b| b as i64).collect())
            .collect()
    };
    let wave_idxs = |w: usize| -> Vec<usize> {
        let mut v = ml.plan.waves[w].clone();
        if ml.pad_layout.has_pads() {
            v.push(ml.base_pad + w / ml.pad_layout.waves_per_cm);
        }
        let g0 = ml.base_wave_g + w * ml.wave_g_groups;
        v.extend(g0..g0 + ml.wave_g_groups);
        v
    };
    let mut wave_proofs: Vec<ring::ct_engine::CtRoundProof> = Vec::with_capacity(n_waves);
    let mut rp_cache: std::collections::BTreeMap<usize, (ring::ct_engine::CtRoundParams, ring::commit::A1Paths)> =
        std::collections::BTreeMap::new();
    let tr_state = tr.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        assert!(n_cw <= ml.c2_max);
        if !rp_cache.contains_key(&n_cw) {
            let rp = derive_ct_round_params(q, shape, n_cw, 0, 0, true);
            let a1pw = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cw, (rp, a1pw));
        }
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).unwrap();
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut pw_claims[w]);
        let wrhos: Vec<Vec<Vec<i64>>> = idxs.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings: Vec<StdOpening> = idxs
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &wrhos[j] })
            .collect();
        let mut state_p: Vec<u8> = tr_state.to_vec();
        state_p.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t2s[i].clone()).collect();
        let h0_w = ct_h0(&crs, &state_p, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(ml.pad_layout.has_pads());
        let (proof_w, _) = prove_ct_round(
            &path_w, &ctx_ring, rp_w, None, &crs, &h0_w, &claims_w, &[], &[], &[], &openings,
            &[], &[], ml.plan.waves[w].len() + pad_shift, &mut rng,
        );
        cost.bytes_ct_z += n_cw * shape.n_r * D * 8;
        cost.bytes_ct_w1 += n_cw * shape.kappa * D * 4;
        cost.bytes_ct_other += claims_w.len() * D * 4 * 2;
        wave_proofs.push(proof_w);
    }
    let closing_proof = if ml.pad_layout.has_pads() {
        let idxs_z: Vec<usize> = (ml.base_pad..ml.base_pad + ml.pad_layout.n_pad_cms)
            .chain(ml.base_closing_g..ml.base_closing_g + ml.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        if !rp_cache.contains_key(&n_cz) {
            let rp = derive_ct_round_params(q, shape, n_cz, 0, 0, true);
            let a1pz = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cz, (rp, a1pz));
        }
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).unwrap();
        let path_z = KernelPath::A1(a1p_z);
        let claims_z = closing_round_claims(&zq, &ml.pad_layout);
        let mut state_z: Vec<u8> = tr_state.to_vec();
        state_z.extend(b"bf-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t2s[i].clone()).collect();
        let h0_z = ct_h0(&crs, &state_z, &zt1s, &zt2s, &[]);
        let zrhos: Vec<Vec<Vec<i64>>> = idxs_z.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings_z: Vec<StdOpening> = idxs_z
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &zrhos[j] })
            .collect();
        let (proof_z, _) = prove_ct_round(
            &path_z, &ctx_ring, rp_z, None, &crs, &h0_z, &claims_z, &[], &[], &[], &openings_z,
            &[], &[], ml.pad_layout.n_pad_cms, &mut rng,
        );
        cost.bytes_ct_z += n_cz * shape.n_r * D * 8;
        cost.bytes_ct_w1 += n_cz * shape.kappa * D * 4;
        cost.bytes_ct_other += claims_z.len() * D * 4 * 2;
        Some(proof_z)
    } else {
        None
    };
    cost.waves_s = t_waves.elapsed().as_secs_f64();
    cost.prove_s = t_prove.elapsed().as_secs_f64();

    // ---- VERIFIER. ------------------------------------------------------
    // Statement gate (the P0 model-identity discipline): the verifier
    // rebuilds the pass statement from the PUBLIC model — honest export
    // data reloaded, weight commitments RECOMPUTED under their public
    // seeds — plus the RECEIVED witness commitment tags, and compares
    // digests. A wrong-weight prover (self-consistent or not) fails
    // HERE, before any crypto.
    let t_verify = Instant::now();
    let honest_li = bf_load_layer(li, t, true);
    {
        let mut v_digests = all_digests.clone();
        let (honest_digs, _) = bf_commit_entries(&honest_li, t, shape, &crs, &path, false);
        for e in 1..=3 {
            v_digests[li][e] = honest_digs[e].clone();
        }
        let saved = std::mem::replace(&mut layers[li], honest_li);
        let statement_v = m125_build_statement(t, layers, &v_digests, &crs.crs_hash);
        layers[li] = saved;
        let ctx_v = statement_v.digest().expect("verifier statement validates");
        if ctx_v != ctx {
            verdict.statement_ok = false;
            cost.verify_s = t_verify.elapsed().as_secs_f64();
            return (verdict, cost);
        }
    }
    let mut tv = LkpTranscript::new("uagb1-bf-pass", &h0_layer);
    let mut pins_v: Vec<PinnedValue> = Vec::new();
    for (mi, &(ea, eb, ec, rows, inner, cols)) in matmuls.iter().enumerate() {
        let (lr, lk, lc) = (lg2(rows), lg2(inner), lg2(cols));
        let (scp, v_claim) = &mm_proofs[mi];
        let rx: Vec<KElem> = (0..lr).map(|_| tv.challenge_k(&kf)).collect();
        let ry: Vec<KElem> = (0..lc).map(|_| tv.challenge_k(&kf)).collect();
        tv.absorb_k(&kf, "bf-mm-claim", std::slice::from_ref(v_claim));
        let sc = sumcheck_verify(&kf, lk, 2, v_claim, scp, &product2, &mut tv);
        tv.absorb_k(&kf, "bf-mm-final", &scp.final_evals);
        match sc {
            Some((kstar, _)) => {
                let eq_rx = eq_table(&kf, &rx);
                let eq_ry = eq_table(&kf, &ry);
                let eq_k = eq_table(&kf, &kstar);
                pins_v.extend(matmul_pins(
                    ea, eb, ec, rows, inner, cols, &eq_rx, &eq_ry, &eq_k, v_claim,
                    &scp.final_evals[0], &scp.final_evals[1],
                ));
            }
            None => {
                verdict.matmul_ok[mi] = false;
            }
        }
    }
    {
        let (scp, v_h) = &had_proof;
        let r2: Vec<KElem> = (0..lv_f).map(|_| tv.challenge_k(&kf)).collect();
        tv.absorb_k(&kf, "bf-had-claim", std::slice::from_ref(v_h));
        let sc = sumcheck_verify(&kf, lv_f, 3, v_h, scp, &product3, &mut tv);
        tv.absorb_k(&kf, "bf-had-final", &scp.final_evals);
        match sc {
            Some((kstar, _)) => {
                // The eq-table final is verifier-computable; a lying
                // prover cannot shift mass into it.
                if scp.final_evals[0] != bf_eq_point(&kf, &r2, &kstar) {
                    verdict.hadamard_ok = false;
                }
                let eq_r2 = eq_table(&kf, &r2);
                let eq_z = eq_table(&kf, &kstar);
                let col_pin = |e: usize, weights_tab: &[KElem], value: &KElem| PinnedValue {
                    terms: (0..ml.entry_cms[e])
                        .map(|g| PinTerm::Scalar {
                            commit: ml.entry_base[e] + g,
                            coeff0: 0,
                            weights: weights_tab[g * per..(g + 1) * per].to_vec(),
                        })
                        .collect(),
                    value: value.clone(),
                };
                pins_v.push(col_pin(11, &eq_r2, v_h));
                pins_v.push(col_pin(7, &eq_z, &scp.final_evals[1]));
                pins_v.push(col_pin(10, &eq_z, &scp.final_evals[2]));
            }
            None => {
                verdict.hadamard_ok = false;
            }
        }
    }
    for &(xe, ye, re, shift) in &req_edges {
        let (er, ec) = bf_entry_shape(xe, t);
        let lv = lg2(er * ec);
        let r: Vec<KElem> = (0..lv).map(|_| tv.challenge_k(&kf)).collect();
        let lw = eq_table(&kf, &r);
        let two_s = zq.to_mod(1i64 << shift);
        let col_terms = |e: usize, f: &dyn Fn(&KElem) -> KElem| -> Vec<PinTerm> {
            (0..ml.entry_cms[e])
                .map(|g| PinTerm::Scalar {
                    commit: ml.entry_base[e] + g,
                    coeff0: 0,
                    weights: lw[g * per..(g + 1) * per].iter().map(f).collect(),
                })
                .collect()
        };
        let mut terms = col_terms(xe, &|w| w.clone());
        terms.extend(col_terms(ye, &|w| kf.neg(&kf.scale(two_s, w))));
        terms.extend(col_terms(re, &|w| kf.neg(w)));
        pins_v.push(PinnedValue { terms, value: kf.zero() });
    }
    let t_vlkp = Instant::now();
    for (ii, inst) in ml.insts.iter().enumerate() {
        let (pw, pt) = &inst_proofs[ii];
        let alpha = tv.challenge_k(&kf);
        let shell_w = zero_masks(&kf, inst.dw, 0);
        let shell_t = zero_masks(&kf, inst.dt, 0);
        let vw = masked_gkr_verify(&kf, 1, inst.dw, &shell_w, pw, &mut tv, false);
        let vt = masked_gkr_verify(&kf, 1, inst.dt, &shell_t, pt, &mut tv, false);
        match (vw, vt) {
            (Some((roots_w, ew)), Some((roots_t, et))) => {
                let mut ok = !kf.is_zero(&roots_w[0][1]) && !kf.is_zero(&roots_t[0][1]);
                ok &= kf.mul(&roots_w[0][0], &roots_t[0][1])
                    == kf.mul(&roots_t[0][0], &roots_w[0][1]);
                verdict.roots_ok[ii] = ok;
                pins_v.extend(descent_pins(inst.base_wm, &shell_w, pw, &ew, inst.dw));
                pins_v.extend(descent_pins(inst.base_tm, &shell_t, pt, &et, inst.dt));
                // The verifier folds the STATEMENT's table — the
                // wrong-table reject point.
                pins_v.extend(leaf_pins(
                    inst,
                    &stmt_tab_k(inst),
                    &ew,
                    &et,
                    &alpha,
                    tamper == BfTamper::WrongMap, // [UAGB1-BJ] the wrong-map leg
                ));
            }
            _ => {
                verdict.roots_ok[ii] = false;
            }
        }
    }
    cost.verify_lkp_s = t_vlkp.elapsed().as_secs_f64();
    for p in &pins_v {
        tv.absorb_k(&kf, "bf-pin", std::slice::from_ref(&p.value));
    }
    let psi_v = derive_pin_psi(&tv.state(), UR1_PIN_COPIES, pins_v.len() * K_DEG, q);
    let claims_v = pin_claims(&kf, &pins_v, ml.n_data, msg_r, &psi_v);
    drop(pins_v);
    let v_split = split_claims_verifier_masked(&zq, &ml.plan, &claims_v, &reveals, &ml.pad_layout);
    drop(claims_v);
    let mut vw_claims: Vec<Vec<CtClaim>> = match v_split {
        Ok(v) => v,
        Err(_) => {
            verdict.sum_gate_ok = false;
            verdict.waves_ok = false;
            cost.verify_s = t_verify.elapsed().as_secs_f64();
            return (verdict, cost);
        }
    };
    if vw_claims.is_empty() {
        vw_claims = (0..n_waves).map(|_| Vec::new()).collect();
    }
    let t_vw = Instant::now();
    let tv_state = tv.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).expect("verifier derives the same round shapes");
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut vw_claims[w]);
        let mut state_v: Vec<u8> = tv_state.to_vec();
        state_v.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t2s[i].clone()).collect();
        let h0_wv = ct_h0(&crs, &state_v, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(ml.pad_layout.has_pads());
        let ok_w = verify_ct_round(
            &path_w, &ctx_ring, rp_w, None, &crs, &h0_wv, &claims_w, &[], &[], &[], &wt1s, &wt2s,
            &[], &[], &[], ml.plan.waves[w].len() + pad_shift, &wave_proofs[w],
        );
        if !ok_w {
            verdict.waves_ok = false;
            if verdict.first_bad_wave.is_none() {
                verdict.first_bad_wave = Some(w);
            }
        }
    }
    if let Some(proof_z) = &closing_proof {
        let idxs_z: Vec<usize> = (ml.base_pad..ml.base_pad + ml.pad_layout.n_pad_cms)
            .chain(ml.base_closing_g..ml.base_closing_g + ml.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).expect("closing shape derived");
        let path_z = KernelPath::A1(a1p_z);
        let claims_zv = closing_round_claims(&zq, &ml.pad_layout);
        let mut state_zv: Vec<u8> = tv_state.to_vec();
        state_zv.extend(b"bf-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t2s[i].clone()).collect();
        let h0_zv = ct_h0(&crs, &state_zv, &zt1s, &zt2s, &[]);
        if !verify_ct_round(
            &path_z, &ctx_ring, rp_z, None, &crs, &h0_zv, &claims_zv, &[], &[], &[], &zt1s, &zt2s,
            &[], &[], &[], ml.pad_layout.n_pad_cms, proof_z,
        ) {
            verdict.closing_ok = false;
        }
    }
    cost.verify_waves_s = t_vw.elapsed().as_secs_f64();
    cost.verify_s = t_verify.elapsed().as_secs_f64();
    if !quiet {
        println!(
            "  layer {li}: accept={} | {} data cms ({} commitments, {} waves, {} pins) | commit {:.1}s prove {:.1}s (mm {:.1} had {:.1} req {:.1} lkp {:.1} pinclaims {:.1} waves {:.1}) verify {:.1}s (lkp {:.1} waves {:.1})",
            verdict.accept(), ml.n_data, ml.n_commits, n_waves, cost.n_pins,
            cost.commit_s, cost.prove_s, cost.matmul_s, cost.had_s, cost.req_s, cost.lkp_s,
            cost.pinclaims_s, cost.waves_s, cost.verify_s, cost.verify_lkp_s, cost.verify_waves_s
        );
    }
    (verdict, cost)
}

// ===========================================================================
// [UAGB1-BH] U-AG-B1 wave 3 lane BH: VERIFIER PERFORMANCE.
//
// (1) The Greyhound row-column split of the eval-proof claim kernel
//     (PARAMS 2.2/5.3): ring/eval_proof.rs `psi_level0_factored` +
//     `transport_level_from_psi`, consumed by agg_verify_group's
//     recursed path (marked [UAGB1-BH] edits there). The verifier no
//     longer materializes Phi_0 (n_0 ring elements) or the N-value
//     weight table; Psi_0 — the single Phi_0-derived object the
//     transported chain needs — is assembled from the rank-1 kernel
//     factors. Exact mod-q identity => bit-identical transcripts and
//     verdicts; asserted by the differential legs below and by BD's
//     agg-matmul battery re-running green on the new verifier.
// (2) BF-F3: the gkr_masked witness-tree capacity lift — the split
//     fill (capacity n - 8, `witness_leaf_positions`), bit-identical
//     below the historical 2^(d-1)-4 cap; measured dw 22 -> 21 at the
//     2^20-element pass shape.
//
// Subcommands: `bh-verifier battery` (differential + BF-F3 legs),
// `bh-verifier kernel [rows inner cols]` (reference-vs-factored Psi_0
// timing + equality at a full shape), `bh-verifier gkr [log2_els]`
// (the BF-F3 tree-work measurement).

/// Deterministic battery kernels for a group (transcript-independent
/// random K material — the claim-kernel algebra is kernel-agnostic).
fn bh_random_kernels(
    kf: &ring::kfield::KField,
    group: &ring::eval_proof::AggGroup,
    seed: u64,
) -> Vec<ring::eval_proof::TensorClaimKernel> {
    group
        .tensors
        .iter()
        .enumerate()
        .map(|(ti, t)| {
            let mut rd = XofReader::new(
                "bh-kernels",
                &[&seed.to_le_bytes(), group.name.as_bytes(), &(ti as u64).to_le_bytes()],
            );
            ring::eval_proof::TensorClaimKernel {
                tensor_idx: ti,
                row_kernel: (0..t.rows).map(|_| kf.uniform(&mut rd)).collect(),
                col_kernel: (0..t.cols).map(|_| kf.uniform(&mut rd)).collect(),
            }
        })
        .collect()
}

/// The VERBATIM wave-2 verifier claim-kernel pipeline (the removed
/// code, kept as the differential oracle): N-value weight table ->
/// per-ring bpolys -> Phi_0 -> compute_psi.
fn bh_psi_reference(
    ctxr: &RingCtx,
    kf: &ring::kfield::KField,
    group: &ring::eval_proof::AggGroup,
    kernels: &[ring::eval_proof::TensorClaimKernel],
    alphas: &[Poly],
    cs: &[Vec<i64>],
    chunk: usize,
) -> (Vec<Poly>, Vec<Poly>) {
    let zq = &ctxr.zq;
    let vw = agg_value_weights(kf, group, kernels);
    let mut phi = Vec::with_capacity(group.n_digit_rings);
    for u in 0..group.n_digit_rings {
        let bp = agg_bpolys(kf, group, &vw, u);
        let mut acc = poly_zero();
        for (a, b) in alphas.iter().zip(bp.iter()) {
            acc = poly_add(zq, &acc, &ring_mul_split_kara_fast(ctxr, a, b));
        }
        phi.push(acc);
    }
    let psi = ring::eval_proof::compute_psi(ctxr, &phi, chunk, cs);
    (phi, psi)
}

/// One differential leg: factored Psi_0 == the wave-2 reference,
/// coefficient-for-coefficient, on both W-C groups of a shape.
fn bh_psi_leg(rows: usize, inner: usize, cols: usize, force_levels: Option<usize>, seed: u64) {
    use ring::eval_proof::{plan_schedule, psi_level0_factored};
    use ring::kfield::{KField, K_DEG};
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let q = ctxr.zq.q;
    let (gw, ga, _) = agg_build_groups(rows, inner, cols);
    let mut st = [0u8; 32];
    st[..8].copy_from_slice(&seed.to_le_bytes());
    for (g, e0) in [(&gw, 1u32), (&ga, 2u32)] {
        let sched = plan_schedule(g.n_digit_rings, e0, q, force_levels);
        assert!(!sched.levels.is_empty(), "differential leg needs a recursed schedule");
        let plan0 = &sched.levels[0];
        let kernels = bh_random_kernels(&kf, g, seed);
        let alphas: Vec<Poly> =
            (0..K_DEG).map(|i| ring::eval_proof::draw_alpha(&st, "bh-alpha", i as u64, q)).collect();
        let cs: Vec<Vec<i64>> = (0..plan0.r)
            .map(|j| ring::eval_proof::draw_quinary_capped(&st, "bh-c", j as u64).0)
            .collect();
        let (phi_ref, psi_ref) =
            bh_psi_reference(&ctxr, &kf, g, &kernels, &alphas, &cs, plan0.chunk);
        let psi_fac =
            psi_level0_factored(&ctxr, &kf, g, &kernels, &alphas, &cs, plan0.chunk);
        let aligned = g.tensors.iter().all(|t| t.cols % D == 0);
        assert_true(
            &format!(
                "psi differential [{}x{}x{} {}]: factored == wave-2 reference (n0 {}, chunk {}, r {}, {})",
                rows, inner, cols, g.name, g.n_digit_rings, plan0.chunk, plan0.r,
                if aligned { "aligned" } else { "MISALIGNED cols -> generic branch" }
            ),
            psi_fac == psi_ref,
        );
        // The library's per-ring reference oracle ties to the bin
        // pipeline too (small groups only — it is O(n0 * D) K-mults).
        if g.n_digit_rings <= 4_096 {
            let phi_lib = ring::eval_proof::phi0_reference(&ctxr, &kf, g, &kernels, &alphas);
            assert_true(
                &format!("phi0 oracle [{}]: library per-ring == bin vw pipeline", g.name),
                phi_lib == phi_ref,
            );
        }
    }
}

/// BF-F3 battery: the split fill's layout identity below the cap, the
/// beyond-cap honest/tamper legs at depth 6, and the capacity gates.
fn bh_gkr_legs() {
    use ring::gkr_masked::{
        blinded_witness_tree, blinder_positions, draw_masks, install_blinders,
        masked_gkr_prove, masked_gkr_verify, witness_leaf_positions, BlinderSet,
    };
    use ring::gkr::eq_table;
    use ring::kfield::KField;
    use ring::sumcheck::LkpTranscript;
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    // (i) Below the cap the map is the identity (the historical layout).
    for (w, dp) in [(28usize, 6usize), (100, 8), (2044, 12)] {
        let n = 1usize << dp;
        assert!(w <= n / 2 - 4);
        let pos = witness_leaf_positions(w, n);
        assert_true(
            &format!("BF-F3 layout identity below the cap (w = {w}, depth {dp})"),
            pos.iter().enumerate().all(|(j, &p)| p == j),
        );
    }
    // (ii) Below the cap the LEAF VECTORS equal the historical fill
    // (build_tree is deterministic in its leaves, so tree identity
    // follows; roots compared as a sanity face).
    {
        let mut rng = ring::ProverRng::from_test_seed("bh-gkr-id", b"leg2");
        let mut rd = XofReader::new("bh-gkr-alpha", &[b"leg2"]);
        let alpha = kf.uniform(&mut rd);
        let dp = 8usize;
        let n = 1usize << dp;
        let w: Vec<ring::kfield::KElem> = (0..100).map(|_| kf.uniform(&mut rd)).collect();
        let bl = BlinderSet::draw(&kf, &mut rng);
        // Historical fill (the pre-wave-3 body, inline).
        let (mut p_old, mut q_old) = (vec![kf.zero(); n], vec![kf.one(); n]);
        for (i, wv) in w.iter().enumerate() {
            p_old[i] = kf.one();
            q_old[i] = kf.sub(&alpha, wv);
        }
        install_blinders(&kf, &mut p_old, &mut q_old, &bl);
        // Split fill via the public map.
        let pos = witness_leaf_positions(w.len(), n);
        let (mut p_new, mut q_new) = (vec![kf.zero(); n], vec![kf.one(); n]);
        for (wv, &i) in w.iter().zip(pos.iter()) {
            p_new[i] = kf.one();
            q_new[i] = kf.sub(&alpha, wv);
        }
        install_blinders(&kf, &mut p_new, &mut q_new, &bl);
        assert_true(
            "BF-F3 leaf vectors below the cap == historical fill (bit-identical trees follow)",
            p_old == p_new && q_old == q_new,
        );
        let t_old = ring::gkr::build_tree(&kf, p_old, q_old);
        let t_new = blinded_witness_tree(&kf, &alpha, &w, dp, &bl);
        assert_true("BF-F3 roots below the cap unchanged", t_old.root() == t_new.root());
    }
    // (iii) Beyond the cap: honest end-to-end masked descent at depth
    // 6 with w = 40 > 28 = the historical cap; leaf claims checked
    // against the SPLIT layout (the house pin-modelling convention).
    let dp = 6usize;
    let n = 1usize << dp;
    let w_len = 40usize;
    let run = |w: &[ring::kfield::KElem],
               pin_positions: &[usize],
               pin_w: &[ring::kfield::KElem],
               alpha: &ring::kfield::KElem,
               bl: &BlinderSet,
               seed: &[u8]|
     -> (bool, bool, bool) {
        let mut rng = ring::ProverRng::from_test_seed("bh-gkr-e2e", seed);
        let masks = draw_masks(&kf, &mut rng, dp, 0);
        let tree = blinded_witness_tree(&kf, alpha, w, dp, bl);
        let root = tree.root();
        let mut tr = LkpTranscript::new("bh-gkr", seed);
        let (proof, end) = masked_gkr_prove(&kf, &[tree], masks, &mut tr);
        let mut rng2 = ring::ProverRng::from_test_seed("bh-gkr-e2e", seed);
        let masks2 = draw_masks(&kf, &mut rng2, dp, 0);
        let mut tv = LkpTranscript::new("bh-gkr", seed);
        let Some((roots, endv)) = masked_gkr_verify(&kf, 1, dp, &masks2, &proof, &mut tv, true)
        else {
            return (false, false, false);
        };
        let roots_ok = roots.len() == 1 && roots[0] == root;
        // The aggregate leaf-pin model: p*/q* are the true leaf MLEs;
        // the committed-column side is rebuilt from (pin_w at
        // pin_positions, blinders, dummies) — the verifier's view.
        let lw = eq_table(&kf, &endv.zstar);
        let blp = blinder_positions(n);
        let hw = pin_positions.iter().fold(kf.zero(), |a, &p| kf.add(&a, &lw[p]));
        let wsum = pin_positions
            .iter()
            .zip(pin_w.iter())
            .fold(kf.zero(), |a, (&p, wv)| kf.add(&a, &kf.mul(&lw[p], wv)));
        let bl_items = [&bl.tl, &bl.tr, &bl.f0, &bl.f1];
        let asum = blp
            .iter()
            .zip(bl_items.iter())
            .fold(kf.zero(), |a, (&p, b)| kf.add(&a, &kf.mul(&lw[p], &b.a)));
        let usum = blp
            .iter()
            .zip(bl_items.iter())
            .fold(kf.zero(), |a, (&p, b)| kf.add(&a, &kf.mul(&lw[p], &b.u)));
        let sum_eqbl = blp.iter().fold(kf.zero(), |a, &p| kf.add(&a, &lw[p]));
        let p_want = kf.add(&hw, &asum);
        let dummies = kf.sub(&kf.sub(&kf.sub(&kf.one(), &hw), &sum_eqbl), &kf.zero());
        let q_want = kf.add(
            &kf.add(&kf.sub(&kf.mul(alpha, &hw), &wsum), &usum),
            &dummies,
        );
        (true, roots_ok, endv.p_claim == p_want && endv.q_claim == q_want)
    };
    let mut rd = XofReader::new("bh-gkr-alpha", &[b"leg3"]);
    let alpha = kf.uniform(&mut rd);
    let w: Vec<ring::kfield::KElem> = (0..w_len).map(|_| kf.uniform(&mut rd)).collect();
    let mut rng = ring::ProverRng::from_test_seed("bh-gkr-bl", b"leg3");
    let bl = BlinderSet::draw(&kf, &mut rng);
    let pos = witness_leaf_positions(w_len, n);
    assert_true(
        &format!(
            "BF-F3 beyond-cap positions valid (w = {w_len} > cap 28 at depth 6; right block at n/2)"
        ),
        pos[27] == 27 && pos[28] == 32 && pos.iter().all(|p| !blinder_positions(n).contains(p)),
    );
    let (ok, roots_ok, pins_ok) = run(&w, &pos, &w, &alpha, &bl, b"honest");
    assert_true(
        "BF-F3 beyond-cap HONEST: masked descent verifies, derived roots match, leaf P/Q pins \
         match the split layout",
        ok && roots_ok && pins_ok,
    );
    // Tamper: one honest value in the RIGHT block changed — the leaf
    // Q pin against the true committed column must reject.
    let mut w_bad = w.clone();
    w_bad[35] = kf.add(&w_bad[35], &kf.one());
    let (ok, roots_ok, pins_ok) = run(&w_bad, &pos, &w, &alpha, &bl, b"tamper");
    assert_true(
        "BF-F3 beyond-cap TAMPER (right-block leaf): descent self-consistent but the leaf pin \
         REJECTS against the true column",
        ok && roots_ok && !pins_ok,
    );
    // Wrong map: pins computed as if the fill were contiguous — the
    // position map is load-bearing.
    let wrong_pos: Vec<usize> = (0..w_len).collect();
    let (ok, _roots_ok, pins_ok) = run(&w, &wrong_pos, &w, &alpha, &bl, b"wrongmap");
    assert_true(
        "BF-F3 beyond-cap WRONG MAP (contiguous assumption): leaf pins REJECT — the split map \
         is load-bearing",
        ok && !pins_ok,
    );
    // (iv) Capacity gates + frozen blinder positions.
    {
        let n = 64usize;
        let pos = witness_leaf_positions(n - 8, n);
        let blp = blinder_positions(n);
        let mut seen = vec![false; n];
        let all_ok = pos.iter().all(|&p| {
            let fresh = p < n && !seen[p] && !blp.contains(&p);
            if p < n {
                seen[p] = true;
            }
            fresh
        });
        assert_true(
            "BF-F3 capacity n - 8: all positions distinct, in range, off the blinder slots",
            all_ok && pos.len() == n - 8,
        );
        assert_true(
            "BF-F3 blinder positions UNCHANGED (LKP-6 layout: [28, 60, 30, 61] at n = 64)",
            blp == [28, 60, 30, 61],
        );
    }
}

/// `bh-verifier battery`: the lane's differential + BF-F3 legs.
fn uagb1_bh_battery() {
    println!("\n[UAGB1-BH] verifier-performance battery");
    let t = Instant::now();
    // D1 differential legs: aligned multi-tensor (mixed l0 5/13),
    // forced-depth variants, and the misaligned-cols generic branch.
    bh_psi_leg(128, 768, 256, Some(2), 0xB1B_0001);
    bh_psi_leg(128, 768, 256, Some(1), 0xB1B_0002);
    bh_psi_leg(64, 96, 128, Some(1), 0xB1B_0003); // A cols = 96: generic branch
    // D1 end-to-end: the recursed runner honest + sharpest tamper at a
    // battery shape (the full 23-leg battery is `agg-matmul battery`,
    // re-run green at this HEAD — deliverable 3).
    let (v, _) = uagb1_agg_run(128, 768, 256, AggTamper::None, false, Some(2), 0xB1_3004, true);
    assert_true("row-column verifier: honest ACCEPT at 128x768x256 (2 levels)", v.accept());
    let (v, _) = uagb1_agg_run(128, 768, 256, AggTamper::OoaFloor, false, Some(2), 0xB1_3007, true);
    assert_true(
        "row-column verifier: OOA floor pair still caught by the alphabet gate ONLY",
        !v.accept() && v.first_fail == Some("floor-alphabet"),
    );
    // D2 legs.
    bh_gkr_legs();
    println!("\n[UAGB1-BH] battery passed in {:.2}s", t.elapsed().as_secs_f64());
}

/// `bh-verifier kernel [rows inner cols]`: the claim-kernel phase in
/// isolation at a full shape — wave-2 reference vs the row-column
/// split, timed, with the exact-equality assertion. [MAC-BOX].
fn uagb1_bh_kernel_bench(rows: usize, inner: usize, cols: usize) {
    use ring::eval_proof::{plan_schedule, psi_level0_factored};
    use ring::kfield::{KField, K_DEG};
    println!(
        "[UAGB1-BH] claim-kernel phase at {rows}x{inner}x{cols}: wave-2 reference (N-value \
         K-mult table + Phi_0 at n0 x 16 ring-mults + fold) vs the row-column split \
         [MAC-BOX, non-reference]"
    );
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let q = ctxr.zq.q;
    let (gw, ga, _) = agg_build_groups(rows, inner, cols);
    let mut st = [0u8; 32];
    st[..8].copy_from_slice(&0xB1B_0010u64.to_le_bytes());
    for (g, e0) in [(&gw, 1u32), (&ga, 2u32)] {
        let sched = plan_schedule(g.n_digit_rings, e0, q, None);
        assert!(!sched.levels.is_empty());
        let plan0 = &sched.levels[0];
        let kernels = bh_random_kernels(&kf, g, 0xB1B_0010);
        let alphas: Vec<Poly> =
            (0..K_DEG).map(|i| ring::eval_proof::draw_alpha(&st, "bh-alpha", i as u64, q)).collect();
        let cs: Vec<Vec<i64>> = (0..plan0.r)
            .map(|j| ring::eval_proof::draw_quinary_capped(&st, "bh-c", j as u64).0)
            .collect();
        let t0 = Instant::now();
        let (_phi, psi_ref) = bh_psi_reference(&ctxr, &kf, g, &kernels, &alphas, &cs, plan0.chunk);
        let t_ref = t0.elapsed().as_secs_f64();
        let t1 = Instant::now();
        let psi_fac = psi_level0_factored(&ctxr, &kf, g, &kernels, &alphas, &cs, plan0.chunk);
        let t_fac = t1.elapsed().as_secs_f64();
        assert!(psi_fac == psi_ref, "kernel-phase differential MUST be exact");
        println!(
            "  [{}] n0 {} digit rings (chunk {}, r {}): reference {:.3}s -> factored {:.3}s \
             ({:.1}x) | psi EXACT-EQUAL",
            g.name,
            g.n_digit_rings,
            plan0.chunk,
            plan0.r,
            t_ref,
            t_fac,
            t_ref / t_fac.max(1e-9),
        );
        // Residual attribution: the verifier's remaining heavy term is
        // the level-0 CRS seed-expansion (+ the designed level-1
        // transport pass); time the level-0 expansions at this
        // schedule's real dims.
        let l_t0 = plan0.l_t;
        let that0_len = plan0.r * ring::eval_proof::KAPPA_AGG * l_t0;
        let hh0_len = plan0.n_pairs * plan0.l_h;
        let t2 = Instant::now();
        let a0 = ring::eval_proof::expand_level_matrix(
            0xB1B_0011, g.name, 0, "A", ring::eval_proof::KAPPA_AGG, plan0.chunk, q,
        );
        let b0u = ring::eval_proof::expand_level_matrix(
            0xB1B_0011, g.name, 0, "Bu", ring::eval_proof::KAPPA_AGG, that0_len, q,
        );
        let b0h = ring::eval_proof::expand_level_matrix(
            0xB1B_0011, g.name, 0, "Bh", ring::eval_proof::KAPPA_AGG, hh0_len, q,
        );
        println!(
            "    residual: level-0 CRS expansion (A {}x{}, Bu {}x{}, Bh {}x{}) = {:.3}s \
             [seed-XOF; identical on both implementations]",
            ring::eval_proof::KAPPA_AGG,
            plan0.chunk,
            ring::eval_proof::KAPPA_AGG,
            that0_len,
            ring::eval_proof::KAPPA_AGG,
            hh0_len,
            t2.elapsed().as_secs_f64()
        );
        std::hint::black_box((a0, b0u, b0h));
    }
}

/// `bh-verifier gkr [log2_els]`: the BF-F3 measurement — one masked
/// witness descent at 2^log2 fused elements, historical padded depth
/// vs the split depth. [MAC-BOX].
fn uagb1_bh_gkr_bench(log2_els: usize) {
    use ring::gkr_masked::{
        blinded_witness_tree, draw_masks, masked_gkr_prove, masked_gkr_verify,
        masked_transcript_totals, BlinderSet,
    };
    use ring::kfield::KField;
    use ring::sumcheck::LkpTranscript;
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let n_els = 1usize << log2_els;
    let mut dw_old = 4usize;
    while (1usize << (dw_old - 1)) - 4 < n_els {
        dw_old += 1;
    }
    let mut dw_new = 4usize;
    while (1usize << dw_new) - 8 < n_els {
        dw_new += 1;
    }
    println!(
        "[UAGB1-BH] BF-F3 measurement: masked witness descent at 2^{log2_els} fused elements \
         [MAC-BOX, non-reference]\n  historical capacity 2^(d-1)-4 -> depth {dw_old}; split \
         capacity n-8 -> depth {dw_new}"
    );
    let mut rd = XofReader::new("bh-gkr-bench", &[&(log2_els as u64).to_le_bytes()]);
    let alpha = kf.uniform(&mut rd);
    let w: Vec<ring::kfield::KElem> =
        (0..n_els).map(|i| kf.embed((i as u64 * 2_654_435_761 + 13) % Q8)).collect();
    let mut results: Vec<(usize, f64, f64, f64)> = Vec::new();
    for dw in [dw_old, dw_new] {
        let mut rng = ring::ProverRng::from_test_seed("bh-gkr-bench", &(dw as u64).to_le_bytes());
        let bl = BlinderSet::draw(&kf, &mut rng);
        let masks = draw_masks(&kf, &mut rng, dw, 0);
        let t0 = Instant::now();
        let tree = blinded_witness_tree(&kf, &alpha, &w, dw, &bl);
        let t_tree = t0.elapsed().as_secs_f64();
        let mut tr = LkpTranscript::new("bh-gkr-bench", &(dw as u64).to_le_bytes());
        let t1 = Instant::now();
        let (proof, _end) = masked_gkr_prove(&kf, &[tree], masks, &mut tr);
        let t_prove = t1.elapsed().as_secs_f64();
        let mut rng2 = ring::ProverRng::from_test_seed("bh-gkr-bench", &(dw as u64).to_le_bytes());
        let _bl2 = BlinderSet::draw(&kf, &mut rng2);
        let masks2 = draw_masks(&kf, &mut rng2, dw, 0);
        let mut tv = LkpTranscript::new("bh-gkr-bench", &(dw as u64).to_le_bytes());
        let t2 = Instant::now();
        let vres = masked_gkr_verify(&kf, 1, dw, &masks2, &proof, &mut tv, true);
        let t_verify = t2.elapsed().as_secs_f64();
        assert!(vres.is_some(), "bench descent must verify");
        let (_, kel) = masked_transcript_totals(dw, 0, 1);
        println!(
            "  depth {dw}: tree {t_tree:.2}s prove {t_prove:.2}s verify {t_verify:.3}s | \
             witness-side transcript {kel} K-el = {} B",
            kel * 64
        );
        results.push((dw, t_tree, t_prove, t_verify));
    }
    let (a, b) = (&results[0], &results[1]);
    let (_, kel9) = masked_transcript_totals(9, 0, 1);
    let (_, kel_old) = masked_transcript_totals(a.0, 0, 1);
    let (_, kel_new) = masked_transcript_totals(b.0, 0, 1);
    println!(
        "\n  TREE-WORK RATIO depth {} -> {}: tree {:.2}x, prove {:.2}x, tree+prove {:.2}x\n  \
         pair transcript (with the dt = 9 table side): {} -> {} K-el ({} -> {} B, -{} B)",
        a.0,
        b.0,
        a.1 / b.1.max(1e-9),
        a.2 / b.2.max(1e-9),
        (a.1 + a.2) / (b.1 + b.2).max(1e-9),
        kel_old + kel9,
        kel_new + kel9,
        (kel_old + kel9) * 64,
        (kel_new + kel9) * 64,
        (kel_old - kel_new) * 64,
    );
}

// ===========================================================================
// [UAGB1-BI] U-AG-B1 wave 3, lane BI: THE CANONICAL WIRE FORMAT (audit
// M-05) + the p50/p95 measurement harness.
//
// Wire codec: src/wire.rs (ZKWF v1; spec docs/zkmatrix-poc/
// WIRE_FORMAT.md — the spec is the authority on every byte). This
// section owns the engine-facing side: honest-path drivers that
// produce the wave-2 artifacts as OBJECTS (reusing the BD/BE machinery
// of this module — zero changes inside their zones), object <-> wire
// conversions, the round-trip + corruption battery (`uagb1-bi
// wire-battery`), the serialized-vs-counted measurement (`uagb1-bi
// wire-bench ...`), the contract-statistic harness (`uagb1-bi
// bench-stat ...` — TARGET_CONTRACT Section 4: p95 over >= 20 warm
// runs, p50 alongside, cold-start reported separately; protocol doc
// docs/zkmatrix-poc/MEASUREMENT_PROTOCOL.md), and freeze row
// UAGB1-BI-1 (wire-format stability, both directions).
//
// Shared-zone touches (each ONE line, listed in the lane report): the
// `uagb1-bi` arm in main's dispatch match; the freeze_check_uagb1_bi()
// line in freeze_check's chain.
//
// Decode discipline (panic = abort profile): wire::decode_* never
// panics; the verify-from-wire drivers gate the decoded META against
// the EXPECTED instance before any planner/derive code (whose asserts
// are derive-time gates, not adversarial-input surfaces) can run.

#[path = "../wire.rs"]
mod wire;

// ---------------------------------------------------------------------------
// Object <-> wire conversions (kind 1).

fn bi_group_to_wire(
    name: &str,
    p: &ring::eval_proof::GroupEvalProof,
    tz: Option<&TierZFloor>,
) -> wire::WireEvalGroup {
    wire::WireEvalGroup {
        name: name.to_string(),
        u0: p.u0.clone(),
        ugh0: p.ugh0.clone(),
        b_rows: p.b_rows.clone(),
        level_us: p.level_us.clone(),
        floor_e: p.floor_e,
        floor: p.floor.clone(),
        tierz: tz.map(|t| wire::WireTierZ {
            images: t.images.clone(),
            response: t.response.clone(),
            restarts: t.restarts,
        }),
    }
}

fn bi_group_from_wire(
    g: &wire::WireEvalGroup,
) -> (ring::eval_proof::GroupEvalProof, Option<TierZFloor>) {
    (
        ring::eval_proof::GroupEvalProof {
            u0: g.u0.clone(),
            ugh0: g.ugh0.clone(),
            b_rows: g.b_rows.clone(),
            level_us: g.level_us.clone(),
            floor: g.floor.clone(),
            floor_e: g.floor_e,
            tcap_attempts: Vec::new(), // diagnostics; never wire
        },
        g.tierz.as_ref().map(|t| TierZFloor {
            images: t.images.clone(),
            response: t.response.clone(),
            restarts: t.restarts,
        }),
    )
}

/// The proven eval-proof instance (the honest path of the BD stack,
/// stopped at "serialized proof bytes exist" — everything a verifier
/// consumes, nothing prover-internal).
struct BiAggProven {
    rows: usize,
    inner: usize,
    cols: usize,
    tier_z: bool,
    force_levels: Option<usize>,
    crs_seed: u64,
    statement_bytes: Vec<u8>,
    v_claim: ring::kfield::KElem,
    scp: ring::sumcheck::SumcheckProof,
    proof_w: ring::eval_proof::GroupEvalProof,
    tz_w: Option<TierZFloor>,
    proof_a: ring::eval_proof::GroupEvalProof,
    tz_a: Option<TierZFloor>,
    commit_s: f64,
    prove_s: f64,
}

fn bi_agg_to_wire(p: &BiAggProven) -> wire::WireEvalArtifact {
    let forced = match p.force_levels {
        None => 255u8,
        Some(k) => {
            assert!(k < 255);
            k as u8
        }
    };
    wire::WireEvalArtifact {
        rows: p.rows as u32,
        inner: p.inner as u32,
        cols: p.cols as u32,
        crs_seed: p.crs_seed,
        tier_z: p.tier_z,
        forced_levels: forced,
        statement: p.statement_bytes.clone(),
        sumcheck: wire::WireSumcheck {
            v_claim: p.v_claim.clone(),
            rounds: p.scp.rounds.clone(),
            finals: p.scp.final_evals.clone(),
        },
        groups: vec![
            bi_group_to_wire("weight", &p.proof_w, p.tz_w.as_ref()),
            bi_group_to_wire("act", &p.proof_a, p.tz_a.as_ref()),
        ],
    }
}

/// The honest-path prover of the BD aggregation stack (the exact
/// uagb1_agg_run_full flow with every tamper/weak arm removed),
/// returning the wire-facing objects. Reuses agg_* machinery as-is.
fn bi_agg_prove(
    rows: usize,
    inner: usize,
    cols: usize,
    tier_z: bool,
    force_levels: Option<usize>,
    seed: u64,
) -> BiAggProven {
    use ring::eval_proof::{plan_schedule, plan_schedule_tier_z, TensorClaimKernel};
    use ring::gkr::eq_table;
    use ring::kfield::{KElem, KField};
    use ring::sumcheck::{sumcheck_prove, LkpTranscript};
    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let zq = ctxr.zq;
    let q = zq.q;
    debug_assert_eq!(q, wire::WIRE_Q, "wire v1 field id pins q8_31");

    // Witness ([-127,127] convention, BC export).
    let mut dr = seed;
    let a_i8: Vec<i64> = (0..rows * inner).map(|_| rng_below(&mut dr, 255) as i64 - 127).collect();
    let b_i8: Vec<i64> = (0..inner * cols).map(|_| rng_below(&mut dr, 255) as i64 - 127).collect();
    let mut c_acc: Vec<i64> = vec![0; rows * cols];
    for i in 0..rows {
        for k in 0..inner {
            let a = a_i8[i * inner + k];
            if a == 0 {
                continue;
            }
            let brow = &b_i8[k * cols..(k + 1) * cols];
            let crow = &mut c_acc[i * cols..(i + 1) * cols];
            for (cv, &bv) in crow.iter_mut().zip(brow.iter()) {
                *cv += a * bv;
            }
        }
    }

    // Groups, schedules, digit witnesses, level-0 pre-commits.
    let t_commit = Instant::now();
    let (mut gw, mut ga, _acc_l0) = agg_build_groups(rows, inner, cols);
    gw.begin_opening().expect("first weight-group opening");
    ga.begin_opening().expect("first act-group opening");
    let (sched_w, sched_a) = if tier_z {
        (
            plan_schedule_tier_z(gw.n_digit_rings, 1, q, force_levels),
            plan_schedule_tier_z(ga.n_digit_rings, 2, q, force_levels),
        )
    } else {
        (
            plan_schedule(gw.n_digit_rings, 1, q, force_levels),
            plan_schedule(ga.n_digit_rings, 2, q, force_levels),
        )
    };
    let w0_w = agg_digit_witness(&gw, &[&a_i8]);
    let w0_a = agg_digit_witness(&ga, &[&b_i8, &c_acc]);
    let crs_seed = 0xB1_A6u64 ^ seed.rotate_left(17);
    let pre_w = agg_precommit(&ctxr, &gw, &sched_w, &w0_w, crs_seed);
    let pre_a = agg_precommit(&ctxr, &ga, &sched_a, &w0_a, crs_seed);

    // Statement + h0_agg.
    let u0_digests: Vec<Vec<u8>> = [&pre_w, &pre_a]
        .iter()
        .map(|p| uk8_sha(&[b"agg-u0", &polys_bytes(&p.u0)]).to_vec())
        .collect();
    let acc_bits = mm_acc_bits(inner);
    let descs = vec![agg_group_descriptor(&gw, false), agg_group_descriptor(&ga, false)];
    let statement = agg_build_statement(rows, inner, cols, acc_bits, &descs, &u0_digests, b"agg-crs-v1");
    let ctx_digest = statement.digest().expect("prover statement validates");
    let statement_bytes = statement.encode();
    let h0_agg =
        uk8_sha(&[b"uagb1-agg-h0", &ctx_digest, &polys_bytes(&pre_w.u0), &polys_bytes(&pre_a.u0)]);
    let commit_s = t_commit.elapsed().as_secs_f64();

    // Prover transcript: rx/ry, sumcheck, nu, groups.
    let t_prove = Instant::now();
    let lr = rows.trailing_zeros() as usize;
    let lc = cols.trailing_zeros() as usize;
    let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
    let mut tr = LkpTranscript::new("uagb1-agg", &h0_agg);
    let rx: Vec<KElem> = (0..lr).map(|_| tr.challenge_k(&kf)).collect();
    let ry: Vec<KElem> = (0..lc).map(|_| tr.challenge_k(&kf)).collect();
    let eq_rx = eq_table(&kf, &rx);
    let eq_ry = eq_table(&kf, &ry);
    let nk = 1usize << lk;
    let mut tta = vec![kf.zero(); nk];
    for i in 0..rows {
        let w = &eq_rx[i];
        if kf.is_zero(w) {
            continue;
        }
        for k in 0..inner {
            let v = a_i8[i * inner + k];
            if v != 0 {
                tta[k] = kf.add(&tta[k], &kf.scale(zq.to_mod(v), w));
            }
        }
    }
    let mut ttb = vec![kf.zero(); nk];
    for k in 0..inner {
        let rowb = &b_i8[k * cols..(k + 1) * cols];
        let mut acc = kf.zero();
        for (j, &v) in rowb.iter().enumerate() {
            if v != 0 {
                acc = kf.add(&acc, &kf.scale(zq.to_mod(v), &eq_ry[j]));
            }
        }
        ttb[k] = acc;
    }
    let v_claim = {
        let mut acc = kf.zero();
        for i in 0..rows {
            let rowc = &c_acc[i * cols..(i + 1) * cols];
            let mut ri = kf.zero();
            for (j, &v) in rowc.iter().enumerate() {
                if v != 0 {
                    ri = kf.add(&ri, &kf.scale(zq.to_mod(v), &eq_ry[j]));
                }
            }
            acc = kf.add(&acc, &kf.mul(&ri, &eq_rx[i]));
        }
        acc
    };
    tr.absorb_k(&kf, "agg-claim", std::slice::from_ref(&v_claim));
    let product = |kf: &KField, vals: &[KElem]| kf.mul(&vals[0], &vals[1]);
    let (scp, kstar) = sumcheck_prove(&kf, vec![tta, ttb], 2, &product, &mut tr);
    tr.absorb_k(&kf, "agg-final", &scp.final_evals);
    let eq_k = eq_table(&kf, &kstar);
    let nu_w = tr.challenge_k(&kf);
    let nu_b = tr.challenge_k(&kf);
    let nu_c = tr.challenge_k(&kf);
    let v_batch_w = kf.mul(&nu_w, &scp.final_evals[0]);
    let v_batch_a = kf.add(&kf.mul(&nu_b, &scp.final_evals[1]), &kf.mul(&nu_c, &v_claim));
    let kernels_w = vec![TensorClaimKernel {
        tensor_idx: 0,
        row_kernel: eq_rx.iter().map(|e| kf.mul(&nu_w, e)).collect(),
        col_kernel: eq_k[..inner].to_vec(),
    }];
    let kernels_a = vec![
        TensorClaimKernel {
            tensor_idx: 0,
            row_kernel: eq_k[..inner].iter().map(|e| kf.mul(&nu_b, e)).collect(),
            col_kernel: eq_ry.clone(),
        },
        TensorClaimKernel {
            tensor_idx: 1,
            row_kernel: eq_rx.iter().map(|e| kf.mul(&nu_c, e)).collect(),
            col_kernel: eq_ry.clone(),
        },
    ];
    let mut mask_rng = ring::ProverRng::from_test_seed("uagb1-agg-tz", &seed.to_le_bytes());
    let (proof_w, tz_w) = agg_prove_group(
        &ctxr, &kf, &gw, &sched_w, &w0_w, &kernels_w, &v_batch_w, pre_w, &mut tr, crs_seed, false,
        false, false, tier_z, &mut mask_rng,
    );
    let (proof_a, tz_a) = agg_prove_group(
        &ctxr, &kf, &ga, &sched_a, &w0_a, &kernels_a, &v_batch_a, pre_a, &mut tr, crs_seed, false,
        false, false, tier_z, &mut mask_rng,
    );
    let prove_s = t_prove.elapsed().as_secs_f64();
    BiAggProven {
        rows,
        inner,
        cols,
        tier_z,
        force_levels,
        crs_seed,
        statement_bytes,
        v_claim,
        scp,
        proof_w,
        tz_w,
        proof_a,
        tz_a,
        commit_s,
        prove_s,
    }
}

/// Verify a DECODED kind-1 wire artifact against the expected instance
/// (shape/mode gate first — decoded META never reaches derive-time
/// asserts unvetted). Mirrors the shipped verifier exactly.
fn bi_agg_verify_wire(
    art: &wire::WireEvalArtifact,
    rows: usize,
    inner: usize,
    cols: usize,
    tier_z: bool,
    force_levels: Option<usize>,
) -> Result<(), &'static str> {
    use ring::eval_proof::{plan_schedule, plan_schedule_tier_z, TensorClaimKernel};
    use ring::gkr::eq_table;
    use ring::kfield::{KElem, KField};
    use ring::sumcheck::{sumcheck_verify, LkpTranscript};
    let forced_wire = match force_levels {
        None => 255u8,
        Some(k) => k as u8,
    };
    if art.rows != rows as u32
        || art.inner != inner as u32
        || art.cols != cols as u32
        || art.tier_z != tier_z
        || art.forced_levels != forced_wire
    {
        return Err("meta-mismatch");
    }
    if art.sumcheck.v_claim.len() != ring::kfield::K_DEG {
        return Err("wire-shape");
    }
    // The embedded statement must decode, re-encode byte-identically
    // (canonical embedding), validate, and digest.
    let statement = manifest::Statement::decode(&art.statement).map_err(|_| "statement-decode")?;
    if statement.encode() != art.statement {
        return Err("statement-noncanonical");
    }
    statement.validate().map_err(|_| "statement-invalid")?;
    let ctx_digest = statement.digest().map_err(|_| "statement-digest-err")?;

    let ctxr = ring_ctx_q8();
    let kf = KField::new(&ctxr);
    let zq = ctxr.zq;
    let q = zq.q;
    let (mut gw_v, mut ga_v, _) = agg_build_groups(rows, inner, cols);
    gw_v.begin_opening().map_err(|_| "opening-count")?;
    ga_v.begin_opening().map_err(|_| "opening-count")?;
    let (sched_w, sched_a) = if tier_z {
        (
            plan_schedule_tier_z(gw_v.n_digit_rings, 1, q, force_levels),
            plan_schedule_tier_z(ga_v.n_digit_rings, 2, q, force_levels),
        )
    } else {
        (
            plan_schedule(gw_v.n_digit_rings, 1, q, force_levels),
            plan_schedule(ga_v.n_digit_rings, 2, q, force_levels),
        )
    };
    let (proof_w, tz_w) = bi_group_from_wire(&art.groups[0]);
    let (proof_a, tz_a) = bi_group_from_wire(&art.groups[1]);
    // Rebuild the statement from the proof's u0 identities and require
    // digest equality with the embedded statement (the D-4 gate).
    let descs_v = vec![agg_group_descriptor(&gw_v, false), agg_group_descriptor(&ga_v, false)];
    let u0_digests_v: Vec<Vec<u8>> = [&proof_w, &proof_a]
        .iter()
        .map(|p| uk8_sha(&[b"agg-u0", &polys_bytes(&p.u0)]).to_vec())
        .collect();
    let acc_bits = mm_acc_bits(inner);
    let statement_v =
        agg_build_statement(rows, inner, cols, acc_bits, &descs_v, &u0_digests_v, b"agg-crs-v1");
    let ctx_v = match statement_v.validate() {
        Ok(()) => statement_v.digest().map_err(|_| "statement-digest-err")?,
        Err(_) => return Err("statement-invalid"),
    };
    if ctx_v != ctx_digest {
        return Err("statement-digest");
    }
    let h0_v =
        uk8_sha(&[b"uagb1-agg-h0", &ctx_v, &polys_bytes(&proof_w.u0), &polys_bytes(&proof_a.u0)]);
    let mut tv = LkpTranscript::new("uagb1-agg", &h0_v);
    let lr = rows.trailing_zeros() as usize;
    let lc = cols.trailing_zeros() as usize;
    let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
    let rx_v: Vec<KElem> = (0..lr).map(|_| tv.challenge_k(&kf)).collect();
    let ry_v: Vec<KElem> = (0..lc).map(|_| tv.challenge_k(&kf)).collect();
    let v_claim = art.sumcheck.v_claim.clone();
    tv.absorb_k(&kf, "agg-claim", std::slice::from_ref(&v_claim));
    let scp = ring::sumcheck::SumcheckProof {
        rounds: art.sumcheck.rounds.clone(),
        final_evals: art.sumcheck.finals.clone(),
    };
    if scp.final_evals.len() != 2 {
        return Err("wire-shape");
    }
    let product = |kf: &KField, vals: &[KElem]| kf.mul(&vals[0], &vals[1]);
    let sc_v = sumcheck_verify(&kf, lk, 2, &v_claim, &scp, &product, &mut tv);
    let (kstar_v, _) = match sc_v {
        Some(x) => x,
        None => return Err("sumcheck"),
    };
    tv.absorb_k(&kf, "agg-final", &scp.final_evals);
    let eq_rx_v = eq_table(&kf, &rx_v);
    let eq_ry_v = eq_table(&kf, &ry_v);
    let eq_k_v = eq_table(&kf, &kstar_v);
    let nu_w_v = tv.challenge_k(&kf);
    let nu_b_v = tv.challenge_k(&kf);
    let nu_c_v = tv.challenge_k(&kf);
    let vb_w = kf.mul(&nu_w_v, &scp.final_evals[0]);
    let vb_a = kf.add(&kf.mul(&nu_b_v, &scp.final_evals[1]), &kf.mul(&nu_c_v, &v_claim));
    let kernels_w_v = vec![TensorClaimKernel {
        tensor_idx: 0,
        row_kernel: eq_rx_v.iter().map(|e| kf.mul(&nu_w_v, e)).collect(),
        col_kernel: eq_k_v[..inner].to_vec(),
    }];
    let kernels_a_v = vec![
        TensorClaimKernel {
            tensor_idx: 0,
            row_kernel: eq_k_v[..inner].iter().map(|e| kf.mul(&nu_b_v, e)).collect(),
            col_kernel: eq_ry_v.clone(),
        },
        TensorClaimKernel {
            tensor_idx: 1,
            row_kernel: eq_rx_v.iter().map(|e| kf.mul(&nu_c_v, e)).collect(),
            col_kernel: eq_ry_v.clone(),
        },
    ];
    agg_verify_group(
        &ctxr, &kf, &gw_v, &sched_w, &kernels_w_v, &vb_w, &proof_w, &mut tv, art.crs_seed, false,
        false, tz_w.as_ref(),
    )?;
    agg_verify_group(
        &ctxr, &kf, &ga_v, &sched_a, &kernels_a_v, &vb_a, &proof_a, &mut tv, art.crs_seed, false,
        false, tz_a.as_ref(),
    )?;
    Ok(())
}

// ---------------------------------------------------------------------------
// Kind-2 drivers: the honest joint-matmul IXF fold (the BE rig's
// shipped path), stopped at the transcript objects.

fn bi_ct_to_wire(p: &ring::ct_engine::CtRoundProof) -> wire::WireCtRound {
    // v1 scopes the record to the plain-commitment linear-claim form
    // (what the BE rigs emit) — every other field must be empty.
    assert!(
        p.w1_ajtai.is_empty()
            && p.w_ring.is_empty()
            && p.h_quad.is_empty()
            && p.gq.is_empty()
            && p.w_quad.is_empty()
            && p.gr.is_empty()
            && p.w_qring.is_empty()
            && p.gtq.is_empty()
            && p.w_tq.is_empty()
            && p.z_rho_ajtai.is_empty()
            && p.z_s_ajtai.is_empty()
            && p.t1_digits.is_empty()
            && p.w1_digits.is_empty()
            && p.z_digits.is_empty(),
        "wire v1 ct-round record covers the plain linear form only"
    );
    wire::WireCtRound {
        h: p.h.clone(),
        w1: p.w1.clone(),
        w_claim: p.w_claim.clone(),
        z: p.z.clone(),
    }
}

fn bi_ct_from_wire(c: &wire::WireCtRound) -> ring::ct_engine::CtRoundProof {
    ring::ct_engine::CtRoundProof {
        h: c.h.clone(),
        w1: c.w1.clone(),
        w1_ajtai: Vec::new(),
        w_claim: c.w_claim.clone(),
        w_ring: Vec::new(),
        h_quad: Vec::new(),
        gq: Vec::new(),
        w_quad: Vec::new(),
        gr: Vec::new(),
        w_qring: Vec::new(),
        gtq: Vec::new(),
        w_tq: Vec::new(),
        z: c.z.clone(),
        z_rho_ajtai: Vec::new(),
        z_s_ajtai: Vec::new(),
        t1_digits: Vec::new(),
        w1_digits: Vec::new(),
        z_digits: Vec::new(),
    }
}

struct BiFoldProven {
    layers: usize,
    rows: usize,
    inner: usize,
    cols: usize,
    statement_bytes: Vec<u8>,
    t1s: Vec<Vec<Poly>>,
    t2s: Vec<Vec<Poly>>,
    v_claim: ring::kfield::KElem,
    scp: ring::sumcheck::SumcheckProof,
    reveals: Vec<Vec<(usize, i64)>>,
    waves: Vec<ring::ct_engine::CtRoundProof>,
    closing: Option<ring::ct_engine::CtRoundProof>,
    commit_s: f64,
    prove_s: f64,
}

const BI_FOLD_CRS_SEED: u64 = 0x0BE2; // the BE rig's public CRS seed

fn bi_fold_to_wire(p: &BiFoldProven) -> wire::WireFoldTranscript {
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    wire::WireFoldTranscript {
        family: 1, // joint matmul
        layers: p.layers as u32,
        rows: p.rows as u32,
        inner: p.inner as u32,
        cols: p.cols as u32,
        kappa: shape.kappa as u8,
        msg_r: shape.msg_r as u8,
        n_r: shape.n_r as u8,
        crs_seed: BI_FOLD_CRS_SEED,
        statement: p.statement_bytes.clone(),
        t1s: p.t1s.clone(),
        t2s: p.t2s.clone(),
        sumcheck: wire::WireSumcheck {
            v_claim: p.v_claim.clone(),
            rounds: p.scp.rounds.clone(),
            finals: p.scp.final_evals.clone(),
        },
        reveals: p
            .reveals
            .iter()
            .map(|rv| rv.iter().map(|&(w, v)| (w as u32, v)).collect())
            .collect(),
        waves: p.waves.iter().map(bi_ct_to_wire).collect(),
        closing: p.closing.as_ref().map(bi_ct_to_wire),
    }
}

/// The three stacked pins of the joint matmul fold (the BE rig's local
/// closure, replicated verbatim for the wire verifier — position-
/// determined public weights over committed indices).
#[allow(clippy::too_many_arguments)]
fn bi_mm_pins(
    kf: &ring::kfield::KField,
    layers: usize,
    rows: usize,
    inner: usize,
    cols: usize,
    per: usize,
    cms_layer: usize,
    abc_cms: (usize, usize, usize),
    v: &ring::kfield::KElem,
    a_star: &ring::kfield::KElem,
    b_star: &ring::kfield::KElem,
    eq_rl_w: &[ring::kfield::KElem],
    eq_rx_w: &[ring::kfield::KElem],
    eq_ry_w: &[ring::kfield::KElem],
    eq_k_w: &[ring::kfield::KElem],
    eq_lstar_w: &[ring::kfield::KElem],
) -> Vec<ring::lookup::PinnedValue> {
    use ring::kfield::KElem;
    use ring::lookup::{PinTerm, PinnedValue};
    let (a_cms, b_cms, c_cms) = abc_cms;
    let scalar_terms = |tensor: usize,
                        n_cms: usize,
                        wf: &dyn Fn(usize, usize) -> Option<KElem>|
     -> Vec<PinTerm> {
        let mut terms = Vec::new();
        for l in 0..layers {
            let base = l * cms_layer
                + match tensor {
                    0 => 0,
                    1 => a_cms,
                    _ => a_cms + b_cms,
                };
            for g in 0..n_cms {
                let lo = g * per;
                let mut weights: Vec<KElem> = Vec::with_capacity(per);
                let mut any = false;
                for c in 0..per {
                    match wf(l, lo + c) {
                        Some(w) => {
                            if !kf.is_zero(&w) {
                                any = true;
                            }
                            weights.push(w);
                        }
                        None => weights.push(kf.zero()),
                    }
                }
                if any {
                    terms.push(PinTerm::Scalar { commit: base + g, coeff0: 0, weights });
                }
            }
        }
        terms
    };
    let pin_c = PinnedValue {
        terms: scalar_terms(2, c_cms, &|l, f| {
            if f < rows * cols {
                Some(kf.mul(&eq_rl_w[l], &kf.mul(&eq_rx_w[f / cols], &eq_ry_w[f % cols])))
            } else {
                None
            }
        }),
        value: v.clone(),
    };
    let pin_a = PinnedValue {
        terms: scalar_terms(0, a_cms, &|l, f| {
            if f < rows * inner {
                Some(kf.mul(&eq_lstar_w[l], &kf.mul(&eq_rx_w[f / inner], &eq_k_w[f % inner])))
            } else {
                None
            }
        }),
        value: a_star.clone(),
    };
    let pin_b = PinnedValue {
        terms: scalar_terms(1, b_cms, &|l, f| {
            if f < inner * cols {
                Some(kf.mul(&eq_lstar_w[l], &kf.mul(&eq_k_w[f / cols], &eq_ry_w[f % cols])))
            } else {
                None
            }
        }),
        value: b_star.clone(),
    };
    vec![pin_c, pin_a, pin_b]
}

/// The honest joint-matmul IXF fold prover (the uagb1_ixf_matmul_run
/// shipped path, tamper/weak arms removed), returning the transcript.
fn bi_fold_prove(layers: usize, rows: usize, inner: usize, cols: usize, seed: u64) -> BiFoldProven {
    use ring::ct_engine::{
        ct_h0, derive_ct_round_params, draw_wave_pads, pack_wave_pads, prove_ct_round,
        sample_ct_masks, split_claims_prover_masked, CtClaim, StdOpening, WavePads,
    };
    use ring::fold::{ixf_layout, ixf_sumcheck_prove, matmul_degree_schedule};
    use ring::gkr::eq_table;
    use ring::kfield::{KElem, KField};
    use ring::lookup::{derive_pin_psi, pin_claims};
    use ring::sumcheck::LkpTranscript;

    let ctx_ring = ring_ctx_q8();
    let kf = KField::new(&ctx_ring);
    let zq = ctx_ring.zq;
    let q = zq.q;
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    let msg_r = shape.msg_r;
    let per = msg_r * D;
    let crs = expand_crs(shape, q, BI_FOLD_CRS_SEED);
    let il = ixf_layout(layers);
    assert!(rows.is_power_of_two() && cols.is_power_of_two());
    assert!((rows * inner) % per == 0 && (inner * cols) % per == 0 && (rows * cols) % per == 0);
    let lr = rows.trailing_zeros() as usize;
    let lc = cols.trailing_zeros() as usize;
    let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
    let nk = 1usize << lk;
    let a_cms = (rows * inner) / per;
    let b_cms = (inner * cols) / per;
    let c_cms = (rows * cols) / per;
    let cms_layer = a_cms + b_cms + c_cms;
    let cl = ixf_commit_layout(layers * cms_layer, shape, q);
    let n_waves = cl.plan.waves.len();

    // Witness: per layer A, B int8 [-127,127]; C = A*B exact.
    let mut dr = seed;
    let mut avs: Vec<Vec<i64>> = Vec::with_capacity(layers);
    let mut bvs: Vec<Vec<i64>> = Vec::with_capacity(layers);
    let mut cvs: Vec<Vec<i64>> = Vec::with_capacity(layers);
    for _ in 0..layers {
        let a: Vec<i64> = (0..rows * inner).map(|_| rng_below(&mut dr, 255) as i64 - 127).collect();
        let b: Vec<i64> = (0..inner * cols).map(|_| rng_below(&mut dr, 255) as i64 - 127).collect();
        let mut c: Vec<i64> = vec![0; rows * cols];
        for i in 0..rows {
            for k in 0..inner {
                let av = a[i * inner + k];
                if av == 0 {
                    continue;
                }
                let brow = &b[k * cols..(k + 1) * cols];
                let crow = &mut c[i * cols..(i + 1) * cols];
                for (cv, &bv) in crow.iter_mut().zip(brow.iter()) {
                    *cv += av * bv;
                }
            }
        }
        avs.push(a);
        bvs.push(b);
        cvs.push(c);
    }

    // Commitments (everything before any challenge).
    let t_commit = Instant::now();
    let mut rng = ring::ProverRng::from_test_seed("uagb1-ixf-mm-session", &seed.to_le_bytes());
    let mut pads_live: Option<WavePads> = if cl.pad_layout.has_pads() {
        Some(draw_wave_pads(&mut rng, q, &cl.pad_layout))
    } else {
        None
    };
    let pack_dense = |vals: &[i64], g: usize| -> Vec<Poly> {
        let mut polys = vec![poly_zero(); msg_r];
        for s in 0..msg_r {
            for c in 0..D {
                let idx = g * per + s * D + c;
                if idx < vals.len() {
                    polys[s][c] = zq.to_mod(vals[idx]);
                }
            }
        }
        polys
    };
    let mut msgs: Vec<Vec<Poly>> = Vec::with_capacity(cl.n_commits);
    for l in 0..layers {
        for g in 0..a_cms {
            msgs.push(pack_dense(&avs[l], g));
        }
        for g in 0..b_cms {
            msgs.push(pack_dense(&bvs[l], g));
        }
        for g in 0..c_cms {
            msgs.push(pack_dense(&cvs[l], g));
        }
    }
    if cl.pad_layout.has_pads() {
        let pad_msgs = pack_wave_pads(&mut rng, q, msg_r, &cl.pad_layout, pads_live.as_ref().unwrap())
            .expect("pad packing");
        msgs.extend(pad_msgs);
    }
    let closing_g =
        sample_ct_masks(&mut rng, q, msg_r, if cl.closing_g_groups > 0 { UR1_PIN_COPIES } else { 0 });
    msgs.extend(closing_g);
    for _ in 0..n_waves {
        msgs.extend(sample_ct_masks(&mut rng, q, msg_r, UR1_PIN_COPIES));
    }
    assert_eq!(msgs.len(), cl.n_commits);
    let rp_probe = derive_ct_round_params(q, shape, cl.data_cap + 1 + cl.wave_g_groups, 0, 0, true);
    let a1p = build_a1_paths(&crs, rp_probe.sigma, isqrt_u128(rp_probe.bound_sq));
    let path = KernelPath::A1(&a1p);
    let mut rhos8: Vec<Vec<i8>> = Vec::with_capacity(cl.n_commits);
    let mut t1s: Vec<Vec<Poly>> = Vec::with_capacity(cl.n_commits);
    let mut t2s: Vec<Vec<Poly>> = Vec::with_capacity(cl.n_commits);
    for m in &msgs {
        let rho: Vec<Vec<i64>> = (0..shape.n_r).map(|_| rng_ternary_poly(&mut rng)).collect();
        let (t1, t2) = commit(&path, &crs, m, &rho);
        rhos8.push(rho.iter().flat_map(|p| p.iter().map(|&x| x as i8)).collect());
        t1s.push(t1);
        t2s.push(t2);
    }
    let commit_s = t_commit.elapsed().as_secs_f64();

    // Statement + h0 (per-layer segment rows).
    let t_prove = Instant::now();
    let commit_digests: Vec<Vec<u8>> =
        (0..cl.n_commits).map(|i| group_digest(&t1s[i], &t2s[i])).collect();
    let layer_rows: Vec<Vec<u8>> = (0..layers)
        .map(|l| group_list_digest(&commit_digests[l * cms_layer..(l + 1) * cms_layer]))
        .collect();
    let statement = ixf_mm_build_statement(
        layers,
        rows,
        inner,
        cols,
        &crs.crs_hash,
        &commit_digests[..cl.n_data],
        (a_cms, b_cms, c_cms),
        &layer_rows,
        true,
    );
    let ctx = statement.digest().expect("prover statement validates");
    let statement_bytes = statement.encode();
    let h0 = ct_h0(&crs, &ctx, &t1s, &t2s, &[]);

    // Prover transcript: rx, ry, r_l; claim; the joint sumcheck.
    let mut tr = LkpTranscript::new("uagb1-ixf-mm", &h0);
    let rx: Vec<KElem> = (0..lr).map(|_| tr.challenge_k(&kf)).collect();
    let ry: Vec<KElem> = (0..lc).map(|_| tr.challenge_k(&kf)).collect();
    let rl: Vec<KElem> = (0..il.lambda).map(|_| tr.challenge_k(&kf)).collect();
    let eq_rx = eq_table(&kf, &rx);
    let eq_ry = eq_table(&kf, &ry);
    let eq_rl = eq_table(&kf, &rl);
    let mut tta = vec![kf.zero(); il.slots * nk];
    let mut ttb = vec![kf.zero(); il.slots * nk];
    for l in 0..layers {
        for i in 0..rows {
            let w = &eq_rx[i];
            if kf.is_zero(w) {
                continue;
            }
            for k in 0..inner {
                let v = avs[l][i * inner + k];
                if v != 0 {
                    let t = &mut tta[l * nk + k];
                    *t = kf.add(t, &kf.scale(zq.to_mod(v), w));
                }
            }
        }
        for k in 0..inner {
            let row = &bvs[l][k * cols..(k + 1) * cols];
            let mut acc = kf.zero();
            for (j, &v) in row.iter().enumerate() {
                if v != 0 {
                    acc = kf.add(&acc, &kf.scale(zq.to_mod(v), &eq_ry[j]));
                }
            }
            ttb[l * nk + k] = acc;
        }
    }
    // The committed-C functional value at (r_l, rx, ry) — the claim.
    let v_claim = {
        let mut acc = kf.zero();
        for l in 0..layers {
            if kf.is_zero(&eq_rl[l]) {
                continue;
            }
            let mut lacc = kf.zero();
            for i in 0..rows {
                let row = &cvs[l][i * cols..(i + 1) * cols];
                let mut ri = kf.zero();
                for (j, &v) in row.iter().enumerate() {
                    if v != 0 {
                        ri = kf.add(&ri, &kf.scale(zq.to_mod(v), &eq_ry[j]));
                    }
                }
                lacc = kf.add(&lacc, &kf.mul(&ri, &eq_rx[i]));
            }
            acc = kf.add(&acc, &kf.mul(&lacc, &eq_rl[l]));
        }
        acc
    };
    tr.absorb_k(&kf, "mm-claim", std::slice::from_ref(&v_claim));
    let eq_l_expanded = ring::fold::expand_layer_table(&kf, &eq_rl, nk);
    let degrees = matmul_degree_schedule(lk, il.lambda);
    let comb = |kf: &KField, v: &[KElem]| kf.mul(&v[0], &kf.mul(&v[1], &v[2]));
    let (scp, pt) = ixf_sumcheck_prove(&kf, vec![eq_l_expanded, tta, ttb], &degrees, &comb, &mut tr);
    tr.absorb_k(&kf, "mm-final", &scp.final_evals);

    // The three stacked pins (E4-N1: values before psi).
    let eq_k = eq_table(&kf, &pt[0..lk]);
    let eq_lstar = eq_table(&kf, &pt[lk..]);
    let pins = bi_mm_pins(
        &kf,
        layers,
        rows,
        inner,
        cols,
        per,
        cms_layer,
        (a_cms, b_cms, c_cms),
        &v_claim,
        &scp.final_evals[1],
        &scp.final_evals[2],
        &eq_rl,
        &eq_rx,
        &eq_ry,
        &eq_k,
        &eq_lstar,
    );
    for p in &pins {
        tr.absorb_k(&kf, "mm-pin", std::slice::from_ref(&p.value));
    }
    let psi = derive_pin_psi(&tr.state(), UR1_PIN_COPIES, pins.len() * ring::kfield::K_DEG, q);
    let claims_p = pin_claims(&kf, &pins, cl.n_data, msg_r, &psi);
    drop(pins);

    // Masked split + per-wave ct-rounds (the Z1 shipped path).
    let msg_refs: Vec<&[Poly]> = msgs[..cl.n_data].iter().map(|m| m.as_slice()).collect();
    let (mut pw_claims, reveals) = split_claims_prover_masked(
        &zq,
        &cl.plan,
        &claims_p,
        &msg_refs,
        &cl.pad_layout,
        pads_live.take().unwrap_or_else(|| draw_wave_pads(&mut rng, q, &cl.pad_layout)),
    )
    .expect("honest masked split");
    drop(claims_p);
    if pw_claims.is_empty() {
        pw_claims = (0..n_waves).map(|_| Vec::new()).collect();
    }
    let unpack_rho = |packed: &[i8]| -> Vec<Vec<i64>> {
        (0..shape.n_r)
            .map(|rr| packed[rr * D..(rr + 1) * D].iter().map(|&b| b as i64).collect())
            .collect()
    };
    let wave_idxs = |w: usize| -> Vec<usize> {
        let mut v = cl.plan.waves[w].clone();
        if cl.pad_layout.has_pads() {
            v.push(cl.base_pad + w / cl.pad_layout.waves_per_cm);
        }
        let g0 = cl.base_wave_g + w * cl.wave_g_groups;
        v.extend(g0..g0 + cl.wave_g_groups);
        v
    };
    let mut wave_proofs: Vec<ring::ct_engine::CtRoundProof> = Vec::with_capacity(n_waves);
    let mut rp_cache: std::collections::BTreeMap<
        usize,
        (ring::ct_engine::CtRoundParams, ring::commit::A1Paths),
    > = std::collections::BTreeMap::new();
    let tr_state = tr.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        if !rp_cache.contains_key(&n_cw) {
            let rp = derive_ct_round_params(q, shape, n_cw, 0, 0, true);
            let a1pw = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cw, (rp, a1pw));
        }
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).unwrap();
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut pw_claims[w]);
        let wrhos: Vec<Vec<Vec<i64>>> = idxs.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings: Vec<StdOpening> = idxs
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &wrhos[j] })
            .collect();
        let mut state_p: Vec<u8> = tr_state.to_vec();
        state_p.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| t2s[i].clone()).collect();
        let h0_w = ct_h0(&crs, &state_p, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(cl.pad_layout.has_pads());
        let (proof_w, _) = prove_ct_round(
            &path_w,
            &ctx_ring,
            rp_w,
            None,
            &crs,
            &h0_w,
            &claims_w,
            &[],
            &[],
            &[],
            &openings,
            &[],
            &[],
            cl.plan.waves[w].len() + pad_shift,
            &mut rng,
        );
        wave_proofs.push(proof_w);
    }
    let closing_proof = if cl.pad_layout.has_pads() {
        let idxs_z: Vec<usize> = (cl.base_pad..cl.base_pad + cl.pad_layout.n_pad_cms)
            .chain(cl.base_closing_g..cl.base_closing_g + cl.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        if !rp_cache.contains_key(&n_cz) {
            let rp = derive_ct_round_params(q, shape, n_cz, 0, 0, true);
            let a1pz = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cz, (rp, a1pz));
        }
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).unwrap();
        let path_z = KernelPath::A1(a1p_z);
        let claims_z = ring::ct_engine::closing_round_claims(&zq, &cl.pad_layout);
        let mut state_z: Vec<u8> = tr_state.to_vec();
        state_z.extend(b"ixf-mm-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| t2s[i].clone()).collect();
        let h0_z = ct_h0(&crs, &state_z, &zt1s, &zt2s, &[]);
        let zrhos: Vec<Vec<Vec<i64>>> = idxs_z.iter().map(|&i| unpack_rho(&rhos8[i])).collect();
        let openings_z: Vec<StdOpening> = idxs_z
            .iter()
            .enumerate()
            .map(|(j, &i)| StdOpening { t1: &t1s[i], t2: &t2s[i], x: &msgs[i], rho: &zrhos[j] })
            .collect();
        let (proof_z, _) = prove_ct_round(
            &path_z,
            &ctx_ring,
            rp_z,
            None,
            &crs,
            &h0_z,
            &claims_z,
            &[],
            &[],
            &[],
            &openings_z,
            &[],
            &[],
            cl.pad_layout.n_pad_cms,
            &mut rng,
        );
        Some(proof_z)
    } else {
        None
    };
    let prove_s = t_prove.elapsed().as_secs_f64() + commit_s;
    BiFoldProven {
        layers,
        rows,
        inner,
        cols,
        statement_bytes,
        t1s,
        t2s,
        v_claim,
        scp,
        reveals,
        waves: wave_proofs,
        closing: closing_proof,
        commit_s,
        prove_s,
    }
}

/// Verify a DECODED kind-2 wire transcript against the expected
/// instance (META gate first). Mirrors the BE rig's shipped verifier.
fn bi_fold_verify_wire(
    art: &wire::WireFoldTranscript,
    layers: usize,
    rows: usize,
    inner: usize,
    cols: usize,
) -> Result<(), &'static str> {
    use ring::ct_engine::{ct_h0, derive_ct_round_params, split_claims_verifier_masked, verify_ct_round, CtClaim};
    use ring::fold::{ixf_layout, ixf_sumcheck_verify, matmul_degree_schedule};
    use ring::gkr::{eq_eval, eq_table};
    use ring::kfield::{KElem, KField};
    use ring::lookup::{derive_pin_psi, pin_claims};
    use ring::sumcheck::LkpTranscript;
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    if art.family != 1
        || art.layers != layers as u32
        || art.rows != rows as u32
        || art.inner != inner as u32
        || art.cols != cols as u32
        || art.kappa != shape.kappa as u8
        || art.msg_r != shape.msg_r as u8
        || art.n_r != shape.n_r as u8
        || art.crs_seed != BI_FOLD_CRS_SEED
    {
        return Err("meta-mismatch");
    }
    let ctx_ring = ring_ctx_q8();
    let kf = KField::new(&ctx_ring);
    let zq = ctx_ring.zq;
    let q = zq.q;
    let msg_r = shape.msg_r;
    let per = msg_r * D;
    let crs = expand_crs(shape, q, art.crs_seed);
    let il = ixf_layout(layers);
    let lr = rows.trailing_zeros() as usize;
    let lc = cols.trailing_zeros() as usize;
    let lk = usize::BITS as usize - (inner - 1).leading_zeros() as usize;
    let a_cms = (rows * inner) / per;
    let b_cms = (inner * cols) / per;
    let c_cms = (rows * cols) / per;
    let cms_layer = a_cms + b_cms + c_cms;
    let cl = ixf_commit_layout(layers * cms_layer, shape, q);
    let n_waves = cl.plan.waves.len();
    if art.t1s.len() != cl.n_commits || art.waves.len() != n_waves {
        return Err("wire-shape");
    }
    // The embedded statement: decode, canonical re-encode, validate.
    let statement = manifest::Statement::decode(&art.statement).map_err(|_| "statement-decode")?;
    if statement.encode() != art.statement {
        return Err("statement-noncanonical");
    }
    statement.validate().map_err(|_| "statement-invalid")?;
    let ctx_claimed = statement.digest().map_err(|_| "statement-digest-err")?;
    // Rebuild the statement from the wire tags (the D-4 identity gate).
    let commit_digests_v: Vec<Vec<u8>> =
        (0..cl.n_commits).map(|i| group_digest(&art.t1s[i], &art.t2s[i])).collect();
    let layer_rows_v: Vec<Vec<u8>> = (0..layers)
        .map(|l| group_list_digest(&commit_digests_v[l * cms_layer..(l + 1) * cms_layer]))
        .collect();
    let statement_v = ixf_mm_build_statement(
        layers,
        rows,
        inner,
        cols,
        &crs.crs_hash,
        &commit_digests_v[..cl.n_data],
        (a_cms, b_cms, c_cms),
        &layer_rows_v,
        true,
    );
    let ctx_v = statement_v.digest().map_err(|_| "statement-invalid")?;
    if ctx_v != ctx_claimed {
        return Err("statement-digest");
    }
    let h0_v = ct_h0(&crs, &ctx_v, &art.t1s, &art.t2s, &[]);
    let mut tv = LkpTranscript::new("uagb1-ixf-mm", &h0_v);
    let rx_v: Vec<KElem> = (0..lr).map(|_| tv.challenge_k(&kf)).collect();
    let ry_v: Vec<KElem> = (0..lc).map(|_| tv.challenge_k(&kf)).collect();
    let rl_v: Vec<KElem> = (0..il.lambda).map(|_| tv.challenge_k(&kf)).collect();
    let v_claim = art.sumcheck.v_claim.clone();
    tv.absorb_k(&kf, "mm-claim", std::slice::from_ref(&v_claim));
    let scp = ring::sumcheck::SumcheckProof {
        rounds: art.sumcheck.rounds.clone(),
        final_evals: art.sumcheck.finals.clone(),
    };
    if scp.final_evals.len() != 3 {
        return Err("wire-shape");
    }
    let degrees = matmul_degree_schedule(lk, il.lambda);
    let comb = |kf: &KField, v: &[KElem]| kf.mul(&v[0], &kf.mul(&v[1], &v[2]));
    let sc_v = ixf_sumcheck_verify(&kf, &degrees, &v_claim, &scp, &comb, &mut tv);
    let (pt_v, _c_end) = match sc_v {
        Some(x) => x,
        None => return Err("sumcheck"),
    };
    if scp.final_evals[0] != eq_eval(&kf, &rl_v, &pt_v[lk..]) {
        return Err("eq-final");
    }
    tv.absorb_k(&kf, "mm-final", &scp.final_evals);
    let eq_rx_vt = eq_table(&kf, &rx_v);
    let eq_ry_vt = eq_table(&kf, &ry_v);
    let eq_rl_vt = eq_table(&kf, &rl_v);
    let eq_k_vt = eq_table(&kf, &pt_v[0..lk]);
    let eq_lstar_vt = eq_table(&kf, &pt_v[lk..]);
    let pins_v = bi_mm_pins(
        &kf,
        layers,
        rows,
        inner,
        cols,
        per,
        cms_layer,
        (a_cms, b_cms, c_cms),
        &v_claim,
        &scp.final_evals[1],
        &scp.final_evals[2],
        &eq_rl_vt,
        &eq_rx_vt,
        &eq_ry_vt,
        &eq_k_vt,
        &eq_lstar_vt,
    );
    for p in &pins_v {
        tv.absorb_k(&kf, "mm-pin", std::slice::from_ref(&p.value));
    }
    let psi_v = derive_pin_psi(&tv.state(), UR1_PIN_COPIES, pins_v.len() * ring::kfield::K_DEG, q);
    let claims_v = pin_claims(&kf, &pins_v, cl.n_data, msg_r, &psi_v);
    drop(pins_v);
    let reveals: Vec<Vec<(usize, i64)>> = art
        .reveals
        .iter()
        .map(|rv| rv.iter().map(|&(w, v)| (w as usize, v)).collect())
        .collect();
    let v_split = split_claims_verifier_masked(&zq, &cl.plan, &claims_v, &reveals, &cl.pad_layout);
    let mut vw_claims: Vec<Vec<CtClaim>> = match v_split {
        Ok(v) => v,
        Err(_) => return Err("sum-gate"),
    };
    drop(claims_v);
    if vw_claims.is_empty() {
        vw_claims = (0..n_waves).map(|_| Vec::new()).collect();
    }
    let wave_idxs = |w: usize| -> Vec<usize> {
        let mut v = cl.plan.waves[w].clone();
        if cl.pad_layout.has_pads() {
            v.push(cl.base_pad + w / cl.pad_layout.waves_per_cm);
        }
        let g0 = cl.base_wave_g + w * cl.wave_g_groups;
        v.extend(g0..g0 + cl.wave_g_groups);
        v
    };
    let mut rp_cache: std::collections::BTreeMap<
        usize,
        (ring::ct_engine::CtRoundParams, ring::commit::A1Paths),
    > = std::collections::BTreeMap::new();
    let tv_state = tv.state();
    for w in 0..n_waves {
        let idxs = wave_idxs(w);
        let n_cw = idxs.len();
        if art.waves[w].w1.len() != n_cw {
            return Err("wire-shape");
        }
        if !rp_cache.contains_key(&n_cw) {
            let rp = derive_ct_round_params(q, shape, n_cw, 0, 0, true);
            let a1pw = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cw, (rp, a1pw));
        }
        let (rp_w, a1p_w) = rp_cache.get(&n_cw).unwrap();
        let path_w = KernelPath::A1(a1p_w);
        let claims_w: Vec<CtClaim> = std::mem::take(&mut vw_claims[w]);
        let mut state_v: Vec<u8> = tv_state.to_vec();
        state_v.extend((w as u64).to_le_bytes());
        let wt1s: Vec<Vec<Poly>> = idxs.iter().map(|&i| art.t1s[i].clone()).collect();
        let wt2s: Vec<Vec<Poly>> = idxs.iter().map(|&i| art.t2s[i].clone()).collect();
        let h0_wv = ct_h0(&crs, &state_v, &wt1s, &wt2s, &[]);
        let pad_shift = usize::from(cl.pad_layout.has_pads());
        let proof_w = bi_ct_from_wire(&art.waves[w]);
        let ok_w = verify_ct_round(
            &path_w,
            &ctx_ring,
            rp_w,
            None,
            &crs,
            &h0_wv,
            &claims_w,
            &[],
            &[],
            &[],
            &wt1s,
            &wt2s,
            &[],
            &[],
            &[],
            cl.plan.waves[w].len() + pad_shift,
            &proof_w,
        );
        if !ok_w {
            return Err("wave");
        }
    }
    if cl.pad_layout.has_pads() {
        let proof_z = match &art.closing {
            Some(c) => bi_ct_from_wire(c),
            None => return Err("wire-shape"),
        };
        let idxs_z: Vec<usize> = (cl.base_pad..cl.base_pad + cl.pad_layout.n_pad_cms)
            .chain(cl.base_closing_g..cl.base_closing_g + cl.closing_g_groups)
            .collect();
        let n_cz = idxs_z.len();
        if proof_z.w1.len() != n_cz {
            return Err("wire-shape");
        }
        if !rp_cache.contains_key(&n_cz) {
            let rp = derive_ct_round_params(q, shape, n_cz, 0, 0, true);
            let a1pz = build_a1_paths(&crs, rp.sigma, isqrt_u128(rp.bound_sq));
            rp_cache.insert(n_cz, (rp, a1pz));
        }
        let (rp_z, a1p_z) = rp_cache.get(&n_cz).unwrap();
        let path_z = KernelPath::A1(a1p_z);
        let claims_zv = ring::ct_engine::closing_round_claims(&zq, &cl.pad_layout);
        let mut state_zv: Vec<u8> = tv_state.to_vec();
        state_zv.extend(b"ixf-mm-closing");
        let zt1s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| art.t1s[i].clone()).collect();
        let zt2s: Vec<Vec<Poly>> = idxs_z.iter().map(|&i| art.t2s[i].clone()).collect();
        let h0_zv = ct_h0(&crs, &state_zv, &zt1s, &zt2s, &[]);
        if !verify_ct_round(
            &path_z,
            &ctx_ring,
            rp_z,
            None,
            &crs,
            &h0_zv,
            &claims_zv,
            &[],
            &[],
            &[],
            &zt1s,
            &zt2s,
            &[],
            &[],
            &[],
            cl.pad_layout.n_pad_cms,
            &proof_z,
        ) {
            return Err("closing");
        }
    } else if art.closing.is_some() {
        return Err("wire-shape");
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Serialized-vs-counted accounting (the M-05 table). Counted lines
// replicate the historical conventions EXACTLY (AggCost / MmCost
// formulas); serialized lines are arithmetic mirrors of the spec,
// cross-ASSERTED against the measured encoding length.

fn bi_sint_width(vals: &[i64]) -> usize {
    let mut w = 1usize;
    for &v in vals {
        let need = if (-128..=127).contains(&v) {
            1
        } else if (-32_768..=32_767).contains(&v) {
            2
        } else if (i32::MIN as i64..=i32::MAX as i64).contains(&v) {
            4
        } else {
            8
        };
        w = w.max(need);
    }
    w
}

struct BiLine {
    name: String,
    counted: usize,
    serialized: usize,
}

fn bi_print_table(what: &str, lines: &[BiLine], total_serialized: usize) {
    println!("  serialized vs counted — {what}:");
    println!("    {:<38} {:>14} {:>14}", "component", "counted B", "serialized B");
    let mut ct = 0usize;
    let mut st = 0usize;
    for l in lines {
        println!("    {:<38} {:>14} {:>14}", l.name, l.counted, l.serialized);
        ct += l.counted;
        st += l.serialized;
    }
    println!("    {:<38} {:>14} {:>14}", "TOTAL", ct, st);
    assert_eq!(
        st, total_serialized,
        "serialized component arithmetic must reproduce the measured encoding"
    );
    println!(
        "    serialized/counted = {:.4} ({} B delta)",
        st as f64 / ct as f64,
        st as i64 - ct as i64
    );
}

/// Kind-1 table lines (per the spec's fixed layout arithmetic).
fn bi_eval_table(p: &BiAggProven, encoded: &[u8]) -> Vec<BiLine> {
    let polyb_c = 4 + D * 4; // counted poly incl. its 4 B prefix
    let sc_els = 1 + p.scp.rounds.iter().map(|r| r.len()).sum::<usize>() + p.scp.final_evals.len();
    let sc_ser = 64 + 4
        + p.scp.rounds.iter().map(|r| 4 + r.len() * 64).sum::<usize>()
        + 4
        + p.scp.final_evals.len() * 64;
    let mut lines = vec![
        BiLine {
            name: "statement (manifest bytes)".into(),
            counted: p.statement_bytes.len(),
            serialized: p.statement_bytes.len(),
        },
        BiLine { name: "matmul sumcheck".into(), counted: 64 * sc_els, serialized: sc_ser },
    ];
    let mut overhead_ser = 24 + 5 * 12 + 24; // envelope + 5 section headers + META body
    for (name, proof, tz) in
        [("weight", &p.proof_w, p.tz_w.as_ref()), ("act", &p.proof_a, p.tz_a.as_ref())]
    {
        let b = proof.counted_bytes();
        let outer_ser = 8 + (proof.u0.len() + proof.ugh0.len()) * D * 4;
        let rows_ser = 4 + proof.b_rows.len() * D * 4;
        let lvl_ser = 4 + proof.level_us.iter().map(|u| 4 + u.len() * D * 4).sum::<usize>();
        let flat: Vec<i64> = proof.floor.iter().flatten().copied().collect();
        let w = bi_sint_width(&flat);
        let floor_ser = 5 + flat.len() * w;
        lines.push(BiLine {
            name: format!("[{name}] outer identities"),
            counted: b.outer_identities,
            serialized: outer_ser,
        });
        lines.push(BiLine {
            name: format!("[{name}] claim rows"),
            counted: b.claim_rows,
            serialized: rows_ser,
        });
        lines.push(BiLine {
            name: format!("[{name}] level messages"),
            counted: b.level_msgs,
            serialized: lvl_ser,
        });
        match tz {
            None => {
                lines.push(BiLine {
                    name: format!("[{name}] bare floor"),
                    counted: b.floor,
                    serialized: floor_ser,
                });
            }
            Some(t) => {
                // Counted convention: masked response 4 + coords*4 in the
                // floor slot; images line 4 + n*516 (AggCost tierz_lines).
                lines.push(BiLine {
                    name: format!("[{name}] Tier-Z masked response"),
                    counted: 4 + proof.floor.len() * D * 4,
                    serialized: floor_ser,
                });
                lines.push(BiLine {
                    name: format!("[{name}] Tier-Z mask images"),
                    counted: 4 + t.images.len() * polyb_c,
                    serialized: 4 + t.images.len() * D * 4 + 4, // POLYS + restarts u32
                });
            }
        }
        overhead_ser += 1 + name.len() + 1; // STR + floor_e
    }
    lines.push(BiLine {
        name: "wire envelope + headers + META".into(),
        counted: 0,
        serialized: overhead_ser,
    });
    let _ = encoded;
    lines
}

/// Kind-2 table lines (MmCost conventions vs the spec arithmetic).
fn bi_fold_table(p: &BiFoldProven, encoded: &[u8]) -> Vec<BiLine> {
    let shape = CommitShape { kappa: 8, n_r: 26, msg_r: 8 };
    let n_commits = p.t1s.len();
    let sc_els = 1 + p.scp.rounds.iter().map(|r| r.len()).sum::<usize>() + p.scp.final_evals.len();
    let sc_ser = 64 + 4
        + p.scp.rounds.iter().map(|r| 4 + r.len() * 64).sum::<usize>()
        + 4
        + p.scp.final_evals.len() * 64;
    let n_reveals = p.reveals.iter().map(|r| r.len()).sum::<usize>();
    let reveals_ser = 4 + p.reveals.iter().map(|r| 4 + r.len() * 8).sum::<usize>();
    let mut z_counted = 0usize;
    let mut z_ser = 0usize;
    let mut w1_counted = 0usize;
    let mut w1_ser = 0usize;
    let mut other_counted = 0usize;
    let mut other_ser = 0usize;
    let mut wave_overhead = 4; // n_waves u32
    for c in p.waves.iter().chain(p.closing.iter()) {
        let n_cw = c.z.len();
        z_counted += n_cw * shape.n_r * D * 8;
        let flat: Vec<i64> = c.z.iter().flatten().flatten().copied().collect();
        z_ser += 5 + flat.len() * bi_sint_width(&flat);
        w1_counted += n_cw * shape.kappa * D * 4;
        w1_ser += 4 + n_cw * shape.kappa * D * 4; // n_cw u32 + polys
        other_counted += c.h.len() * D * 4 * 2;
        other_ser += (4 + c.h.len() * D * 4) + (4 + c.w_claim.len() * D * 4);
    }
    wave_overhead += 1; // closing presence byte
    let lines = vec![
        BiLine {
            name: "statement (manifest bytes)".into(),
            counted: p.statement_bytes.len(),
            serialized: p.statement_bytes.len(),
        },
        BiLine {
            name: "commitment tags t1+t2".into(),
            counted: n_commits * (shape.kappa + shape.msg_r) * D * 4,
            serialized: 4 + n_commits * (shape.kappa + shape.msg_r) * D * 4,
        },
        BiLine { name: "folded sumcheck".into(), counted: 64 * sc_els, serialized: sc_ser },
        BiLine { name: "masked share reveals".into(), counted: 12 * n_reveals, serialized: reveals_ser },
        BiLine { name: "ct-round z responses".into(), counted: z_counted, serialized: z_ser },
        BiLine { name: "ct-round w1 images".into(), counted: w1_counted, serialized: w1_ser },
        BiLine { name: "ct-round h + w_claim".into(), counted: other_counted, serialized: other_ser },
        BiLine {
            name: "wire envelope + headers + META".into(),
            counted: 0,
            serialized: 24 + 7 * 12 + 29 + wave_overhead,
        },
    ];
    let _ = encoded;
    lines
}

// ---------------------------------------------------------------------------
// The wire battery (`uagb1-bi wire-battery`) — round trips, verify-
// after-round-trip, corruption legs both classes, kinds 1-4.

fn bi_corrupt(bytes: &[u8], pos: usize, mask: u8) -> Vec<u8> {
    let mut v = bytes.to_vec();
    v[pos] ^= mask;
    v
}

/// Byte offset of section `idx`'s body inside an encoded artifact.
fn bi_section_body_offset(bytes: &[u8], idx: usize) -> usize {
    let sizes = wire::section_sizes(bytes).expect("well-formed artifact");
    let mut off = 24usize;
    for (i, (_, len)) in sizes.iter().enumerate() {
        off += 12;
        if i == idx {
            return off;
        }
        off += *len as usize;
    }
    panic!("section index out of range");
}

fn bi_wire_battery(light: bool) {
    use wire::WireError;
    println!(
        "\n[UAGB1-BI] ZKWF v1 wire battery (round trips, verify-after-round-trip, corruption legs){}",
        if light { " — light face (Tier-Z leg runs in the full battery)" } else { "" }
    );

    // ---- Golden sample: canonicality + structural corruption. ----
    {
        let g = wire::golden_sample_kind1();
        let bytes = wire::encode_eval_artifact(&g);
        let dec = wire::decode_eval_artifact(&bytes).expect("golden decodes");
        assert_true("golden: decode reproduces the artifact", dec == g);
        assert_true(
            "golden: re-encode is byte-identical",
            wire::encode_eval_artifact(&dec) == bytes,
        );
        println!(
            "       golden bytes {} | sha {}",
            bytes.len(),
            hex_prefix(&uk8_sha(&[&bytes]))
        );
        let legs: Vec<(&str, Vec<u8>, Option<WireError>)> = vec![
            ("magic byte", bi_corrupt(&bytes, 0, 0x01), Some(WireError::BadMagic)),
            ("format version", bi_corrupt(&bytes, 8, 0x02), None),
            ("artifact kind", bi_corrupt(&bytes, 12, 0x04), None),
            ("field id", bi_corrupt(&bytes, 14, 0x01), None),
            ("reserved byte", bi_corrupt(&bytes, 15, 0x80), Some(WireError::ReservedNonzero)),
            ("payload length", bi_corrupt(&bytes, 16, 0x01), None),
            ("section tag", bi_corrupt(&bytes, 24, 0x01), None),
            ("section length", bi_corrupt(&bytes, 28, 0x01), None),
            ("truncated", bytes[..bytes.len() - 1].to_vec(), None),
            ("trailing byte", {
                let mut v = bytes.clone();
                v.push(0);
                v
            }, Some(WireError::TrailingBytes)),
        ];
        for (name, mutated, want) in legs {
            let r = wire::decode_eval_artifact(&mutated);
            let ok = match (&r, &want) {
                (Err(e), Some(w)) => e == w,
                (Err(_), None) => true,
                (Ok(_), _) => false,
            };
            assert_true(&format!("golden structural corruption REJECTS cleanly: {name}"), ok);
        }
        // A poly coefficient pushed out of canonical range (the u32
        // high byte of the first u0 coefficient of group 'weight').
        let g0_off = bi_section_body_offset(&bytes, 3); // META, STMT, SC, GROUP0
        let coeff0 = g0_off + 1 + 6 + 4; // STR "weight" + POLYS count
        let hi = bi_corrupt(&bytes, coeff0 + 3, 0x80);
        assert_true(
            "golden value corruption: coefficient >= q REJECTS (CoeffRange)",
            wire::decode_eval_artifact(&hi) == Err(WireError::CoeffRange),
        );
        // Non-canonical SINT width: the floor block of group 'weight'
        // holds w=1 digits; force the width byte to 2.
        let floor_w_off = {
            let name = 1 + 6;
            let u0 = 4 + 11 * D * 4;
            let ugh0 = 4 + 11 * D * 4;
            let brows = 4 + 16 * D * 4;
            let levels = 4 + (4 + 11 * D * 4);
            g0_off + name + u0 + ugh0 + brows + levels + 1 + 4
        };
        let mut wid = bytes.clone();
        assert_eq!(wid[floor_w_off], 1, "golden floor block is w = 1");
        wid[floor_w_off] = 2;
        assert_true(
            "golden width corruption: non-minimal SINT width REJECTS",
            matches!(
                wire::decode_eval_artifact(&wid),
                Err(WireError::NonCanonicalWidth) | Err(WireError::Truncated)
            ),
        );
    }

    // ---- Kind 1, degenerate schedule (forced 0 levels). ----
    let small = bi_agg_prove(64, 96, 128, false, Some(0), 0xB1_5001);
    {
        let art = bi_agg_to_wire(&small);
        let bytes = wire::encode_eval_artifact(&art);
        let dec = wire::decode_eval_artifact(&bytes).expect("kind-1 degenerate decodes");
        assert_true(
            "kind-1 degenerate: re-encode byte-identical",
            wire::encode_eval_artifact(&dec) == bytes,
        );
        assert_true(
            "kind-1 degenerate: verify-after-round-trip ACCEPTS",
            bi_agg_verify_wire(&dec, 64, 96, 128, false, Some(0)).is_ok(),
        );
        // Value corruption inside the weight floor (in-range digit
        // change): decode OK, verify REJECTS.
        let g0_off = bi_section_body_offset(&bytes, 3);
        let floor_data = {
            let name = 1 + 6;
            let u0 = 4 + small.proof_w.u0.len() * D * 4;
            let ugh0 = 4 + small.proof_w.ugh0.len() * D * 4;
            let brows = 4 + small.proof_w.b_rows.len() * D * 4;
            let levels = 4;
            g0_off + name + u0 + ugh0 + brows + levels + 1 + 5
        };
        let tampered = bi_corrupt(&bytes, floor_data, 0x01);
        match wire::decode_eval_artifact(&tampered) {
            Ok(dec_t) => {
                let v = bi_agg_verify_wire(&dec_t, 64, 96, 128, false, Some(0));
                assert_true(
                    &format!(
                        "kind-1 degenerate: floor value corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => assert_true(
                &format!("kind-1 degenerate: floor value corruption rejected at decode ({e})"),
                true,
            ),
        }
        // Claim-row corruption (non-ct coefficient): decode OK (still
        // canonical), verify REJECTS via the claim-row evaluation.
        let brow_data = {
            let name = 1 + 6;
            let u0 = 4 + small.proof_w.u0.len() * D * 4;
            let ugh0 = 4 + small.proof_w.ugh0.len() * D * 4;
            g0_off + name + u0 + ugh0 + 4 + 4
        };
        let tampered = bi_corrupt(&bytes, brow_data, 0x01);
        match wire::decode_eval_artifact(&tampered) {
            Ok(dec_t) => {
                let v = bi_agg_verify_wire(&dec_t, 64, 96, 128, false, Some(0));
                assert_true(
                    &format!(
                        "kind-1 degenerate: claim-row corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => assert_true(
                &format!("kind-1 degenerate: claim-row corruption rejected at decode ({e})"),
                true,
            ),
        }
        // META corruption: the expect gate rejects before any planner.
        let meta_off = bi_section_body_offset(&bytes, 0);
        let tampered = bi_corrupt(&bytes, meta_off, 0x40);
        match wire::decode_eval_artifact(&tampered) {
            Ok(dec_t) => assert_true(
                "kind-1 degenerate: META corruption REJECTS at the expect gate",
                bi_agg_verify_wire(&dec_t, 64, 96, 128, false, Some(0)) == Err("meta-mismatch"),
            ),
            Err(_) => assert_true("kind-1 degenerate: META corruption rejected at decode", true),
        }
        // Cross-kind: the artifact must not decode as a fold transcript.
        assert_true(
            "kind gate: a kind-1 artifact refuses to decode as kind-2",
            wire::decode_fold_transcript(&bytes) == Err(WireError::BadKind(wire::KIND_EVAL_PROOF)),
        );
    }

    // ---- Kind 1, recursed schedule (forced 2 levels). ----
    {
        let p = bi_agg_prove(64, 96, 128, false, Some(2), 0xB1_5002);
        let art = bi_agg_to_wire(&p);
        let bytes = wire::encode_eval_artifact(&art);
        let dec = wire::decode_eval_artifact(&bytes).expect("kind-1 recursed decodes");
        assert_true(
            "kind-1 recursed: re-encode byte-identical",
            wire::encode_eval_artifact(&dec) == bytes,
        );
        assert_true(
            "kind-1 recursed: verify-after-round-trip ACCEPTS",
            bi_agg_verify_wire(&dec, 64, 96, 128, false, Some(2)).is_ok(),
        );
        // Level-message corruption: transported chain REJECTS.
        let g1_off = bi_section_body_offset(&bytes, 4); // act group
        let lvl_data = {
            let name = 1 + 3;
            let u0 = 4 + p.proof_a.u0.len() * D * 4;
            let ugh0 = 4 + p.proof_a.ugh0.len() * D * 4;
            let brows = 4 + p.proof_a.b_rows.len() * D * 4;
            g1_off + name + u0 + ugh0 + brows + 4 + 4
        };
        let tampered = bi_corrupt(&bytes, lvl_data, 0x01);
        match wire::decode_eval_artifact(&tampered) {
            Ok(dec_t) => {
                let v = bi_agg_verify_wire(&dec_t, 64, 96, 128, false, Some(2));
                assert_true(
                    &format!(
                        "kind-1 recursed: level-message corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => assert_true(
                &format!("kind-1 recursed: level-message corruption rejected at decode ({e})"),
                true,
            ),
        }
    }

    // ---- Kind 1, Tier-Z at the smallest corner-surviving shape. ----
    if !light {
        let p = bi_agg_prove(256, 768, 2048, true, None, 0xB1_5003);
        let art = bi_agg_to_wire(&p);
        let bytes = wire::encode_eval_artifact(&art);
        let dec = wire::decode_eval_artifact(&bytes).expect("kind-1 tier-z decodes");
        assert_true(
            "kind-1 Tier-Z: re-encode byte-identical",
            wire::encode_eval_artifact(&dec) == bytes,
        );
        assert_true(
            "kind-1 Tier-Z: verify-after-round-trip ACCEPTS",
            bi_agg_verify_wire(&dec, 256, 768, 2048, true, None).is_ok(),
        );
        // Response corruption (in-range): the family equations REJECT.
        let g0_off = bi_section_body_offset(&bytes, 3);
        let resp_data = {
            let name = 1 + 6;
            let u0 = 4 + p.proof_w.u0.len() * D * 4;
            let ugh0 = 4 + p.proof_w.ugh0.len() * D * 4;
            let brows = 4 + p.proof_w.b_rows.len() * D * 4;
            let levels = 4 + p.proof_w.level_us.iter().map(|u| 4 + u.len() * D * 4).sum::<usize>();
            g0_off + name + u0 + ugh0 + brows + levels + 1 + 5
        };
        let tampered = bi_corrupt(&bytes, resp_data, 0x01);
        match wire::decode_eval_artifact(&tampered) {
            Ok(dec_t) => {
                let v = bi_agg_verify_wire(&dec_t, 256, 768, 2048, true, None);
                assert_true(
                    &format!(
                        "kind-1 Tier-Z: response corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => assert_true(
                &format!("kind-1 Tier-Z: response corruption rejected at decode ({e})"),
                true,
            ),
        }
        let lines = bi_eval_table(&p, &bytes);
        bi_print_table("Tier-Z eval proof at 256x768x2048", &lines, bytes.len());
    }

    // ---- Kind 2: the joint-matmul fold at the BE battery shape. ----
    {
        let p = bi_fold_prove(12, 64, 96, 128, 0xB1_5004);
        let art = bi_fold_to_wire(&p);
        let bytes = wire::encode_fold_transcript(&art);
        let dec = wire::decode_fold_transcript(&bytes).expect("kind-2 decodes");
        assert_true(
            "kind-2 mm fold: re-encode byte-identical",
            wire::encode_fold_transcript(&dec) == bytes,
        );
        assert_true(
            "kind-2 mm fold: verify-after-round-trip ACCEPTS",
            bi_fold_verify_wire(&dec, 12, 64, 96, 128).is_ok(),
        );
        // Tag corruption: the rebuilt statement digest gate REJECTS.
        let tags_off = bi_section_body_offset(&bytes, 2);
        let tampered = bi_corrupt(&bytes, tags_off + 4, 0x01);
        match wire::decode_fold_transcript(&tampered) {
            Ok(dec_t) => assert_true(
                "kind-2: tag corruption decodes, statement-digest gate REJECTS",
                bi_fold_verify_wire(&dec_t, 12, 64, 96, 128) == Err("statement-digest"),
            ),
            Err(e) => {
                assert_true(&format!("kind-2: tag corruption rejected at decode ({e})"), true)
            }
        }
        // z-response corruption inside wave 0: the wave REJECTS.
        let waves_off = bi_section_body_offset(&bytes, 5);
        let z_data = {
            let c = &p.waves[0];
            let h = 4 + c.h.len() * D * 4;
            let w1 = 4 + c.w1.len() * 8 * D * 4;
            let wc = 4 + c.w_claim.len() * D * 4;
            waves_off + 4 + h + w1 + wc + 5
        };
        let tampered = bi_corrupt(&bytes, z_data, 0x01);
        match wire::decode_fold_transcript(&tampered) {
            Ok(dec_t) => {
                let v = bi_fold_verify_wire(&dec_t, 12, 64, 96, 128);
                assert_true(
                    &format!(
                        "kind-2: wave z corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => {
                assert_true(&format!("kind-2: wave z corruption rejected at decode ({e})"), true)
            }
        }
        // Reveal corruption: the masked-split sum gate REJECTS.
        let rev_off = bi_section_body_offset(&bytes, 4);
        let tampered = bi_corrupt(&bytes, rev_off + 4 + 4 + 4, 0x01);
        match wire::decode_fold_transcript(&tampered) {
            Ok(dec_t) => {
                let v = bi_fold_verify_wire(&dec_t, 12, 64, 96, 128);
                assert_true(
                    &format!(
                        "kind-2: reveal corruption decodes, verify REJECTS ({})",
                        v.err().unwrap_or("?")
                    ),
                    v.is_err(),
                );
            }
            Err(e) => {
                assert_true(&format!("kind-2: reveal corruption rejected at decode ({e})"), true)
            }
        }
        let lines = bi_fold_table(&p, &bytes);
        bi_print_table("12x(64x96x128) mm fold transcript", &lines, bytes.len());
    }

    // ---- Kind 3: statement wraps, digest stability, pairing. ----
    {
        // v3: the aggregation statement at the battery shape (synthetic
        // u0 digests — the wrap is about BYTES, not about this
        // statement's provenance).
        let (mut gw, mut ga, _) = agg_build_groups(64, 96, 128);
        gw.begin_opening().unwrap();
        ga.begin_opening().unwrap();
        let descs = vec![agg_group_descriptor(&gw, false), agg_group_descriptor(&ga, false)];
        let u0d = vec![vec![0xAAu8; 32], vec![0xBBu8; 32]];
        let st3 = agg_build_statement(64, 96, 128, mm_acc_bits(96), &descs, &u0d, b"agg-crs-v1");
        let d3_before = st3.digest().expect("v3 digests");
        let wrap = wire::WireStatementWrap { version: 3, statement: st3.encode() };
        let bytes = wire::encode_statement_wrap(&wrap);
        let dec = wire::decode_statement_wrap(&bytes).expect("v3 wrap decodes");
        assert_true(
            "kind-3 v3: re-encode byte-identical",
            wire::encode_statement_wrap(&dec) == bytes,
        );
        let st3_rt = manifest::Statement::decode(&dec.statement).expect("v3 re-decodes");
        assert_true(
            "kind-3 v3: manifest bytes verbatim + digest UNMOVED through the wire",
            st3_rt.encode() == wrap.statement && st3_rt.digest().unwrap() == d3_before,
        );
        // v4: the manifest codec sample.
        let st4 = manifest::codec_sample_statement_v4();
        let d4_before = st4.digest().expect("v4 digests");
        let wrap4 = wire::WireStatementWrap { version: 4, statement: st4.encode() };
        let bytes4 = wire::encode_statement_wrap(&wrap4);
        let dec4 = wire::decode_statement_wrap(&bytes4).expect("v4 wrap decodes");
        let st4_rt = manifest::Statement::decode(&dec4.statement).expect("v4 re-decodes");
        assert_true(
            "kind-3 v4: manifest bytes verbatim + digest UNMOVED through the wire",
            st4_rt.encode() == wrap4.statement && st4_rt.digest().unwrap() == d4_before,
        );
        // Pairing negatives, both directions.
        let bad34 = wire::WireStatementWrap { version: 4, statement: st3.encode() };
        assert_true(
            "kind-3 pairing: v3 bytes under a version-4 wrap REJECT",
            wire::decode_statement_wrap(&wire::encode_statement_wrap(&bad34))
                == Err(WireError::BadPairing),
        );
        let bad43 = wire::WireStatementWrap { version: 3, statement: st4.encode() };
        assert_true(
            "kind-3 pairing: v4 bytes under a version-3 wrap REJECT",
            wire::decode_statement_wrap(&wire::encode_statement_wrap(&bad43))
                == Err(WireError::BadPairing),
        );
    }

    // ---- Kind 4: the pass-artifact writer API (BG's target). ----
    {
        let st4 = manifest::codec_sample_statement_v4();
        let group = bi_group_to_wire("weight", &small.proof_w, None);
        let fold_sc = wire::WireSumcheck {
            v_claim: small.v_claim.clone(),
            rounds: small.scp.rounds.clone(),
            finals: small.scp.final_evals.clone(),
        };
        let mut wtr = wire::PassArtifactWriter::new(2, 12, st4.encode());
        wtr.add_group_eval(0, group)
            .add_fold_claim(1, fold_sc, vec![small.v_claim.clone()])
            .add_raw(0x0001, b"bg-extension-space".to_vec());
        let bytes = wtr.finish();
        let dec = wire::decode_pass_artifact(&bytes).expect("kind-4 decodes");
        assert_true(
            "kind-4 pass artifact: re-encode byte-identical (writer is canonical)",
            wire::encode_pass_artifact(&dec) == bytes,
        );
        assert_true(
            "kind-4: mode/layers/raw sections preserved exactly",
            dec.mode == 2
                && dec.layers == 12
                && dec.raw == vec![(0x0001u16, b"bg-extension-space".to_vec())],
        );
        // Mode corruption REJECTS.
        let meta_off = bi_section_body_offset(&bytes, 0);
        let tampered = bi_corrupt(&bytes, meta_off, 0x04);
        assert_true(
            "kind-4: mode byte corruption REJECTS (ValueRange)",
            wire::decode_pass_artifact(&tampered) == Err(WireError::ValueRange),
        );
    }
}

